-- The regulations book: 1146 clauses, MS2627 Rev.01, Section D excluded (eFuel).
-- clause_key is unique; printed_ref is what the book prints. They differ for
-- E.5.4.5 and F.5.2.3, which the Organization numbered twice. Show printed_ref.
insert into clauses (clause_key, printed_ref, section, article, article_title, group_title, subteam_key, body, obligation, criticality, phase, milestone_key, is_team_duty, specs) values
  ('A.1.1.1', 'A.1.1.1', 'A', 1, 'Introduction To Motostudent Competition', null, 'ADMIN', 'MotoStudent is an international academic challenge aimed at student teams from higher education institutions. For the purposes of this Competition, higher education institutions include universities, polytechnic institutes, technical colleges, and vocational training institutions providing post-secondary education. Teams must design and develop a competition motorbike project (Electric or eFuel), which will be evaluated throughout the different milestones of the Competition and tested in a Final Event to be held at the MotorLand Aragón facilities in Alcañiz (Teruel), Spain.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.1.2', 'A.1.1.2', 'A', 1, 'Introduction To Motostudent Competition', null, 'ADMIN', 'MotoStudent is an advanced multidisciplinary educational program designed to develop technical, managerial and innovative talent among undergraduate and graduate students. Through a real motorsport challenge, participants conceive, design, develop and manufacture a competition motorbike project (Electric or eFuel), applying engineering knowledge, strategic thinking and professional standards within an international competitive environment. Throughout the different phases of the competition, teams strengthen and demonstrate their capabilities in areas including:
- Project management, with emphasis on economic planning, budget control, marketing strategy, resource management, technical documentation and milestone execution.
- The design, development and manufacturing of a real competition prototype under defined regulations, with particular focus on innovation, technical rigor and performance.
- Competitive mindset, teamwork, leadership and international collaboration with student teams from higher education institutions worldwide.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.2.1', 'A.1.2.1', 'A', 1, 'Introduction To Motostudent Competition', 'Event Promoter and Organization', 'ADMIN', 'The MotoStudent International Competition is promoted and organized by the Moto Engineering Foundation (hereinafter “MEF”) together with TechnoPark MotorLand. Both entities constitute the official Competition Organization and are jointly responsible for the planning, coordination, management and full development of the Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.2.2', 'A.1.2.2', 'A', 1, 'Introduction To Motostudent Competition', 'Event Promoter and Organization', 'ADMIN', 'The Competition Organization holds the authority to interpret, adapt and modify the Competition Rules & Regulations, the official calendar and any other official document whenever deemed necessary for the proper development, safety or integrity of the Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.2.3', 'A.1.2.3', 'A', 1, 'Introduction To Motostudent Competition', 'Event Promoter and Organization', 'ADMIN', 'Any modification will be duly communicated to the participating teams through the official communication channels of the Competition. The version of the Competition Rules & Regulations published on the official website shall always be considered the only valid and binding version.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.3.1', 'A.1.3.1', 'A', 1, 'Introduction To Motostudent Competition', 'Competition Categories', 'ADMIN', 'The MotoStudent International Competition is structured into two distinct and independent categories:
- MotoStudent eFuel
- MotoStudent Electric', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.3.2', 'A.1.3.2', 'A', 1, 'Introduction To Motostudent Competition', 'Competition Categories', 'ADMIN', 'The MotoStudent eFuel category involves prototypes powered exclusively by an internal combustion engine operating with the designated competition fuel, in accordance with the technical requirements established in these Competition Rules & Regulations.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.3.3', 'A.1.3.3', 'A', 1, 'Introduction To Motostudent Competition', 'Competition Categories', 'ADMIN', 'The MotoStudent Electric category involves prototypes powered exclusively by an electric propulsion system, in accordance with the technical requirements established in these Competition Rules & Regulations.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.3.4', 'A.1.3.4', 'A', 1, 'Introduction To Motostudent Competition', 'Competition Categories', 'ADMIN', 'Each category will be conducted in parallel and independently, with its own classification, evaluation process, scoring system, tests and milestones throughout all phases of the Competition, including the Final Event.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.4.1', 'A.1.4.1', 'A', 1, 'Introduction To Motostudent Competition', 'Phases of the Competition', 'ADMIN', 'The Competition is structured into two distinct and sequential phases: MS1 and MS2. During these phases, the projects and prototypes presented by the teams will be evaluated through a series of defined tests and assessments.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.4.2', 'A.1.4.2', 'A', 1, 'Introduction To Motostudent Competition', 'Phases of the Competition', 'ADMIN', 'MS1 is the evaluation phase focused on engineering, management and organizational capabilities. It assesses the teams’ capacity to conceive, plan, develop and validate a competitive real-world project in accordance with the Competition Rules & Regulations. The evaluation emphasizes efficiency, innovation and effective use of available resources.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.4.3', 'A.1.4.3', 'A', 1, 'Introduction To Motostudent Competition', 'Phases of the Competition', 'ADMIN', 'MS2 is the dynamic and performance phase, consisting of a series of technical and on-track tests aimed at assessing the safety, functionality and performance of the manufactured prototype under competitive conditions.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.4.4', 'A.1.4.4', 'A', 1, 'Introduction To Motostudent Competition', 'Phases of the Competition', 'ADMIN', 'Access to any phase or stage of the Competition shall be conditional upon compliance with the requirements, mandatory deliverables and minimum criteria established for that phase, as defined in these Competition Rules & Regulations. Failure to meet such requirements may result in restriction or denial of access to subsequent phases.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.1.4.5', 'A.1.4.5', 'A', 1, 'Introduction To Motostudent Competition', 'Phases of the Competition', 'ADMIN', 'Non-compliance with the Competition Rules & Regulations at any stage of the Competition may result in penalties in accordance with the applicable provisions. The Competition Organization reserves the authority to take any necessary decision to safeguard the safety, integrity and proper development of the Competition.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.1.4.6', 'A.1.4.6', 'A', 1, 'Introduction To Motostudent Competition', 'Phases of the Competition', 'ADMIN', 'Safety constitutes a fundamental principle of the MotoStudent International Competition’s mission. All participants, officials and stakeholders are required to prioritize safety in the design, development and operation of their projects, in accordance with the standards and requirements established in these Competition Rules & Regulations.', 'admin', 'info', 'registration', null, true, '[]'::jsonb),
  ('A.1.5.1', 'A.1.5.1', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'Awards will be granted independently in each category (MotoStudent eFuel and MotoStudent Electric) in accordance with the results obtained during the Competition, except where expressly stated otherwise.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.5.2', 'A.1.5.2', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'MS1 Phase Awards The following awards will be granted in each category based on the evaluation results of the MS1 phase:
- Best MS1
- Best Design
- Best Innovation', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.5.3', 'A.1.5.3', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'MS2 Phase Awards The following awards will be granted in each category based on the official classification of the MS2 phase:
- 1st Classified of the MS2 Phase
- 2nd Classified of the MS2 Phase
- 3rd Classified of the MS2 Phase', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.5.4', 'A.1.5.4', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'Overall Category Awards The following awards will be granted in each category based on the combined results of MS1 and MS2:
- Best MotoStudent: awarded to the team obtaining the highest total score from the combined results of MS1 and MS2.
- Best MotoStudent Rookie: awarded to the highest-ranked eligible team, based on the combined results of MS1 and MS2, representing an institution that has never previously participated in any past edition of the MotoStudent Competition. For the purposes of this award, eligibility shall be determined at institutional level. The Competition Organization reserves the right to verify institutional continuity in order to prevent artificial reclassification of teams.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.5.5', 'A.1.5.5', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'Special Nominations In addition to the category-based awards, the following Special Nominations may be granted by the Competition Organization:
- MotoStudent Fair Play nomination: granted to the team demonstrating exemplary integrity, respect and professional conduct throughout all phases of the Competition.
- MotoStudent Media Hero nomination: granted to the team demonstrating outstanding communication, media engagement and public outreach during the Competition.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.1.5.6', 'A.1.5.6', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'Summary of the MotoStudent International Competition Awards A summary of the awards structure is provided in Table 1 for reference purposes only: MotoStudent eFuel MotoStudent Electric MS1 Phase Awards Best MS1 Best MS1 Best Design Best Innovation Best Design Best Innovation MS2 Phase Awards 1st classified 1st classified 2nd classified 3rd classified 2nd classified 3rd classified Overall Category Awards Best MotoStudent Best MotoStudent Best Rookie Team Best Rookie Team Special Nomination MotoStudent Fair Play MotoStudent Media Hero Table 1 - MotoStudent awards summary', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.5.7', 'A.1.5.7', 'A', 1, 'Introduction To Motostudent Competition', 'Awards', 'ADMIN', 'The economic and/or material value of any award will be communicated by the Competition Organization through the official communication channels to all registered teams.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.6.1', 'A.1.6.1', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'MotoStudent is open to student teams officially representing universities worldwide. Participating universities may collaborate with officially accredited vocational training institutions or other equivalent academic entities. However, the representing university shall remain the sole institutional counterpart before the Competition Organization. Participation must be officially endorsed by the representing university.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.2', 'A.1.6.2', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'The registration period for the IX Edition of the MotoStudent International Competition will open on 20/04/2026 and shall be formalized exclusively through the official website of the Competition: www.motostudent.com. All applicable deadlines will be published through the official communication channels of the Competition.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.1.6.3', 'A.1.6.3', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'Registration and participation in the Competition shall be conditional upon full payment of the participation fee. For the IX Edition, the participation fee per team amounts to € 4,550 (VAT included). No registration shall be considered valid until full payment of the participation fee has been received by the Competition Organization. The participation fee corresponds to the right to participate in the MotoStudent Competition and to access the elements, services and opportunities associated with the current edition. It shall not be interpreted as the purchase price of any specific component of the MotoStudent Kit.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.4', 'A.1.6.4', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'Team registration includes:
- The right to participate as an official team in the IX Edition of the MotoStudent International Competition.
- The right to use the official MotoStudent Kit during the current edition, including the mandatory common components to be installed in the prototype. Shipping costs of the MotoStudent Kit are included. Customs duties, import taxes or any similar charges applicable in the destination country shall not be included.
- Registration for up to ten (10) students (nine Team Members and one Team Leader) and two (2) Team Tutors to participate at the current edition.
- Access to the Competition phases, evaluations, official activities and Final Event.
- Access to official challenges, partner initiatives and opportunities offered by the Competition Organization and collaborating entities.
- Access to services, supplies, discounts and opportunities made available by the Competition Organization and its collaborating entities within the framework of the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.5', 'A.1.6.5', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'The fee for adding additional Team Members slots amounts to € 240 (VAT included). Additional Team Members may be registered until 30 days before the first day of the Final Event. Requests to purchase additional Team Member slots must be made through the MotoStudent website, either during the initial team registration process or after the team has been registered, through the Store section in the team’s private area.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.6', 'A.1.6.6', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'Registration as a Team Member includes:
- Passes for the Final Event, with exclusive access to areas designated for Team Members.
- The right to receive a certificate validating participation in the current edition of the International MotoStudent Competition.
- Access to specialized on-site or online training courses via the MotoStudent Platform, including the corresponding official certificate and possible discounts.
- Access to the MotoStudent Talent Roadshow to stay informed about job opportunities with leading mobility companies.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.6.7', 'A.1.6.7', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'The fee for adding additional Team Tutor slots amounts to € 115 (VAT included). Additional Team Tutors may be registered until 30 days before the first day of the Final Event. Requests to purchase additional Team Tutor slots must be made through the MotoStudent website, either during the initial team registration process or after the team has been registered, through the Store section in the team’s private area.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.8', 'A.1.6.8', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'Registration as a Team Tutor includes:
- Passes for the Final Event, with exclusive access to areas designated for Team Members.
- The right to receive a certificate validating participation in the current edition of the International MotoStudent Competition.
- Access to specialized on-site or online training courses via the MotoStudent Platform, including the corresponding official certificate.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.6.9', 'A.1.6.9', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'All Team Members and Team Tutors must be registered through the MotoStudent Platform once the team registration has been completed and confirmed by the Competition Organization. Individual registration of Team Members and Team Tutors shall only be possible after the team has been officially registered. The complete registration process is described in Annex 5.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.10', 'A.1.6.10', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'A team, Team Member, Team Leader or Team Tutor shall only be considered registered upon receipt of official confirmation issued by the Competition Organization via email or any other electronic means.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.11', 'A.1.6.11', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'The Competition Organization reserves the right to deny the registration of any team, Team Member or Team Tutor.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.6.12', 'A.1.6.12', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'The number of available team entries is limited. Entries shall be confirmed in order of registration. Teams that have not completed payment of the applicable fees shall not be considered registered and shall not be entitled to reserve a place in the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.6.13', 'A.1.6.13', 'A', 1, 'Introduction To Motostudent Competition', 'Entries and Participation', 'ADMIN', 'Entry fees are non-refundable. Once a team member / tutor has been registered through the MotoStudent Platform, this team slot is blocked and can´t be modify. In the event of interruption, cancellation, or modification of the Competition schedule or format (including changes to the dates of the Final Event) due to circumstances beyond the control of the Competition Organization, the Organization shall not be obliged to refund the registration fees, whether partially or in full.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.7.1', 'A.1.7.1', 'A', 1, 'Introduction To Motostudent Competition', 'Official Publications and Final Event Information', 'ADMIN', 'All official communications, regulations, annexes and related documents will be published on the official website of the Competition: www.motostudent.com', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.7.2', 'A.1.7.2', 'A', 1, 'Introduction To Motostudent Competition', 'Official Publications and Final Event Information', 'ADMIN', 'Teams are required to read, understand and remain familiar with all official publications issued by the Competition Organization.', 'admin', 'info', 'registration', null, true, '[]'::jsonb),
  ('A.1.7.3', 'A.1.7.3', 'A', 1, 'Introduction To Motostudent Competition', 'Official Publications and Final Event Information', 'ADMIN', 'The Competition Organization may use email, private messaging within the MotoStudent Platform, or any other electronic means to distribute official information regarding the Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.7.4', 'A.1.7.4', 'A', 1, 'Introduction To Motostudent Competition', 'Official Publications and Final Event Information', 'ADMIN', 'Any official communication issued by the Competition Organization shall be binding within their scope. Clarifications and interpretations may be communicated through the official channels of the Competition. Any modification of the Competition Rules & Regulations or of the applicable technical or sporting requirements shall be formalized through the corresponding official amendment, Technical Note or updated version of the applicable document.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.1.7.5', 'A.1.7.5', 'A', 1, 'Introduction To Motostudent Competition', 'Official Publications and Final Event Information', 'ADMIN', 'The Competition Organization reserves the right to designate additional communication channels as official, provided that prior notice is given to the teams.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.1.8.1', 'A.1.8.1', 'A', 1, 'Introduction To Motostudent Competition', 'Official Languages', 'ADMIN', 'The official languages of the MotoStudent International Competition shall be:
- English
- Spanish', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.1.8.2', 'A.1.8.2', 'A', 1, 'Introduction To Motostudent Competition', 'Official Languages', 'ADMIN', 'Official publications and documents shall be issued in English.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.1.8.3', 'A.1.8.3', 'A', 1, 'Introduction To Motostudent Competition', 'Official Languages', 'ADMIN', 'All communications between participating teams and the Competition Organization shall be conducted in one of the official languages.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.1.9.1', 'A.1.9.1', 'A', 1, 'Introduction To Motostudent Competition', 'Official Time', 'ADMIN', 'The official time of the MotoStudent International Competition shall be the time in force in mainland Spain:
- Winter Time: CET (UTC+1)
- Summer Time: CEST (UTC+2)', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.1.1', 'A.2.1.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Ambiguities in the Regulations', 'ADMIN', 'Any ambiguity, interpretation issue or question regarding the meaning or intent of these Competition Rules & Regulations shall be resolved exclusively by the Competition Organization.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.1.2', 'A.2.1.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Ambiguities in the Regulations', 'ADMIN', 'Any matter not expressly permitted by these Competition Rules & Regulations shall be considered prohibited. Teams may submit a formal request for clarification or authorization to the Competition Organization. The corresponding decision will be communicated to all teams through an official communication.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.2.2.1', 'A.2.2.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Validity of the Regulations', 'ADMIN', 'The Competition Rules & Regulations of the MotoStudent International Competition published on the official website www.motostudent.com, including any subsequent official amendments or revisions, shall constitute the only valid regulatory framework for the current edition of the MotoStudent International Competition.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.2.2', 'A.2.2.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Validity of the Regulations', 'ADMIN', 'Regulations from any previous edition shall not apply to the current edition of the MotoStudent International Competition.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.2.3', 'A.2.2.3', 'A', 2, 'Application Of The Motostudent Regulations', 'Validity of the Regulations', 'ADMIN', 'In the event of any sporting situation or infraction not expressly covered by these Competition Rules & Regulations or by any official communication issued by the Competition Organization, the RFME Sporting Regulations of the Spanish Speed Championship (ESBK) 2026 shall apply for procedural purposes.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.3.1', 'A.2.3.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Compliance with the Regulations', 'ADMIN', 'By taking part in the MotoStudent International Competition, the team, Team Members, Team Leader, Team Tutors, Riders and any other university staff members, in their individual capacity, accept and shall comply with all rules established by the Competition Organization, including these Competition Rules & Regulations, subsequent official communications, and the rules of the sports complex where the Final Event takes place.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.2.3.2', 'A.2.3.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Compliance with the Regulations', 'ADMIN', 'The Competition Organization reserves the right to sanction any team that fails to comply with the Competition Rules & Regulations, established schedules, or that demonstrates unsportsmanlike conduct or behaviour that may endanger persons or facilities.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.2.3.3', 'A.2.3.3', 'A', 2, 'Application Of The Motostudent Regulations', 'Compliance with the Regulations', 'ADMIN', 'During the MS2 phase, Race Direction may apply the relevant sporting penalties for non-compliance with applicable sporting regulations. Such penalties may be accompanied by score penalties where appropriate.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.3.4', 'A.2.3.4', 'A', 2, 'Application Of The Motostudent Regulations', 'Compliance with the Regulations', 'ADMIN', 'Disobedience of instructions issued by the Competition Organization or Race Direction, unsportsmanlike or aggressive behaviour, or acts prejudicial to persons attending the event may result in disqualification.', 'admin', 'blocking', 'registration', null, true, '[]'::jsonb),
  ('A.2.3.5', 'A.2.3.5', 'A', 2, 'Application Of The Motostudent Regulations', 'Compliance with the Regulations', 'ADMIN', 'Teams, Riders, Team Members, Team Leaders and Team Tutors shall refrain from issuing public statements or press releases that may irresponsibly harm the legitimate interests of the MotoStudent International Competition, its Officials, or that may be contrary to the integrity of the Competition or the sport.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.2.3.6', 'A.2.3.6', 'A', 2, 'Application Of The Motostudent Regulations', 'Compliance with the Regulations', 'ADMIN', 'Public statements covered by this provision include, but are not limited to:
- Statements or comments to the media that attack, belittle, discredit, or irresponsibly harm Competition Officials.
- Public comments made by Team Members, Team Leaders, Team Tutors or Riders who know, or should reasonably know, that such comments may harm the reputation, image, or interests of the Competition or its Officials.
- Constructive and respectful feedback regarding Competition decisions or policies may be submitted through the official communication channels of the Competition.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.2.4.1', 'A.2.4.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Non-Compliance (hereinafter NC) shall result in the penalized delivery scoring 0 points.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.4.2', 'A.2.4.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Not Presented (hereinafter NP) shall result in the penalized delivery scoring 0 points.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.3', 'A.2.4.3', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Minor Penalty (hereinafter MP) shall result in a deduction of 10 points from the total MotoStudent score.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.4', 'A.2.4.4', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Severe Penalty (hereinafter SP) shall result in a deduction of 50 points from the total MotoStudent score.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.5', 'A.2.4.5', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Disqualification penalty (hereinafter DQ) shall entail, automatically and independently of any other penalty, the invalidation of the results obtained in an event, session, race, milestone or delivery. During the MS2 phase, immediate disqualification from a practice session or race may be indicated by means of a black flag.', 'admin', 'blocking', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.6', 'A.2.4.6', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'Any sporting-related penalty arising from the MS2 phase shall be determined by Race Direction.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.7', 'A.2.4.7', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'The Competition Organization reserves the right to impose penalties not expressly defined in Article A.2.4 if deemed necessary.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.8', 'A.2.4.8', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Warning may be issued either privately or publicly and may be imposed without a formal hearing.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.2.4.9', 'A.2.4.9', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'In the case of a Long Lap Penalty (hereinafter LLP), the Rider shall complete the predefined Long Lap route.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.2.4.10', 'A.2.4.10', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'A Grid Penalty shall consist of a drop of one or more grid positions or the obligation to start the race (either the Playoff Race or the Final Race) from the pit lane exit.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.4.11', 'A.2.4.11', 'A', 2, 'Application Of The Motostudent Regulations', 'Penalty types', 'ADMIN', 'An Expulsion penalty shall result in a score of 0 in the relevant phase. Depending on the seriousness of the infringement, the Competition Organization may impose the automatic expulsion of the team and its members from the Competition.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.5.1', 'A.2.5.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'Any team has the right to submit a protest or request for clarification. The Competition Organization shall review any doubt, alleged breach or penalty submitted through the official procedure.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.5.2', 'A.2.5.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'A team may file a claim in case of disagreement with any action taken by the Competition Organization, including scoring decisions or any other official action that may be considered detrimental to the team.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.2.5.3', 'A.2.5.3', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'A team may submit a protest against another participating team if it observes any breach of these Competition Rules & Regulations or improper conduct.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.2.5.4', 'A.2.5.4', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'All protests and complaints shall be submitted to the Competition Organization in accordance with the format established in Section J, Annex 1 of these Competition Rules & Regulations, clearly stating the article considered to have been breached and providing sufficient evidence for verification. Protests and complaints submitted prior to the Final Event may be sent scanned or digitally signed by email to faq@motostudent.com. Protests concerning the interpretation or application of the Competition Rules & Regulations must be submitted no later than sixty (60) days prior to the first day of the Final Event. During the Final Event, protests and complaints shall be submitted in written form to the Competition Organization through the Race Direction or the Technical Organization.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.5.5', 'A.2.5.5', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'To submit a claim or protest, the applicant team shall deposit 50 points from the score of the relevant phase or test and € 800. If the decision is rendered in favour of the applicant team, the 50 points and € 800 will be returned. If the protest is rejected, the team shall forfeit the 50 points and the € 800 deposit.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.2.5.6', 'A.2.5.6', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'Claims or protests related to tests conducted during the Final Event shall be submitted within a maximum of 30 minutes after publication of the results of the affected test.', 'admin', 'required', 'registration', null, true, '[{"op": "max", "value": 30.0, "unit": "minutes"}]'::jsonb),
  ('A.2.5.7', 'A.2.5.7', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'The Competition Organization will issue the final decision on any protest. Such decision shall be final and binding and not subject to appeal, except as provided below.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.2.5.8', 'A.2.5.8', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'In purely sporting matters, an appeal procedure may be requested in accordance with Article 119 of the RFME Sporting Regulations. Any participant may appeal penalties imposed or decisions taken by the Competition Organization or Race Direction before the Disciplinary Court of the RFME. The appeal must be submitted in writing, signed by the interested party and accompanied by a deposit of € 800. The right of appeal will expire fifteen days after notification of the decision.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.5.9', 'A.2.5.9', 'A', 2, 'Application Of The Motostudent Regulations', 'Right to Claims and Appeals', 'ADMIN', 'In accordance with Article 119 of the RFME Sporting Regulations, appeals to the FIM may be lodged through the RFME. The RFME shall determine whether the appeal is admissible and may refuse to process it without being obliged to provide justification. The right of appeal shall not suspend the imposed penalty or sanction. However, where the RFME admits the appeal to the FIM, the appellant may request temporary suspension of the decision, subject to submission of the guaranteed deposit required by the FIM.', 'admin', 'penalty', 'registration', null, true, '[]'::jsonb),
  ('A.2.6.1', 'A.2.6.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Right of Confiscation', 'ADMIN', 'The Competition Organization reserves the right, during the Final Event, to confiscate or retain any prototype, component, tool or rider equipment deemed non-compliant with these Competition Rules & Regulations.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.2.6.2', 'A.2.6.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Right of Confiscation', 'ADMIN', 'Any material confiscated by the Competition Organization during the Final Event will be returned to the corresponding team at the end of the Final Event.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.2.6.3', 'A.2.6.3', 'A', 2, 'Application Of The Motostudent Regulations', 'Right of Confiscation', 'ADMIN', 'The Competition Organization reserves the right to confiscate, retain or recall any component of the MotoStudent Kit if it is used outside the MotoStudent International Competition without prior authorization from the Competition Organization.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.2.7.1', 'A.2.7.1', 'A', 2, 'Application Of The Motostudent Regulations', 'Changes to the Competition Rules & Regulations', 'ADMIN', 'The Competition Organization reserves the right to amend the Competition Rules & Regulations, as well as the official Competition Calendar, if deemed necessary. Any amendment will be incorporated into Section I and published on the official website of the Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.2.7.2', 'A.2.7.2', 'A', 2, 'Application Of The Motostudent Regulations', 'Changes to the Competition Rules & Regulations', 'ADMIN', 'The Competition Organization will communicate any amendments through the communication channels it considers appropriate. In all cases, the most updated version of the Competition Rules & Regulations will be the one published on the official website of the Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.3.1.1', 'A.3.1.1', 'A', 3, 'Participation Requirements', 'Team Eligibility', 'ADMIN', 'The Competition has a purely academic objective and is conceived as a multidisciplinary educational project open to students from diverse fields of study, such as engineering, economics, marketing and project management. Although it involves the design and manufacture of a racing motorcycle prototype, MotoStudent is not a conventional speed championship but an academic competition in which engineering, management, innovation and teamwork are the core pillars.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.3.1.2', 'A.3.1.2', 'A', 3, 'Participation Requirements', 'Team Eligibility', 'ADMIN', 'Institutions whose primary activity is training in professional motor racing and / or motorsport competition are not eligible to participate in the MotoStudent Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.3.1.3', 'A.3.1.3', 'A', 3, 'Participation Requirements', 'Team Eligibility', 'ADMIN', 'There is no limit to the number of teams per university. Each university may register multiple teams in any category of the Competition.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.3.1.4', 'A.3.1.4', 'A', 3, 'Participation Requirements', 'Team Eligibility', 'ADMIN', 'Each registered team may submit only one project and one prototype.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.3.1.5', 'A.3.1.5', 'A', 3, 'Participation Requirements', 'Team Eligibility', 'ADMIN', 'Each team must represent a recognized higher education institution and must be officially endorsed by that institution. The name of the institution shall be clearly identifiable in the team registration and official documentation of the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.1.6', 'A.3.1.6', 'A', 3, 'Participation Requirements', 'Team Eligibility', 'ADMIN', 'Each participating team must choose a bike number between 1 and 99. Numbers will be allocated according to the team’s selection, subject to availability and in order of registration in the Competition. Numbers 1, 2 and 3 shall be exclusively reserved for the teams representing the universities ranked first, second and third respectively in the Best MotoStudent Award of the previous edition of the MotoStudent International Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.2.1', 'A.3.2.1', 'A', 3, 'Participation Requirements', 'Participants', 'ADMIN', 'Teams, Team Members, Team Leaders and Team Tutors registered in the Competition shall be considered “Participants of the Competition” from the moment of registration until the end of the Final Event.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.2.2', 'A.3.2.2', 'A', 3, 'Participation Requirements', 'Participants', 'ADMIN', 'Students from Vocational Training Centres (enrolled in the 2025–2026 and/or 2026–2027 academic year) may also be part of a team. In such cases, the team must provide proof of an agreement between the Vocational Training Center and the participating university.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.2.3', 'A.3.2.3', 'A', 3, 'Participation Requirements', 'Participants', 'ADMIN', 'The consideration of the Competition and its compatibility with the academic curriculum shall be the decision of each university. The representing university is not obliged to include the MotoStudent International Competition in its curriculum, including as an elective course.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.3.2.4', 'A.3.2.4', 'A', 3, 'Participation Requirements', 'Participants', 'ADMIN', 'To participate in the Competition, students must be enrolled in the 2025–2026 and/or 2026–2027 academic year, regardless of the percentage of subjects or credits passed.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.3.2.5', 'A.3.2.5', 'A', 3, 'Participation Requirements', 'Participants', 'ADMIN', 'All students must be at least 18 years old at the beginning of the Final Event.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.3.2.6', 'A.3.2.6', 'A', 3, 'Participation Requirements', 'Participants', 'ADMIN', 'If a team includes members from different Universities or Vocational Training Centres, in compliance with the rules indicated above, they must draft and formalize an agreement document in which both Educational Entities formally approve this collaboration. Additionally, a template of the agreement document is attached in the Annex 4 for your reference and use.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.3.1', 'A.3.3.1', 'A', 3, 'Participation Requirements', 'Liability Waiver', 'ADMIN', 'All Participants, including Team Members, Team Leaders, Team Tutors and Riders, must sign a liability waiver upon entering the MotoStudent International Competition. Any other persons attending the Final Event with the teams shall be considered members of the general public. Picture 1 - Motorsport can be dangerous', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.1', 'A.3.4.1', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'Each team must designate at least one Team Tutor, who may advise the team on any aspect of the project.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.2', 'A.3.4.2', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'A Team Tutor must have a contractual relationship with the representing university at the time of registration.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.3', 'A.3.4.3', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'The Team Tutor shall be considered the highest responsible person of the team in the event of any major incident during the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.4', 'A.3.4.4', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'The Team Tutor should accompany the team during the Final Event. If the Team Tutor is unable to attend, responsibility shall be delegated to the Team Leader, who shall act as the highest responsible person of the Team during the Final Event.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.5', 'A.3.4.5', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'The Team Tutor shall not take part in the development, assembly or manufacture of any component, document or presentation of the prototype.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.6', 'A.3.4.6', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'The Team Tutor shall represent the university in administrative matters throughout the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.4.7', 'A.3.4.7', 'A', 3, 'Participation Requirements', 'Team Tutor Duties', 'ADMIN', 'Any change of Team Tutor, for duly justified reasons, must be communicated as soon as possible to the Competition Organization. Such change shall be subject to an administrative fee.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.5.1', 'A.3.5.1', 'A', 3, 'Participation Requirements', 'Team Leader Duties', 'ADMIN', 'Each team must designate one Team Member as its Team Leader.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.5.2', 'A.3.5.2', 'A', 3, 'Participation Requirements', 'Team Leader Duties', 'ADMIN', 'The Team Leader shall have the same rights and obligations as the other enrolled students and shall act as the communication link with the Competition Organization and as the official representative of the team.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.5.3', 'A.3.5.3', 'A', 3, 'Participation Requirements', 'Team Leader Duties', 'ADMIN', 'Any reassignment of the Team Leader role within a team must be communicated to the Competition Organization as soon as possible. The Team Leader role may only be reassigned to another registered Team Member of the same team and shall be subject to an administrative fee.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.6.1', 'A.3.6.1', 'A', 3, 'Participation Requirements', 'Replacements', 'ADMIN', 'Only role modifications of Team Members or the Team Leader shall be allowed. Such modifications shall entail the payment of the corresponding administrative fee for management expenses, in accordance with Article A.3.8.1, and shall only be accepted up to 30 days before the first day of the Final Event.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.6.2', 'A.3.6.2', 'A', 3, 'Participation Requirements', 'Replacements', 'ADMIN', 'No Team Member or Team Tutor registration fee shall be cancelled or reimbursed.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.6.3', 'A.3.6.3', 'A', 3, 'Participation Requirements', 'Replacements', 'ADMIN', 'All permitted modifications concerning participating students must be communicated to the Competition Organization by the Team Tutor or the Team Leader through the MotoStudent Platform.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.1', 'A.3.7.1', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'An insurance coverage is mandatory. The registered universities must ensure that their students are covered by valid institutional insurance for all activities arising from participation in the MotoStudent International Competition.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.3.7.2', 'A.3.7.2', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'Each registered team must hold a valid insurance policy covering the Final Event, including Team Members, Team Leader, Team Tutor and Rider, as well as civil liability for damages to third parties. Such insurance must be valid in Spain and may be subject to documentary verification by the Competition Organization at any time prior to or during the Final Event.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.3', 'A.3.7.3', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'The Final Event will provide the medical and safety services required in accordance with applicable sporting regulations. Such services shall not substitute the insurance obligations of the participating teams or universities.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.4', 'A.3.7.4', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'Each team is solely responsible for the design, manufacture, assembly, maintenance, handling and operation of its prototype. Technical inspection, verification, scrutineering or approval by the Competition Organization shall not be construed as certification, homologation or guarantee of safety, reliability or regulatory compliance beyond the scope of the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.5', 'A.3.7.5', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'The Competition Organization shall not be liable for any material damage, personal injury, indirect loss or third-party claims arising from the team’s participation in the Competition, including but not limited to the development, construction, testing, racing, transport or post-event use of the prototype, including any modification or manipulation carried out by the team.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.6', 'A.3.7.6', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'The team shall indemnify and hold harmless the Competition Organization, its officials and partners against any third-party claims, damages, losses or liabilities arising from the team’s participation in the Competition.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.7', 'A.3.7.7', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'Any components supplied as part of the MotoStudent Kit, including engines and/or motors provided under a lease regime, remain the property of the Competition Organization and are placed under the responsibility of the team during their possession and use. The team shall be responsible for the proper handling, storage, transport, installation and operation of such components. The team’s insurance policy must provide adequate coverage for any damage, loss or liability arising from the handling, transport, modification, operation or misuse of these components while under the responsibility of the team. For components supplied under a lease regime, including engines and / or motors, the insurance coverage must name Fundacion Moto Engineering Foundation as beneficiary or additional insured party.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.3.7.8', 'A.3.7.8', 'A', 3, 'Participation Requirements', 'Insurances', 'ADMIN', 'The Competition Organization does not guarantee the fitness for purpose or commercial safety of any supplied component.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.3.8.1', 'A.3.8.1', 'A', 3, 'Participation Requirements', 'Administrative Procedures and Fees', 'ADMIN', 'Administrative procedures requested by the teams to the Competition Organization, which are not part of the development of the official milestones and activities of MotoStudent, shall entail a standard administrative fee of € 45 (VAT included) for management expenses. Examples of such administrative procedures include:
- Issuance of individual certificates or other justification documents (excluding those issued generically by the Competition Organization).
- Issuance of duplicate documentation.
- Modification of team data, including the assignment or change of the Team Leader role, Team Tutor, team name and/or representing university.
- Modification of Rider data not required by the Competition Organization (e.g. replacement due to injury).
- Management of parcels, shipments, customs interaction and storage of prototypes or other team equipment upon arrival at the Competition facilities may be provided upon prior written request. Such local handling services shall entail the standard administrative fee and may additionally be subject to the logistical and operational costs incurred. The Competition Organization shall evaluate the corresponding costs in advance and communicate them to the Team. The services shall only proceed upon written approval by the requesting Team.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.1.1', 'A.4.1.1', 'A', 4, 'Manufacturing The Motorbike', 'Prototype Manufacturing', 'ADMIN', 'The motorbikes participating in MotoStudent must be conceived, designed and assembled by the students registered in the team, without the direct involvement of professional engineers, race engineers, professional mechanics or other external professionals. Participation in the Competition shall constitute full acceptance of this requirement and of all provisions established in these Competition Rules & Regulations.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.2.1', 'A.4.2.1', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'The Competition Organization will provide each registered team with a MotoStudent Kit including compulsory components to be installed in the prototype. The technical regulations applicable to the Kit are defined in Sections B, C and D of these Competition Rules & Regulations.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.4.2.2', 'A.4.2.2', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'The MotoStudent Kit for the teams registered in the MotoStudent Competition includes, as a minimum, the following components:
- An internal combustion engine (only for the MotoStudent eFuel category).
- A permanent magnet electric motor (only for the MotoStudent Electric category).
- A set of front and rear slick tyres. The engines and motors supplied by the Competition Organization are provided under a lease-for-use scheme exclusively for the development of the prototype and participation in the MotoStudent Competition. Ownership of the engines shall remain at all times with the Competition Organization. Teams shall be responsible for their proper use, conservation and return in accordance with the procedures established by the Competition Organization (see Annex 6 and Annex 7 for a complete explanation of this procedures). The tyres supplied to the teams are intended for use during the Competition and shall become property of the team once delivered. Additional compulsory parts may be included in the MotoStudent Kit at the discretion of the Competition Organization depending on the technical configuration of the Competition. Where applicable, such components supplied by third parties (e.g. IMD) will be specified in the MotoStudent Accepted Parts Sheet.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.2.3', 'A.4.2.3', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'The Competition Organization will arrange the shipment of the MotoStudent Kit to the facilities indicated by the teams. The Competition Organization will normally cover the shipping cost of the MotoStudent Kit, subject to logistical feasibility and destination conditions. However, depending on the destination region, logistical constraints or extraordinary transport costs, the Competition Organization reserves the right to establish alternative delivery arrangements or distribution points, which will be communicated to the teams in advance. Each team shall be responsible for any customs duties, import taxes or similar charges applicable in the destination country, region or territory. Shipping conditions may vary depending on the geographical location of the team.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.2.4', 'A.4.2.4', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'Teams shall inform the Competition Organization prior to shipment of any applicable tariff policies, import restrictions or logistical limitations related to the destination of the MotoStudent Kit in order to avoid customs retention of the material.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.2.5', 'A.4.2.5', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'In certain countries, shipment of specific components included in the MotoStudent Kit may be restricted. In such cases, the Competition Organization will contact the team to determine an alternative solution for the delivery or management of those components.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.4.2.6', 'A.4.2.6', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'The components included in the MotoStudent Kit shall be used exclusively for the development of the team’s prototype and for participation in the MotoStudent Competition. Any other use is strictly prohibited.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.2.7', 'A.4.2.7', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'The components included in the MotoStudent Kit are listed in the corresponding articles of the category-specific sections of these Competition Rules & Regulations.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.4.2.8', 'A.4.2.8', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'The components included in the MotoStudent Kit will incorporate an identification mark. This marking must remain intact and visible, as it will be verified by the Technical Staff of the Competition Organization during the Final Event. In the event of damage or alteration of such markings, teams shall contact the Competition Organization to determine the appropriate procedure.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.4.2.9', 'A.4.2.9', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'It is prohibited to cover, remove or alter any identification mark of the components supplied by the Competition Organization.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.4.2.10', 'A.4.2.10', 'A', 4, 'Manufacturing The Motorbike', 'MotoStudent Kit', 'ADMIN', 'Any technical question regarding the components included in the MotoStudent Kit shall be addressed through the Competition Organization. Direct contact between participating teams and supplying companies regarding technical matters related to the MotoStudent Kit is prohibited.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.1', 'A.5.1.1', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'Shipments and imports of prototypes and team equipment must comply with all applicable transportation, import and export requirements established by Spanish laws and regulations, as well as the regulations of the country of origin of the shipment.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.2', 'A.5.1.2', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'Teams are responsible for arranging transport, customs clearance and all administrative procedures related to the shipment of prototypes and team equipment. Teams are strongly recommended to manage transport and customs procedures through a specialized logistics or customs company.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.5.1.3', 'A.5.1.3', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'Under no circumstances shall the Competition Organization or the management company of the Speed Circuit act as consignee, importer of record or customs representative for the transport of prototypes or team equipment.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.4', 'A.5.1.4', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'Teams participating from outside the European Union are strongly recommended to use temporary import procedures (such as ATA Carnet or equivalent customs mechanisms) for the transport of prototypes and equipment to and from the Final Event.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.5.1.5', 'A.5.1.5', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'The prototype and equipment, except the engine and/or motor, brought by the teams for participation in the Final Event shall normally be treated as temporarily imported goods for the duration of the event. Teams must ensure that the selected customs procedure allows the subsequent re-export of such equipment after the Final Event.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.6', 'A.5.1.6', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'Components of the MotoStudent Kit supplied under a lease-for-use scheme (such as engines) remain the property of the Competition Organization and must be returned to the Competition Organization in accordance with the procedures established in these Competition Rules & Regulations. Teams must ensure that the customs procedures used for their transport allow their return to the Competition Organization when required.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.7', 'A.5.1.7', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'Components of the MotoStudent Kit supplied for permanent use by the team (such as tyres or other non-returnable components) may be treated as standard exports or imports according to the applicable customs regulations.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.5.1.8', 'A.5.1.8', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'The Competition Organization shall not be responsible for customs procedures, duties, taxes, storage costs, delays, administrative requirements or any other issues related to shipments arranged by the teams.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.9', 'A.5.1.9', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'The Competition Organization may accept package deliveries for the Final Event up to fifteen (15) days prior to the start date of the Final Event, subject to prior coordination with the Organization. Such reception of shipments shall be considered an exceptional logistical facilitation and shall not imply that the Competition Organization acts as carrier, consignee, storage provider or logistics operator. Teams remain fully responsible for the shipment, transport conditions, customs procedures and any associated risks. The Competition Organization shall not be liable for loss, damage, delays or storage costs related to such shipments. Where applicable, the reception and handling of shipments may be subject to administrative or logistical management fees in accordance with the applicable provisions of these Competition Rules & Regulations. The Competition Organization reserves the right to refuse or return any shipment that has not been previously coordinated.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.10', 'A.5.1.10', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'For shipments arriving before the week of the Final Event, the delivery information shall be as follows:
- Addressee: Team or University name
- Address: TechnoPark MotorLand, Ed. Dr. Joaquin Repolles, Oficina 1, 44600 Alcañiz – Teruel (Spain)
- Contact phone: Team’s contact phone', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.1.11', 'A.5.1.11', 'A', 5, 'Particularities For Non-European Teams', 'Transport and Import of the Prototype', 'ADMIN', 'For shipments arriving during the week of the Final Event, the delivery information shall be as follows:
- Addressee: Team or University name
- Address: MotorLand Aragón – Circuito de Velocidad, Ctra. TE-V-7033 km. 1, 44600 Alcañiz – Teruel (Spain)
- Contact phone: Team’s contact phone', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.5.2.1', 'A.5.2.1', 'A', 5, 'Particularities For Non-European Teams', 'Visa', 'ADMIN', 'Registration documents issued within the MotoStudent Competition, as well as other participation accreditations provided by the Competition Organization, may be used by the teams as supporting documentation when applying for a visa, if required. Upon request, the Competition Organization may provide a certificate confirming the registration of the team in the MotoStudent Competition. The issuance of such certificates may entail the applicable administrative fees established in Article A.3.8 of these Competition Rules & Regulations. The Competition Organization strongly recommends that non-EU teams verify visa requirements and arrange all travel documentation as early as possible in order to avoid delays or unforeseen issues. Information regarding entry requirements for Spain can be found on the official website of the Ministry of Foreign Affairs of the Government of Spain: www.exteriores.gob.es.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.5.2.2', 'A.5.2.2', 'A', 5, 'Particularities For Non-European Teams', 'Visa', 'ADMIN', 'The Competition Organization does not grant visas and will not intervene with any authority, embassy or consulate regarding visa applications of team members. The responsibility for obtaining the necessary travel documentation lies entirely with the participants.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.1.1', 'A.6.1.1', 'A', 6, 'Competition Calendar', 'Official Deadlines and Calendar', 'ADMIN', 'The MotoStudent International Competition takes place over three academic semesters. During this time, several milestones must be completed by all teams as part of the evaluation process of the Competition. The following calendar presents the main deadlines of the Competition. Picture 2 – Current Edition calendar', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.6.2.1', 'A.6.2.1', 'A', 6, 'Competition Calendar', 'Team Registration Period', 'ADMIN', 'The Team Registration period opens on the date defined in Article A.1.6.2 and will remain open until all available places are filled. If vacancies remain, registration will close 30 days before the Final Event.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.3.1', 'A.6.3.1', 'A', 6, 'Competition Calendar', 'Additional Team Members and Team Tutors registration', 'ADMIN', 'The registration period for additional Team Members and Team Tutors remains open from the opening of the Team Registration period defined in Article A.1.6.2 until one month prior to the first day of the Final Event.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.1', 'A.6.4.1', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 1st milestone, Team Plan, aims to provide a general overview of the team composition, team objectives and internal organization. The submission period for this milestone is from 1 November 2026 to 30 November 2026.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.2', 'A.6.4.2', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 2nd milestone, Product Definition, requires the teams to describe to the jury the different technical solutions selected for the prototype, including the calculations used to ensure the safety of the theoretical design. The submission period for this milestone is from 1 February 2027 to 28 February 2027.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.3', 'A.6.4.3', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 3rd milestone, Innovation, requires teams to introduce improvements or new concepts in the prototype through new methods, ideas or products. The submission period for this milestone is from 1 April 2027 to 30 April 2027.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.4', 'A.6.4.4', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 4th milestone, Prototype CAD and Drawings, requires the teams to submit a 3D CAD model of their prototype together with a defined set of technical drawings. The submission period for this milestone is from 1 May 2027 to 31 May 2027.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.5', 'A.6.4.5', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 5th milestone, Economical Plan, requires the teams to present the total amount of funds obtained, the project expenses, the estimated total value of the prototype and the projected financial sustainability of the project. The submission period for this milestone is from 1 May 2027 to 31 May 2027.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.6', 'A.6.4.6', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 6th milestone, Pitch Presentation, must showcase the development of the project during the MotoStudent International Competition. The submission period for this milestone is from 1 June 2027 to 30 June 2027.', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.6.4.7', 'A.6.4.7', 'A', 6, 'Competition Calendar', 'MS1 Milestones', 'ADMIN', 'The MS1 7th milestone, Final Event Presentation, takes place during the Final Event (autumn 2027), where teams present their project to the jury. Each team must explain the main project decisions, the development process and the innovation presented. The jury may conduct a question round at the team box to further evaluate the project.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.6.5.1', 'A.6.5.1', 'A', 6, 'Competition Calendar', 'MSE Deliveries', 'ADMIN', 'The MSE 1st delivery, Electric and Battery Pack Schemes, is a specific requirement for teams participating in the MotoStudent Electric category. Teams must submit the electrical schematics of the prototype together with the mechanical and electrical configuration of the battery pack. The submission period for this delivery is from 1 March 2027 to 31 March 2027.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.6.5.2', 'A.6.5.2', 'A', 6, 'Competition Calendar', 'MSE Deliveries', 'ADMIN', 'The MSE 2nd delivery, Electrical Precheck, requires teams to review each article of Chapter D of these Competition Rules & Regulations and provide a brief explanation, supported by graphical evidence, demonstrating compliance. The submission period for this delivery is from 1 July 2027 to 31 July 2027.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.6.6.1', 'A.6.6.1', 'A', 6, 'Competition Calendar', 'Rider Eligibility Declaration', 'ADMIN', 'The Rider Eligibility Declaration requires each team to submit the sporting background and achievements of their rider in order to allow the Organization to verify compliance with the sporting requirements established in the Rules & Regulations. The submission period for this declaration is from 1 August 2027 to 31 August 2027. Submission of a valid Rider Eligibility Declaration within the defined period is a mandatory condition for participation in the dynamic activities of the Final Event. Teams that fail to submit this declaration will not be authorized to participate in any on-track activity.', 'admin', 'blocking', 'registration', null, true, '[]'::jsonb),
  ('A.6.7.1', 'A.6.7.1', 'A', 6, 'Competition Calendar', 'Final Event', 'ADMIN', 'The Final Event will take place during autumn 2027 (dates to be confirmed by the Competition Organization and FIM) at the MotorLand Aragón Speed Circuit. The specific dates and timetable for tests and activities will be published by the Competition Organization.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.1.1', 'A.7.1.1', 'A', 7, 'Communication Between Teams And Organization', 'Publication of questions: Frequently Asked Questions (FAQ)', 'ADMIN', 'By submitting a question to the Competition Organization, teams accept that the Organization may partially or totally reproduce the question and the corresponding official response in the FAQ Database, which is available to all registered teams through the official MotoStudent platforms. Accessible on the following URL or clicking in the following icon: https://www.motostudent.com/blocks/helpdesk/new.php', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.1.2', 'A.7.1.2', 'A', 7, 'Communication Between Teams And Organization', 'Publication of questions: Frequently Asked Questions (FAQ)', 'ADMIN', 'The FAQ Database collects the most common questions regarding the MotoStudent Competition submitted by the teams and will be updated periodically by the Competition Organization.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.1.3', 'A.7.1.3', 'A', 7, 'Communication Between Teams And Organization', 'Publication of questions: Frequently Asked Questions (FAQ)', 'ADMIN', 'Registered teams must regularly review the updates published in the FAQ Database. The clarifications and interpretations published through the FAQ Database shall be considered official and binding for the participating teams. However, if a clarification implies a modification, addition or change to the content of these Competition Rules & Regulations, such change shall be formalized by the Competition Organization through the corresponding official amendment, Technical Note or updated version of the applicable document.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.7.1.4', 'A.7.1.4', 'A', 7, 'Communication Between Teams And Organization', 'Publication of questions: Frequently Asked Questions (FAQ)', 'ADMIN', 'Teams are expected to consult the FAQ Database before submitting new questions in order to avoid duplicate queries already addressed by the Organization.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.1.5', 'A.7.1.5', 'A', 7, 'Communication Between Teams And Organization', 'Publication of questions: Frequently Asked Questions (FAQ)', 'ADMIN', 'All technical or regulatory questions related to the Competition should be submitted through the official communication channels established by the Competition Organization.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.7.2.1', 'A.7.2.1', 'A', 7, 'Communication Between Teams And Organization', 'Types of Questions', 'ADMIN', 'The Competition Organization will answer questions that are not already addressed in the Competition Rules & Regulations or in the FAQ Database.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.2.2', 'A.7.2.2', 'A', 7, 'Communication Between Teams And Organization', 'Types of Questions', 'ADMIN', 'The Competition Organization reserves the right not to answer questions whose response is clearly reflected in the Competition Rules & Regulations, the FAQ Database, the registration documentation or any other official communication issued by the Competition Organization.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.3.1', 'A.7.3.1', 'A', 7, 'Communication Between Teams And Organization', 'Consultation Procedure', 'ADMIN', 'All questions addressed to the Competition Organization must be submitted through the platform established by the Organization for this purpose and must include the following information:
- Full name of the person submitting the question.
- Category (MotoStudent Electric / MotoStudent eFuel).
- Bike Number.
- Team Name.
- Relevant article(s) of the Competition Rules & Regulations or FAQ reference number.
- Question: Fill in the Summary and Message describing your question.', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('A.7.3.2', 'A.7.3.2', 'A', 7, 'Communication Between Teams And Organization', 'Consultation Procedure', 'ADMIN', 'Teams are recommended not to attach pictures, drawings or files exceeding 500 KB in size.', 'admin', 'recommended', 'registration', null, false, '[]'::jsonb),
  ('A.7.3.3', 'A.7.3.3', 'A', 7, 'Communication Between Teams And Organization', 'Consultation Procedure', 'ADMIN', 'The Competition Organization will not resolve questions by telephone or ordinary email. All questions must be submitted and addressed through the consultation procedure defined in this article (ticketing system through the MotoStudent Platform).', 'admin', 'required', 'registration', null, false, '[]'::jsonb),
  ('A.7.3.4', 'A.7.3.4', 'A', 7, 'Communication Between Teams And Organization', 'Consultation Procedure', 'ADMIN', 'The Competition Organization reserves the right to group similar questions and publish the corresponding clarifications through the FAQ Database.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.7.4.1', 'A.7.4.1', 'A', 7, 'Communication Between Teams And Organization', 'Response Time', 'ADMIN', 'The Competition Organization will respond to questions as soon as reasonably possible. Depending on the complexity of the matter or the need for internal or external consultation, the estimated response time may extend up to fifteen (15) calendar days.', 'admin', 'info', 'registration', null, false, '[]'::jsonb),
  ('A.8.1.1', 'A.8.1.1', 'A', 8, 'Other Competitions', 'Other Competitions', 'ADMIN', 'These Competition Rules & Regulations have been developed exclusively for the current Edition of the MotoStudent International Competition. Therefore, prototypes designed and manufactured in accordance with these regulations are not required to comply with the technical or sporting regulations of any other motorcycle racing competition outside MotoStudent. The Competition Organization does not guarantee that prototypes built under these regulations comply with the requirements of other competitions and shall not be responsible for the use that teams may make of their prototypes in any competition or activity outside the MotoStudent International Competition. SECTION B GENERAL TECHNICAL REGULATIONS', 'admin', 'required', 'registration', null, true, '[]'::jsonb),
  ('B.1.1.1', 'B.1.1.1', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'ANY MATTER NOT EXPRESSLY PERMITTED AND SPECIFIED IN THESE TECHNICAL REGULATIONS SHALL BE CONSIDERED PROHIBITED. Teams may submit a request for clarification or authorization to the Competition Organization. Any corresponding decision will be communicated through an official Technical Note.', 'requirement', 'penalty', 'design', null, true, '[]'::jsonb),
  ('B.1.1.2', 'B.1.1.2', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'The design, manufacture and assembly of the prototype must comply with these Competition Rules & Regulations in order to be eligible to participate in the Competition.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.1.1.3', 'B.1.1.3', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'Prototypes must comply with all applicable technical requirements throughout the entire Final Event. The Competition Organization reserves the right to verify compliance at any time.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.1.1.4', 'B.1.1.4', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'Any non-compliance must be corrected and re-inspected before the prototype is allowed to participate in any test or activity during the Final Event.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.1.1.5', 'B.1.1.5', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'The rules contained in this section apply equally to both MotoStudent eFuel and MotoStudent Electric categories, unless specific requirements are explicitly indicated.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.1.1.6', 'B.1.1.6', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'All eligible components are defined in the MotoStudent Approved Parts List, which also identifies mandatory components. Any component not included in the corresponding list shall not be permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.1.1.7', 'B.1.1.7', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'Where no Approved Parts List is defined for a component or system, its design and selection shall be free, provided that it complies with these Rules & Regulations.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.1.1.8', 'B.1.1.8', 'B', 1, 'Technical Requirements Of The Prototype And Restrictions', 'Introduction to Technical Regulations', 'GEOM', 'Teams are solely responsible for the design, construction and safe operation of their prototype. Technical inspections carried out by the Competition Organization do not constitute certification of safety, reliability or regulatory compliance of the prototype.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.2.1.1', 'B.2.1.1', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The dimensions of the prototype are free, except for the requirements specified in Article B.2.1.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.2.1.2', 'B.2.1.2', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The minimum width between the outer ends of the semi-handlebars must be 450 mm. Picture 3 - Minimum prototype width', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 450.0, "unit": "mm"}]'::jsonb),
  ('B.2.1.3', 'B.2.1.3', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The prototype must allow a minimum lean angle of 50° without any part of the motorcycle (except the tires) touching the ground. This measurement shall be performed with the prototype unloaded (without rider), but fully equipped and with all fluids required for normal operation. Picture 4 - Minimum tilt angle', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.2.1.4', 'B.2.1.4', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The minimum ground clearance of the prototype in upright position must be at least 100 mm in static condition. This measurement shall be performed with the prototype unloaded (without rider), fully equipped for operation and with the tires inflated to 2 bar. Picture 5 - Minimum ground clearance distance', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 100.0, "unit": "mm"}]'::jsonb),
  ('B.2.1.5', 'B.2.1.5', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'No element of the prototype may protrude beyond the vertical plane tangential to the external circumference of the front tire. Picture 6 - Front vertical line', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.2.1.6', 'B.2.1.6', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'No element of the prototype may protrude beyond the vertical plane tangential to the external circumference of the rear tire. Picture 7 - Rear vertical line', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.2.1.7', 'B.2.1.7', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'A minimum clearance of 15 mm must be maintained between the tire tread and any part of the prototype along the outer circumference of the tire, in any suspension position or geometry setup.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.2.1.8', 'B.2.1.8', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The maximum seat and tail section width must not exceed 450 mm. No other element of the prototype may exceed this width from the seat to the tail section, except for the exhaust system in MotoStudent eFuel category prototypes. Picture 8 - Maximum seat width', 'prohibition', 'required', 'design', null, true, '[{"op": "max", "value": 450.0, "unit": "mm"}]'::jsonb),
  ('B.2.1.9', 'B.2.1.9', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The maximum fairing width must not exceed 600 mm. Picture 9 - Prototype maximum fairing width', 'prohibition', 'required', 'design', null, true, '[{"op": "max", "value": 600.0, "unit": "mm"}]'::jsonb),
  ('B.2.1.10', 'B.2.1.10', 'B', 2, 'General Design Requirements', 'Dimensions', 'GEOM', 'The maximum height difference between the seat surface and the highest point of the tail section must not exceed 150 mm. Picture 10 - Prototype maximum seat height difference', 'prohibition', 'required', 'design', null, true, '[{"op": "max", "value": 150.0, "unit": "mm"}]'::jsonb),
  ('B.2.2.1', 'B.2.2.1', 'B', 2, 'General Design Requirements', 'Weight', 'GEOM', 'The minimum total weight of the prototype without the rider shall be 85 kg for both categories, including all fluids necessary for the correct operation of the prototype.', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 85.0, "unit": "kg"}]'::jsonb),
  ('B.2.2.2', 'B.2.2.2', 'B', 2, 'General Design Requirements', 'Weight', 'GEOM', 'The weight of the complete prototype shall not fall below the minimum weight defined in Art. B.2.2.1 at any time during the Final Event. The Technical Staff may check the weight of any prototype at any time during the Final Event.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.2.2.3', 'B.2.2.3', 'B', 2, 'General Design Requirements', 'Weight', 'GEOM', 'The use of ballast to reach the minimum prototype weight is permitted. If ballast is used, it must be declared to the Technical Staff during scrutineering.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.2.2.4', 'B.2.2.4', 'B', 2, 'General Design Requirements', 'Weight', 'GEOM', 'Any ballast used must be securely fixed to the chassis in such a way that it cannot become detached in the event of a crash or fall (e.g. bolted fixation). Ballast must be attached using mechanical fasteners.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.1.1', 'B.3.1.1', 'B', 3, 'Frame', 'Design', 'CHASSIS', 'There are no restrictions on the design or materials of the frame, swingarm or subframe, provided that the resulting structure complies with these Competition Rules & Regulations. Teams are solely responsible for the structural integrity of the frame and chassis components.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.3.1.2', 'B.3.1.2', 'B', 3, 'Frame', 'Design', 'CHASSIS', 'In case of doubt regarding the structural safety of the proposed frame design, the Competition Organization may request a safety justification report. Such report may include finite element analysis (FEA), simulations or other equivalent validation tests.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.3.1.3', 'B.3.1.3', 'B', 3, 'Frame', 'Design', 'CHASSIS', 'The whole structure of the prototype must be designed so that the engine, fuel system, intake system and all electrical and electronic control and/or safety systems, including battery packs, are adequately protected in the event of a crash or fall, particularly in the case of a lateral impact.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.1.4', 'B.3.1.4', 'B', 3, 'Frame', 'Design', 'CHASSIS', 'The use of commercial chassis components is not permitted, including modified commercial main frames, subframes or swingarms. The chassis must be a self-designed prototype. For the purposes of these Technical Regulations, the term chassis refers to the main structural assembly of the prototype and includes, at minimum, the main frame, the subframe and the swingarm.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.1.5', 'B.3.1.5', 'B', 3, 'Frame', 'Design', 'CHASSIS', 'Swingarm spindles, wheel spindles and the steering shaft must be manufactured only from steel alloys. The use of aluminium alloys, magnesium alloys, titanium alloys, composite materials or any other non-steel material is not permitted for these components. This restriction does not apply to bolts, nuts, washers, circlips or other standard fasteners.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.1.6', 'B.3.1.6', 'B', 3, 'Frame', 'Design', 'CHASSIS', 'The engine / motor must not be used as a structural element of the chassis. The chassis shall be designed so that the main frame, subframe and swingarm form the load-bearing structural system of the prototype. The engine / motor may be mounted to the chassis and may transmit its own functional loads through its mounting points during normal operation, but it must not be used to complete the structural continuity of the chassis or to replace any primary load path between the main structural elements of the prototype. In particular, the engine / motor must not be used as the element that structurally links the steering area of the prototype to the swingarm pivot area or to the rear structural assembly.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.2.1', 'B.3.2.1', 'B', 3, 'Frame', 'Welding and Structural Joints', 'CHASSIS', 'For trellis or lattice type structures, nodes must ensure proper triangulation and effective load transfer between structural members in order to provide adequate structural stiffness. A small clearance between tubes may be allowed to facilitate welding or joining processes. However, the node must ensure proper structural continuity and load transmission between the connected members. Picture 11 - Example of correct triangulation', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.2.2', 'B.3.2.2', 'B', 3, 'Frame', 'Welding and Structural Joints', 'CHASSIS', 'The joining of structural elements may be carried out using any suitable manufacturing method (e.g. welding, brazing, bolting, bonding or additive manufacturing), provided that the resulting structure ensures adequate strength and structural integrity. All welding operations must ensure adequate structural integrity of the chassis. The team is solely responsible for the quality and safety of all welded joints. The Competition Organization reserves the right to request additional justification if the structural safety of a welded assembly is in doubt.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.3.1', 'B.3.3.1', 'B', 3, 'Frame', 'Crash Protectors', 'CHASSIS', 'The use of chassis crash protectors (frame sliders) is mandatory on both sides of the prototype. These elements must protect the chassis and propulsion system from lateral contact with the ground in the event of a crash or fall.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.3.2', 'B.3.3.2', 'B', 3, 'Frame', 'Crash Protectors', 'CHASSIS', 'Crash protectors must be made of nylon, fibre-reinforced materials or other materials of similar hardness capable of absorbing impact without damaging the track surface. They must be securely fixed to the frame or to a structural part of the chassis. Fixation using cable ties, adhesives or similar temporary fastening methods is not permitted. Crash protectors may be located inside or outside the fairing provided they effectively protect the frame and propulsion system. Picture 12 - Example of crash protector', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.3.3.3', 'B.3.3.3', 'B', 3, 'Frame', 'Crash Protectors', 'CHASSIS', 'Additional crash protection may be installed on wheel axles, handlebar ends or other suitable locations, provided that these elements do not create sharp edges and contribute to protecting the motorcycle structure during a fall.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.4.1.1', 'B.4.1.1', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'All edges and finishes of the fairing must be rounded with a minimum external radius of 1 mm.', 'constraint', 'required', 'design', null, true, '[]'::jsonb)
on conflict (clause_key) do update set
  printed_ref = excluded.printed_ref, section = excluded.section,
  article = excluded.article, article_title = excluded.article_title,
  group_title = excluded.group_title, subteam_key = excluded.subteam_key,
  body = excluded.body, obligation = excluded.obligation,
  criticality = excluded.criticality, phase = excluded.phase,
  milestone_key = excluded.milestone_key,
  is_team_duty = excluded.is_team_duty, specs = excluded.specs;

insert into clauses (clause_key, printed_ref, section, article, article_title, group_title, subteam_key, body, obligation, criticality, phase, milestone_key, is_team_duty, specs) values
  ('B.4.1.2', 'B.4.1.2', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'The fairing must not cover the rider laterally, except for the forearms when the rider is in the minimum aerodynamic resistance position.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.1.3', 'B.4.1.3', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'There are no restrictions regarding the manufacturing materials of the fairing.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.4.1.4', 'B.4.1.4', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'Aerodynamic devices (e.g. wings, fins, ducts or bulges) protruding from the fairing or bodywork are permitted, provided they do not exceed the maximum dimensions established in these Rules & Regulations and are securely fixed to the fairing or structural bodywork elements. Aerodynamic ducts integrated into the fairing for cooling or airflow management are permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.4.1.5', 'B.4.1.5', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'Any leading edge of an aerodynamic device must have a minimum external radius of 2.5 mm. Aerodynamic devices must not create sharp edges or projections that could endanger the rider or other participants.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.1.6', 'B.4.1.6', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'Aerodynamic devices must not deflect more than 10 mm at any point under a vertical downward point load of 50 N. For the purposes of this requirement, vertical downward means the direction of the vertical axis of the prototype relative to the ground. The 50 N load may be applied at any relevant point of the aerodynamic device, particularly at the location where the greatest deflection is expected.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.1.7', 'B.4.1.7', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'Mobile aerodynamic devices, including active aerodynamic systems, are permitted, provided that their operation does not compromise rider safety or the safety of other participants. If such devices require activation, they must be actuated only by direct rider input through a dedicated rider-operated control. Activation through the dashboard, brake controls, sensors, electronic logic or control algorithms is not permitted. All dimensional and safety requirements established in these Rules & Regulations shall be respected in any position or configuration of the aerodynamic device during operation. In case of doubt, the decision of the Technical Staff of the Organization shall be final.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.1.8', 'B.4.1.8', 'B', 4, 'Fairing', 'General Requirements', 'BODY', 'Aerodynamic devices must be designed and positioned so that they cannot contact the ground when the motorcycle reaches the minimum lean angle defined in Art. B.2.1.3. Aerodynamic devices must be securely mounted so that they cannot become detached from the prototype during normal operation or in the event of a crash.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.2.1', 'B.4.2.1', 'B', 4, 'Fairing', 'Lower Fairing', 'BODY', 'The lower fairing must be designed and manufactured to retain, in the event of an incident, at least half of the total volume of liquids of the prototype (fuel excluded), with a minimum containment capacity of 2.5 liters.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.2.2', 'B.4.2.2', 'B', 4, 'Fairing', 'Lower Fairing', 'BODY', 'The lower fairing must include a drainage hole with a diameter of 25 mm located at the lowest point of the fairing. This hole must remain watertight closed with a plug in dry conditions and may only be opened in wet conditions.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.2.3', 'B.4.2.3', 'B', 4, 'Fairing', 'Lower Fairing', 'BODY', 'The lower fairing may incorporate aerodynamic shaping, ducts or flow-deflecting features intended to manage airflow or water spray around the rear wheel or propulsion system, provided that these elements remain integrated within the fairing geometry and comply with all dimensional and safety requirements established in these Rules & Regulations.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.4.3.1', 'B.4.3.1', 'B', 4, 'Fairing', 'Mudguards', 'BODY', 'The use of front and rear mudguards is mandatory.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.3.2', 'B.4.3.2', 'B', 4, 'Fairing', 'Mudguards', 'BODY', 'The front mudguard shall not cover more than 135° of the wheel circumference, measured from the rearmost point of the tyre. The origin of the angle shall be the horizontal line passing through the wheel axle. Mudguard mounting points attached to the front fork, fork legs or brake disc covers may exceed this limit; however, under no circumstances shall they protrude more than 10 mm beyond the lateral projection of the front brake disc. Picture 13 - Prototype front mudguard', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.3.3', 'B.4.3.3', 'B', 4, 'Fairing', 'Mudguards', 'BODY', 'The rear wheel shall not be covered over more than 180° of its circumference by the rear assembly of the prototype.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.3.4', 'B.4.3.4', 'B', 4, 'Fairing', 'Mudguards', 'BODY', 'Mudguards may incorporate aerodynamic shaping, airflow channels or spray deflectors intended to manage airflow, cooling or water spray generated by the rotating wheels, provided that these elements remain integrated within the mudguard structure and comply with all dimensional and safety requirements established in these Rules & Regulations.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.4.3.5', 'B.4.3.5', 'B', 4, 'Fairing', 'Mudguards', 'BODY', 'The use of transparent materials for the purpose of circumventing the coverage limits established in this Article is prohibited.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.4.1', 'B.4.4.1', 'B', 4, 'Fairing', 'Protection Against Trapping', 'BODY', 'If the swingarm design does not cover the lower section of the drive chain or transmission belt, a guard must be installed to prevent trapping between the lower drive chain run and the rear sprocket (or equivalent transmission element).', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.4.2', 'B.4.4.2', 'B', 4, 'Fairing', 'Protection Against Trapping', 'BODY', 'This protection device (commonly known as “shark fin”) must be securely fixed to the swingarm or rear structure and must be made of rigid material, capable of maintaining its shape and protective function during normal use and foreseeable contact.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.4.4.3', 'B.4.4.3', 'B', 4, 'Fairing', 'Protection Against Trapping', 'BODY', 'The guard must extend at least to the rear axle height and cover the lower rear quadrant of the sprocket in order to effectively prevent trapping. Picture 14 - Example of “Shark fin”', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.1.1', 'B.5.1.1', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'Handlebars or semi-handlebars must be manufactured from steel or aluminium alloys. Welded or repaired handlebars are strictly forbidden. The use of magnesium alloys, titanium alloys or composite materials is not permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.1.2', 'B.5.1.2', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'Handlebar or semi-handlebar mounting supports must be designed to minimize the risk of fracture or detachment in the event of a crash.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.1.3', 'B.5.1.3', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'All exposed edges of the handlebars and their mounting components must have a minimum external radius of 2 mm.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.1.4', 'B.5.1.4', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'The throttle control must incorporate an automatic return mechanism that closes the throttle when the rider releases the grip.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.1.5', 'B.5.1.5', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'The clutch lever (if installed) is free in design, provided that the distance between the pivot point and the outer end does not exceed 200 mm. The lever must terminate in a ball end with a minimum diameter of 16 mm. The ball may be flattened but must maintain rounded edges and a minimum thickness of 14 mm.', 'constraint', 'required', 'design', null, true, '[{"op": "max", "value": 200.0, "unit": "mm"}]'::jsonb),
  ('B.5.1.6', 'B.5.1.6', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'The installation of a front brake lever protector is mandatory. This device must protect the brake lever from accidental activation in the event of contact with another prototype or external object. Picture 15 - Examples of front brake lever protections', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.1.7', 'B.5.1.7', 'B', 5, 'Handlebars And Footrests', 'Handlebars and Manual Controls', 'CONTROL', 'The TSMS, electric ignition or start button must be located on the handlebar and must be easily accessible to the rider at all times. Additional rider control switches or actuators may also be installed on the handlebar, provided that they do not interfere with the safe operation of the motorcycle.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.2.1', 'B.5.2.1', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'Footrests may be fixed or folding type (“folding in case of crash”). If folding footrests are used, they must be fitted with a return device that restores them automatically to their normal position and prevents unintended folding during riding. In resting position without the rider, the footrests must remain in the unfolded position.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.2.2', 'B.5.2.2', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'The end of each footrest must have a continuous rounded end with a minimum spherical radius of 8 mm.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.2.3', 'B.5.2.3', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'A protective cap must be installed at the outer end of each footrest. This cap must be made of aluminium, plastic, nylon or another material with equivalent mechanical resistance and must be permanently fixed. The protective surface must cover the widest possible area of the footrest end. Open-ended footrests without such protective cap are not permitted. Picture 16 Footrest ends. Left, footrest with hole (not allowed). Right, footrest with cap (allowed).', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.2.4', 'B.5.2.4', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'Footrests must incorporate side protection devices designed to prevent the rider’s boot from coming into contact with moving elements such as the drive chain, rear sprocket or rear tyre. These devices may take the form of heel guards or protective plates integrated into the footrest assembly and must not introduce any safety risk. Such elements may also contribute to airflow management around the rear wheel area.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.5.2.5', 'B.5.2.5', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'The rear brake pedal design is free.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.5.2.6', 'B.5.2.6', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'The gear shift pedal design (if installed) is free.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.5.2.7', 'B.5.2.7', 'B', 5, 'Handlebars And Footrests', 'Footrests and Their Controls', 'CONTROL', 'Footrest mounting systems may include adjustable mechanisms intended to adapt the riding position to the rider’s ergonomics, provided that such systems are securely fixed and do not introduce structural weakness or risk of unintended movement during riding.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.1.1', 'B.6.1.1', 'B', 6, 'Brake System', 'Allowed Type of Brake System', 'BRAKES', 'The prototype must be equipped with a hydraulic-driven disc brake system on both the front and rear wheel. A single-disc or double-disc configuration is permitted on the front wheel.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.1.2', 'B.6.1.2', 'B', 6, 'Brake System', 'Allowed Type of Brake System', 'BRAKES', 'Brake systems must be designed and installed following safe engineering practices and must provide reliable braking performance under all operating conditions.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.2.1', 'B.6.2.1', 'B', 6, 'Brake System', 'Command and Control', 'BRAKES', 'Combined brake systems are not allowed. The front and rear braking systems must operate independently.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.2.2', 'B.6.2.2', 'B', 6, 'Brake System', 'Command and Control', 'BRAKES', 'The front brake must be operated by a hand lever located next to the throttle grip on the right handlebar.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.2.3', 'B.6.2.3', 'B', 6, 'Brake System', 'Command and Control', 'BRAKES', 'The rear brake actuation system is free. The rear brake may be operated by:
- a foot pedal located near the right footrest, or
- a hand lever located on the left handlebar, or
- a thumb brake control located on the left handlebar, but only one of these actuation systems may be used in each prototype. The complete brake system must comply with all applicable safety and technical requirements of these Rules & Regulations.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.3.1', 'B.6.3.1', 'B', 6, 'Brake System', 'Brake Discs', 'BRAKES', 'Brake discs are free choice provided they comply with the requirements of this Article.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.3.2', 'B.6.3.2', 'B', 6, 'Brake System', 'Brake Discs', 'BRAKES', 'Brake discs must be manufactured from steel alloys. The use of carbon or ceramic brake discs is strictly prohibited.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.3.3', 'B.6.3.3', 'B', 6, 'Brake System', 'Brake Discs', 'BRAKES', 'Brake disc carriers may be manufactured from aluminium, magnesium or steel alloys. Composite materials are not permitted.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.6.3.4', 'B.6.3.4', 'B', 6, 'Brake System', 'Brake Discs', 'BRAKES', 'The use of internally ventilated brake discs is prohibited.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.3.5', 'B.6.3.5', 'B', 6, 'Brake System', 'Brake Discs', 'BRAKES', 'Brake discs must be installed on the front wheel / rim and on the rear wheel / rim in accordance with the selected brake configuration.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.3.6', 'B.6.3.6', 'B', 6, 'Brake System', 'Brake Discs', 'BRAKES', 'The installation of spacers between the brake disc and the wheel hub is permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.4.1', 'B.6.4.1', 'B', 6, 'Brake System', 'Brake Callipers', 'BRAKES', 'Brake callipers are free choice, provided that they are manufactured from aluminium or steel alloys. The use of magnesium alloys, titanium or composite materials for brake callipers is not permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.4.2', 'B.6.4.2', 'B', 6, 'Brake System', 'Brake Callipers', 'BRAKES', 'The rear brake calliper must be mounted using at least one dedicated anchoring element directly fixed to the swingarm.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.4.3', 'B.6.4.3', 'B', 6, 'Brake System', 'Brake Callipers', 'BRAKES', 'The rear calliper may be mounted on a floating support system positioned on the rear axle, provided that at least one dedicated fixing point positively connects the support to the swingarm, as indicated in Art. B.6.4.1.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.6.4.4', 'B.6.4.4', 'B', 6, 'Brake System', 'Brake Callipers', 'BRAKES', 'Brake pads are free choice.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.4.5', 'B.6.4.5', 'B', 6, 'Brake System', 'Brake Callipers', 'BRAKES', 'Brake pad retaining pins may be replaced and quick-change systems are permitted.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.6.4.6', 'B.6.4.6', 'B', 6, 'Brake System', 'Brake Callipers', 'BRAKES', 'Supplementary cooling ducts directing fresh air to the brake callipers are not permitted. Brake disc covers, brake calliper covers or any additional device intended to cover or partially cover the brake discs or brake callipers for cooling or aerodynamic purposes are not permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.5.1', 'B.6.5.1', 'B', 6, 'Brake System', 'Brake Master Cylinders', 'BRAKES', 'When specified by the Competition Organization, the use of brake master cylinders included in the MotoStudent Approved Parts List shall be mandatory for both the front and rear wheel.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.5.2', 'B.6.5.2', 'B', 6, 'Brake System', 'Brake Master Cylinders', 'BRAKES', 'Replacement of the front brake master cylinder activation lever requires prior authorization from the Competition Organization. Authorized replacement parts will be specified in the MotoStudent Approved Parts List.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.5.3', 'B.6.5.3', 'B', 6, 'Brake System', 'Brake Master Cylinders', 'BRAKES', 'Modification of any approved brake lever for the front brake master cylinder is prohibited.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.6.1', 'B.6.6.1', 'B', 6, 'Brake System', 'Brake Lines', 'BRAKES', 'Brake hoses are free choice.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.6.2', 'B.6.6.2', 'B', 6, 'Brake System', 'Brake Lines', 'BRAKES', 'Front brake hoses must pass in front of the lower steering yoke (lower triple clamp).', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.6.3', 'B.6.6.3', 'B', 6, 'Brake System', 'Brake Lines', 'BRAKES', 'Quick connectors on brake hoses are permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.6.4', 'B.6.6.4', 'B', 6, 'Brake System', 'Brake Lines', 'BRAKES', 'Sensors for research or telemetry purposes (e.g. brake pressure or temperature sensors) may be installed in the brake system provided that:
- they do not modify the hydraulic circuit layout beyond the use of manufacturer-approved fittings
- they are securely mounted and protected
- they do not introduce leakage risk or interfere with the safe operation of the braking system In case of doubt, the decision of the Technical Staff of the Competition Organization shall be final.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.7.1', 'B.6.7.1', 'B', 6, 'Brake System', 'ABS System', 'BRAKES', 'The use of anti-lock braking systems (ABS) is prohibited.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.6.8.1', 'B.6.8.1', 'B', 6, 'Brake System', 'Brake Fluid', 'BRAKES', 'Brake fluid is free choice.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.6.8.2', 'B.6.8.2', 'B', 6, 'Brake System', 'Brake Fluid', 'BRAKES', 'Brake fluid specifications must comply with or exceed the recommendations of the brake system manufacturer.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.7.1.1', 'B.7.1.1', 'B', 7, 'Suspension And Dampers', 'General aspects', 'CONTROL', 'Suspension systems are free in design and configuration, provided they comply with the requirements established in this Article. The suspension system includes all components whose function is to provide wheel travel, damping, springing or ride-height variation of the prototype, including the fork, rear shock absorber, linkages and any auxiliary mechanism acting on them.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.1.2', 'B.7.1.2', 'B', 7, 'Suspension And Dampers', 'General aspects', 'CONTROL', 'Active suspension systems, semi-active suspension systems and any system capable of modifying the suspension behaviour or ride height automatically during riding by means of electronic, electromechanical, hydraulic or pneumatic control are not permitted. Holeshot devices, launch devices, locking devices or any system intended to temporarily reduce suspension travel, lower the ride height or alter the normal suspension position for launch or riding purposes are not permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.1.3', 'B.7.1.3', 'B', 7, 'Suspension And Dampers', 'General aspects', 'CONTROL', 'Suspension adjustments may only be performed manually by mechanical or hydraulic means (e.g. spring preload, damping adjustment or ride height adjustment). Automatic or electronically controlled adjustments during operation are not permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.1.4', 'B.7.1.4', 'B', 7, 'Suspension And Dampers', 'General aspects', 'CONTROL', 'Inertial or dynamic devices intended to influence suspension behaviour, such as mass dampers, tuned mass systems, inerters or equivalent mechanisms, are considered suspension systems and are not permitted unless explicitly authorized by the Competition Organization.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.1.5', 'B.7.1.5', 'B', 7, 'Suspension And Dampers', 'General aspects', 'CONTROL', 'The Competition Organization reserves the right to reject the participation of any prototype whose suspension system is considered unsafe, structurally inadequate or incompatible with safe track operation.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.1.6', 'B.7.1.6', 'B', 7, 'Suspension And Dampers', 'General aspects', 'CONTROL', 'Suspension systems must ensure adequate wheel control and structural integrity under normal racing conditions and during potential crash scenarios.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.7.2.1', 'B.7.2.1', 'B', 7, 'Suspension And Dampers', 'Front Suspension', 'CONTROL', 'Any front suspension architecture is permitted, including but not limited to conventional telescopic forks, inverted forks, telelever, duolever, front swingarm systems or other alternative designs. Both commercially available and self-designed suspension systems are permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.2.2', 'B.7.2.2', 'B', 7, 'Suspension And Dampers', 'Front Suspension', 'CONTROL', 'The front suspension assembly may incorporate mechanical or hydraulic adjustment systems such as spring preload, compression damping, rebound damping or ride height adjustment. Suspension settings may only be adjusted when the prototype is stationary. No adjustment of suspension behaviour or ride height is permitted while riding.', 'info', 'info', 'design', null, true, '[]'::jsonb),
  ('B.7.3.1', 'B.7.3.1', 'B', 7, 'Suspension And Dampers', 'Rear Suspension', 'CONTROL', 'Any rear suspension architecture is permitted. Both commercially available and self-designed suspension systems are allowed.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.7.3.2', 'B.7.3.2', 'B', 7, 'Suspension And Dampers', 'Rear Suspension', 'CONTROL', 'The rear suspension assembly may incorporate mechanical or hydraulic adjustment systems such as spring preload, compression damping, rebound damping or ride height adjustment. Suspension settings may only be adjusted when the prototype is stationary. No adjustment of suspension behaviour or ride height is permitted while riding.', 'info', 'info', 'design', null, true, '[]'::jsonb),
  ('B.8.1.1', 'B.8.1.1', 'B', 8, 'Steering System', 'Restrictions and Geometry', 'CONTROL', 'The steering system must allow a minimum steering angle of 15° on each side of the longitudinal axis of the prototype, measured at the steering axis. Picture 17 - Minimum turning angle', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.8.1.2', 'B.8.1.2', 'B', 8, 'Steering System', 'Restrictions and Geometry', 'CONTROL', 'The steering angle must be limited by dedicated steering stops installed on both sides of the steering system. These stops must be made of nylon, aluminium or materials of similar hardness. Steering stops may contact the frame only through the dedicated stop elements designed for that purpose. No other structural element of the prototype shall act directly as a steering stop.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.8.1.3', 'B.8.1.3', 'B', 8, 'Steering System', 'Restrictions and Geometry', 'CONTROL', 'A clearance zone of at least 30 mm must be maintained around the rider’s hands and control areas throughout the full steering range in order to prevent trapping or injury to the rider’s fingers or hands in the event of a crash. The steering system must operate smoothly and must not exhibit excessive play, binding or interference throughout its full range of motion.', 'prohibition', 'required', 'design', null, true, '[{"op": "min", "value": 30.0, "unit": "mm"}]'::jsonb),
  ('B.8.2.1', 'B.8.2.1', 'B', 8, 'Steering System', 'Steering Dampers', 'CONTROL', 'The use of steering dampers is permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.8.2.2', 'B.8.2.2', 'B', 8, 'Steering System', 'Steering Dampers', 'CONTROL', 'Steering damper adjustments may only be performed manually by mechanical or hydraulic means.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.8.2.3', 'B.8.2.3', 'B', 8, 'Steering System', 'Steering Dampers', 'CONTROL', 'Steering dampers must not act as devices that limit the steering angle.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.1.1', 'B.9.1.1', 'B', 9, 'Rims And Tires', 'Rims', 'WHEELS', 'The rim sizes (measured at the tire mounting area) must be:
- Front rim: 2.5" x 17"
- Rear rim: 3.5" x 17"', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.1.2', 'B.9.1.2', 'B', 9, 'Rims And Tires', 'Rims', 'WHEELS', 'Rims made of composite materials (e.g. carbon fibre, glass fibre reinforced composites or similar) are not permitted. Rims must be manufactured from steel, aluminium or magnesium alloys.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.1.3', 'B.9.1.3', 'B', 9, 'Rims And Tires', 'Rims', 'WHEELS', 'The use of crash protectors at the ends of the wheel shafts is permitted. These protectors must be rounded and must have a diameter equal to or greater than the diameter of the corresponding shaft.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.1.4', 'B.9.1.4', 'B', 9, 'Rims And Tires', 'Rims', 'WHEELS', 'The ends of the wheel shafts must not protrude more than 30 mm from their housing. Crash protectors described in Article B.9.1.3 are not considered part of this measurement.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.1.5', 'B.9.1.5', 'B', 9, 'Rims And Tires', 'Rims', 'WHEELS', 'Rims may be freely selected by each team, including solid or closed rim designs, provided that such features form an integral part of the rim itself and comply with the dimensions, material requirements and safety provisions defined in this Article.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.9.1.6', 'B.9.1.6', 'B', 9, 'Rims And Tires', 'Rims', 'WHEELS', 'The use of additional wheel covers or devices intended to cover or partially cover the wheel for aerodynamic purposes is not permitted, except for the mudguards. In case of dispute regarding the interpretation of a wheel cover, the decision of the Competition Organization shall be final.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.2.1', 'B.9.2.1', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'Each team will receive one set of dry-condition slick tires (one front and one rear) supplied by the Official Tire Supplier as part of the MotoStudent Kit.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.9.2.2', 'B.9.2.2', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'Additional dry tires may be purchased through the Competition Organization. Wet-condition tires will only be available for purchase during the Final Event and will be limited to two sets per team. Tires may be supplied randomly from the available stock.', 'info', 'recommended', 'design', null, true, '[]'::jsonb),
  ('B.9.2.3', 'B.9.2.3', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'A maximum of two sets of dry tires (two front tires and two rear tires) must be declared for use during the Final Event. The first set must be declared before dynamic scrutineering. The second set may be declared during the Final Event at the Technical Control Area. The tire declaration template can be found in Annex 8.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.9.2.4', 'B.9.2.4', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'Only declared tires may be used during dynamic scrutineering, Test 1, Test 2, Test 3, free practice sessions, qualifying sessions, the Play-off Race and the Final Race. Non-compliance with this rule will result in the cancellation of the results obtained in the corresponding session.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.9.2.5', 'B.9.2.5', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'Only tires supplied by the Official Tire Supplier of the respective Competition Edition may be used during MotoStudent.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.9.2.6', 'B.9.2.6', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'Official tires may incorporate an identification label or marking provided by the Competition Organization for control purposes. The presence and integrity of this identification may be verified by the Technical Staff at any time during the Final Event. The technical specifications of the official tire set will be communicated to all teams participating in the Competition.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.9.2.7', 'B.9.2.7', 'B', 9, 'Rims And Tires', 'Tires', 'WHEELS', 'The use of tire warmers is permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.10.1.1', 'B.10.1.1', 'B', 10, 'Electronic Systems', 'Riding assistance electronic systems', 'ELEC', 'The use of electronic control or assistance systems that provide a clear riding advantage is forbidden. This includes, but is not limited to, traction control, ABS, anti-wheelie systems, launch control or any similar rider assistance system.', 'prohibition', 'info', 'design', null, true, '[]'::jsonb),
  ('B.10.1.2', 'B.10.1.2', 'B', 10, 'Electronic Systems', 'Riding assistance electronic systems', 'ELEC', 'Engine management systems intended for normal engine operation are permitted, provided they do not incorporate any of the rider assistance systems prohibited in Art. B.10.1.1.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.10.2.1', 'B.10.2.1', 'B', 10, 'Electronic Systems', 'Rider information systems', 'ELEC', 'Rider dashboard, information and warning systems are freely configurable, provided they are limited to the display of information and warning signals. The dashboard must not be used to command, activate controls or modify any system affecting vehicle dynamics.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.1', 'B.10.3.1', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'General requirements Each prototype must be equipped with a data acquisition system capable of monitoring and recording operational parameters of the motorcycle during track operation. The data logging system may be integrated in the ECU, motor controller, Battery Management System (BMS), or in any independent onboard data acquisition system. Recording of powertrain operational parameters is mandatory in order to monitor the correct functioning, safety and reliability of the prototype. The data acquisition system must automatically record data whenever the vehicle is powered and capable of motion.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.2', 'B.10.3.2', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Minimum required parameters – General At minimum, the data acquisition system must record the following parameters:
- Vehicle speed or wheel speed
- Throttle position
- Powertrain rotational speed (engine RPM or motor RPM depending on category)
- Engine / motor temperature
- Coolant temperature at engine / motor inlet and outlet The recorded channels must be sampled at a frequency sufficient to allow meaningful technical analysis of the operation of the prototype. The Competition Organization reserves the right to reject data of insufficient quality or resolution for verification purposes.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.3', 'B.10.3.3', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Additional required parameters – MotoStudent eFuel For prototypes competing in the MotoStudent eFuel category, the following parameters must additionally be monitored and recorded:
- Lambda value
- Oil pressure or oil switch status (if available)', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.4', 'B.10.3.4', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Additional required parameters – MotoStudent Electric For prototypes competing in the MotoStudent Electric category, the following parameters must additionally be monitored and recorded:
- Battery pack temperature (see article D.3.5)
- Battery pack voltage
- Battery current
- Motor controller and / or inverter temperature', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.5', 'B.10.3.5', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Sensors and installation Teams may record additional parameters related to motorcycle dynamics, rider behaviour or system performance. The use of all types of sensors is allowed, provided that their installation does not affect compliance with these Technical Regulations. All sensors, wiring and components of the data acquisition system must be properly secured and installed in safe locations.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.6', 'B.10.3.6', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Telemetry Live telemetry systems transmitting data from the motorcycle to external receivers during track operation are prohibited.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.7', 'B.10.3.7', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Data access and download Data acquisition systems may only be accessed when the motorcycle is stopped in the pit box area. Data download is permitted through wired or wireless connections (e.g. USB, Bluetooth or Wi-Fi), provided that the motorcycle is stationary in the pit area.', 'info', 'info', 'design', null, true, '[]'::jsonb),
  ('B.10.3.8', 'B.10.3.8', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Data availability The Competition Organization may request access to recorded data from any team at any time during the Competition, especially during the Final Event, for technical verification, safety monitoring, reliability analysis or incident investigation purposes. Such request shall be made by the Technical Director, the Technical Staff or any person expressly authorized by the Competition Organization. Teams must provide the requested data as soon as reasonably possible and, in any case, before the next on-track activity of the prototype unless another deadline is expressly authorized by the Competition Organization. Data must be provided in a readable digital format that allows the analysis of the recorded channels. When applicable, raw data files or export files in common formats (e.g. CSV, TXT or equivalent) shall be provided. For categories where a standard ECU is defined, data shall be provided in the native format generated by the ECU or in an exported format that preserves the recorded channels.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.3.9', 'B.10.3.9', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Data integrity and retention The data logging system must operate automatically and continuously whenever the vehicle is powered. Recorded data may be stored in the motorcycle, in the ECU, in the motor controller, in the Battery Management System or in another dedicated recording device, provided that the data remain under the control of the team and can be made available to the Competition Organization upon request during the Final Event. Recorded data must not be intentionally altered, manipulated or deleted during the Final Event. Teams must retain the recorded data for the entire duration of the Final Event and make it available to the Competition Organization if requested during technical inspections. If a team is temporarily unable to provide the requested data due to a justified technical issue, the team must immediately inform the Competition Organization and explain the cause of the issue. The Competition Organization will determine whether the situation is acceptable and what additional measures, deadline or consequences may apply. Failure to provide the requested data without justified cause may be considered a breach of these Technical Regulations and may result in penalties at the discretion of the Competition Organization.', 'prohibition', 'penalty', 'design', null, true, '[]'::jsonb),
  ('B.10.3.10', 'B.10.3.10', 'B', 10, 'Electronic Systems', 'Data Acquisition and Operational Monitoring Systems', 'ELEC', 'Use of data by the Competition Organization The Competition Organization may use the recorded operational data for:
- technical verification
- safety monitoring
- reliability analysis
- incident investigation
- technical evaluation purposes within the MotoStudent program', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.10.4.1', 'B.10.4.1', 'B', 10, 'Electronic Systems', 'Transponder', 'ELEC', 'Prior to the MS2 tests during the Final Event, the Competition Organization will supply a timing transponder to all teams to be installed on the prototype.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.10.4.2', 'B.10.4.2', 'B', 10, 'Electronic Systems', 'Transponder', 'ELEC', 'The transponder must be securely mounted in the location specified by the Competition Organization to ensure proper signal reception. Unless otherwise instructed by the Organization, the transponder shall be mounted on the left fork leg of the front suspension, facing outward from the prototype and in an easily accessible position. It must be properly secured using zip ties or equivalent fastening elements.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.4.3', 'B.10.4.3', 'B', 10, 'Electronic Systems', 'Transponder', 'ELEC', 'If the design of the prototype does not allow installation in the recommended location, the Technical Staff of the Organization will indicate an alternative mounting position.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.10.4.4', 'B.10.4.4', 'B', 10, 'Electronic Systems', 'Transponder', 'ELEC', 'The transponder must be installed in an easily accessible area and must remain properly fixed throughout the Final Event.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.4.5', 'B.10.4.5', 'B', 10, 'Electronic Systems', 'Transponder', 'ELEC', 'The transponder will be provided under a rental fee, € 35, not included in the MotoStudent registration fee.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.10.5.1', 'B.10.5.1', 'B', 10, 'Electronic Systems', 'On-board Cameras', 'ELEC', 'The use of on-board cameras by teams is not permitted during the MS2 phase.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.10.5.2', 'B.10.5.2', 'B', 10, 'Electronic Systems', 'On-board Cameras', 'ELEC', 'The Competition Organization may install on-board cameras on selected prototypes for broadcast, safety or promotional purposes.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.10.6.1', 'B.10.6.1', 'B', 10, 'Electronic Systems', 'Rear Safety Light', 'ELEC', 'All motorcycles must have a functioning red safety light mounted at the rear of the prototype for rain or low visibility conditions. The team must ensure that the light is switched on any time the motorcycle is on track or being ridden in the pit lane whenever rain tyres are fitted on the motorcycle. All lights must comply with the following requirements:
- Lighting direction must be parallel to the motorcycle running direction and clearly visible from the rear at least 15° to both the left and right sides of the prototype centre line.
- The rear light must be mounted near the end of the seat or rear fairing and approximately on the prototype centre line, in a position approved by the Competition Organization. In case of dispute over mounting position or visibility, the decision of the Organization will be final.
- Power output or luminosity equivalent to approximately: 10–15 W (incandescent) or 0.6–5 W (LED).
- The light output must be continuous while the motorcycle is on track. Flashing lights are not permitted during track operation, although flashing may be allowed in the pit lane if required by specific procedures, such as pit limiter active.
- The safety light power supply may be independent from the motorcycle main electrical system.
- The Competition Organization reserves the right to refuse any lighting system that does not satisfy the intended safety purpose.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.1.1', 'B.11.1.1', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'Each prototype must display three (3) competition numbers on the fairing corresponding to the number assigned to the team as defined in Art. A.3.1.6.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.1.2', 'B.11.1.2', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'The front number must be placed on the front fairing. It may be located centrally or slightly offset to either side of the longitudinal centreline of the prototype, provided that it remains clearly visible and readable. Picture 18 - Front number prototype position', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.1.3', 'B.11.1.3', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'On the front number area, each character must have a minimum height of 140 mm and a minimum stroke width of 25 mm. The minimum spacing between characters must be 10 mm. Picture 19 - Prototype front number minimum dimensions', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 10.0, "unit": "mm"}]'::jsonb),
  ('B.11.1.4', 'B.11.1.4', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'Two additional numbers must be placed on both sides of the motorcycle. These numbers must be located either on the lower rear portion of the main fairing or on the rear section of the fairing (tail). Picture 20 - Rear bike number placement', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.1.5', 'B.11.1.5', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'For the side numbers, each character must have a minimum height of 80 mm and a minimum stroke width of 10 mm. The minimum spacing between characters must be 5 mm. Picture 21 – Prototype rear number minimum dimensions', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 5.0, "unit": "mm"}]'::jsonb),
  ('B.11.1.6', 'B.11.1.6', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'Competition numbers must be displayed in a solid colour providing clear contrast with the background. Gradients, patterns or graphic effects that reduce readability are not permitted. If the Competition Organization considers that the numbers are not sufficiently visible or readable, the team must modify them as instructed. The Competition Organization may require replacement or apply temporary numbers to ensure proper identification during the Competition.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.1.7', 'B.11.1.7', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'The font used for competition numbers is free, provided that the numbers remain clearly readable. The Competition Organization reserves the right to require modification of the font if readability is considered insufficient. The inclusion of graphics, logos or decorative elements inside the number characters is not permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.1.8', 'B.11.1.8', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Bike Numbers', 'LIVERY', 'The background behind the competition numbers must be a continuous homogeneous area providing clear contrast with the numbers and extending at least 25 mm around their full perimeter. Graphic elements that reduce readability are not permitted in this area.', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 25.0, "unit": "mm"}]'::jsonb),
  ('B.11.2.1', 'B.11.2.1', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Identification', 'LIVERY', 'The name, logo or initials of the represented university must appear on all prototypes with a minimum dimension of 100 mm in height or width.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.2.2', 'B.11.2.2', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Identification', 'LIVERY', 'A reserved space must be available on the external left side of the frame (considering the riding direction) for scrutineering stickers. These stickers must remain visible with the fairing mounted and must be applied directly to the frame. The Competition Organization will place up to three (3) rectangular scrutineering labels with a maximum size of 35 x 35 mm. Picture 22 - MotoStudent scrutineering stickers', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.2.3', 'B.11.2.3', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Identification', 'LIVERY', 'Every prototype must have an identifying code engraved on both the frame and the swingarm in a visible location during scrutineering. The code format will be as follows: MSCXXYYZZ e.g.: MSF012701 Where:
- MS is the acronym of MotoStudent.
- C is the category in which the team is competing, whereas F for MotoStudent eFuel category and E for MotoStudent Electric category (the example shows a MotoStudent eFuel prototype).
- XX is the bike number (the example shows the bike number 01).
- YY represents the last two digits of the Final Event year of the frame and / or swingarm (the example shows the part produced in the year 2027).
- ZZ represents the unit number of the frame and / or swingarm if more than one unit has been produced (the example 01 shows the 1st produced part).', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.3.1', 'B.11.3.1', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'In the final design of the prototype, all teams must include on the upper part of the side fairing a reserved horizontal white strip complying with the following specifications:
- The strip must be white.
- The strip must extend from the rear part of the side fairing towards the front.
- The strip must be approximately horizontal to the ground with a tolerance of ±15°.
- The minimum length of the strip must be 400 mm.
- The minimum height of the strip must be 80 mm. This strip is reserved for the placement of official MotoStudent and partner logos. Picture 23- White strip example', 'constraint', 'required', 'design', null, true, '[{"op": "min", "value": 400.0, "unit": "mm"}, {"op": "min", "value": 80.0, "unit": "mm"}]'::jsonb),
  ('B.11.3.2', 'B.11.3.2', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'In addition to the strip defined in Art. B.11.3.1, three spaces must be reserved on the prototype to include category stickers that will be fixed by the Competition Organization during the Final Event. These category stickers will have a maximum size of 150 mm wide by 100 mm high.', 'constraint', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.3.3', 'B.11.3.3', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'One category sticker will be placed on the front part of the fairing near the front number, under the windscreen. Picture 24 - Front category sticker placement', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.11.3.4', 'B.11.3.4', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'Two category stickers will be placed on both sides of the prototype on the upper part of the front fairing. Picture 25 - Lateral category sticker placement', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.11.3.5', 'B.11.3.5', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'The Competition Organization may require space for its brand logo or name, or for the logos of official partners or sponsors, on both sides of the swingarm and on the front mudguard. Maximum dimensions will be:
- 200 x 70 mm on the swingarm
- 60 x 80 mm on the front mudguard', 'constraint', 'info', 'design', null, false, '[]'::jsonb),
  ('B.11.3.6', 'B.11.3.6', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'Teams must reserve the areas described in this article during the design phase of the prototype. If these spaces are not respected, the Competition Organization reserves the right to place the official stickers in the most suitable location, even if this results in partial coverage of existing sponsor logos, promotional stickers or fairing graphics. Teams will not have the right to appeal or request relocation of these stickers.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.11.3.7', 'B.11.3.7', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'It is strictly forbidden to include advertising for alcoholic beverages, gambling and / or tobacco on the prototype or in any official team environment related to the Competition.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.11.3.8', 'B.11.3.8', 'B', 11, 'Identification, Advertising And Competition Numbers', 'Competition Logos and Advertising', 'LIVERY', 'It is strictly forbidden to include advertising or messages that violate human dignity or promote violence, intolerance, xenophobia, racism or any other offensive content. The Competition Organization reserves the right to review all advertising content and prohibit any element it considers inappropriate.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.12.1.1', 'B.12.1.1', 'B', 12, 'Rider Equipment', 'Helmet', 'RIDER', 'The rider must wear a homologated full-face helmet complying with at least one of the following standards:
a) FIM FHRPhe-01 or FHRPhe-02 Picture 26 - FHRPhe-01 homologation example
b) ECE 22-05 “P” or ECE 22.06 “P” Picture 27 - ECE 22-05 homologation example
c) SNELL M 2015 o MD2020D o 2020R Picture 28 - SNELL M 2015 homologation example
d) JIS T 8133:2015 Picture 29 - JIS T 8133:205 homologation example Helmets homologated according to the FIM FRHPhe standard are strongly recommended. The Competition Organization reserves the right to update or modify the list of accepted helmet homologations in these Rules & Regulations or in future editions of the Competition. Teams are encouraged to progressively adopt FIM homologated helmets in preparation for future regulatory updates.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.1.2', 'B.12.1.2', 'B', 12, 'Rider Equipment', 'Helmet', 'RIDER', 'The use of disposable visor screen covers (tear-offs) is permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('B.12.1.3', 'B.12.1.3', 'B', 12, 'Rider Equipment', 'Helmet', 'RIDER', 'Helmet visors must be made of shatterproof material.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.1.4', 'B.12.1.4', 'B', 12, 'Rider Equipment', 'Helmet', 'RIDER', 'Riders must wear a helmet that is in good condition, correctly fitted and properly fastened at all times while the prototype is operating on track and during all MS2 Tests.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.1.5', 'B.12.1.5', 'B', 12, 'Rider Equipment', 'Helmet', 'RIDER', 'No cameras, sensors, communication devices or electronic equipment may be attached to the helmet unless expressly authorized by the Competition Organization. The Competition Organization may require the removal of any device considered unsafe or non-compliant.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.12.2.1', 'B.12.2.1', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'The rider must wear a complete one-piece suit made of leather or another material with equivalent abrasion resistance, covering the full torso and limbs and including integrated protection for elbows, shoulders and knees complying with EN 1621-1 or equivalent standards. Picture 30 - Rider equipment', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.2.2', 'B.12.2.2', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'The use of a back protector complying with EN 1621-2 and a chest protector complying with EN 1621-3 is mandatory.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.2.3', 'B.12.2.3', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'Riders must wear boots in good condition made of leather or equivalent protective material and specifically designed for motorcycle competition.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.2.4', 'B.12.2.4', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'Riders must wear gloves in good condition made of leather or equivalent material and incorporating protection for fingers and knuckles.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.2.5', 'B.12.2.5', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'The use of fire-resistant or competition-grade underwear is recommended. Undergarments made of synthetic materials that may melt and cause injury in the event of a crash should be avoided.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.12.2.6', 'B.12.2.6', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'The use of an airbag system approved for motorcycle racing is strongly recommended. Riders should consult the latest FIM or equivalent self-certified airbag compatibility lists when selecting such systems.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('B.12.2.7', 'B.12.2.7', 'B', 12, 'Rider Equipment', 'Safety Clothing', 'RIDER', 'The use of wearable sensors, monitoring devices or electronic equipment attached to the rider’s body or equipment is not permitted unless expressly authorized by the Competition Organization for safety or technical reasons.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('B.12.3.1', 'B.12.3.1', 'B', 12, 'Rider Equipment', 'Long hair safety', 'RIDER', 'It is the rider’s responsibility to ensure that long hair is securely contained inside the helmet or suit during track activities so that it does not present a safety risk to the rider or others. SECTI ON C: SPECIFI C TECHN ICAL REGU LATIONS FOR THE CATEG ORY “M OTOSTUDE NT eFUE L” SECTION C SPECIFIC TECHNICAL REGULATIONS FOR THE CATEGORY "MOTOSTUDENT eFUEL"', 'info', 'penalty', 'design', null, true, '[]'::jsonb),
  ('C.1.1.1', 'C.1.1.1', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The Competition Organization will supply a standardized internal combustion engine to all teams registered in the MotoStudent eFuel category. The engine remains the exclusive property of the MotoStudent Organization (MEF – Fundacion Moto Engineering Foundation) and is provided to the teams under a temporary loan system for the sole purpose of developing their prototype and participating in the MotoStudent International Competition. Participation in the Competition and acceptance of these Rules & Regulations implies acceptance of the conditions governing the use, care and return of the supplied engine (see Annexes 6 and 7).', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.1.2', 'C.1.1.2', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The supplied engines have undergone quality control checks prior to shipment and are based on series-production engines. However, as the engines will be installed and operated within prototypes designed and manufactured by the Teams, and may be used on external test benches and/or motorcycles without the original OEM components of the production vehicle, the Competition Organization assumes no responsibility for any damage the engine may suffer during installation, operation, testing or competition activities. Teams shall be responsible for the correct installation, handling and use of the engine, as well as for covering the costs of any repair required due to damage occurring while the engine is under their custody. This responsibility also includes any theft, loss or other incidents affecting the engine during such period.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.3', 'C.1.1.3', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The supplied engines may only be used within the framework of the MotoStudent Competition and its related development activities, including prototype development, testing and track sessions. Any use of the engine outside activities directly related to the MotoStudent Competition is strictly prohibited. Any breach of this rule may result in sanctions imposed by the Competition Organization.', 'info', 'info', 'design', null, true, '[]'::jsonb),
  ('C.1.1.4', 'C.1.1.4', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'Teams are responsible for the correct installation, operation and maintenance of the engine according to the technical instructions provided by the Competition Organization and the manufacturer. Any operation outside the specified operating limits may be considered improper use.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.1.1.5', 'C.1.1.5', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The engine is delivered sealed by the Competition Organization. The engine must not be opened, disassembled, modified or altered in any way by the teams. Breaking, removing or manipulating the engine seals is strictly prohibited unless expressly authorized in writing by the Competition Organization.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.6', 'C.1.1.6', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'Any engine with damaged, missing or manipulated seals may be considered non- compliant and may be subject to sanctions imposed by the Competition Organization.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.1.1.7', 'C.1.1.7', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'Teams are not allowed to open, modify, alter or attempt to reverse engineer the internal components of the engine. Any modification to the engine is strictly prohibited unless explicitly authorized in these Technical Regulations. Only those external interfaces and components expressly permitted in the relevant articles of these Rules and Regulations may be modified or adapted for installation purposes.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.1.1.8', 'C.1.1.8', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'Teams must immediately notify the Competition Organization of any malfunction, abnormal behaviour or suspected damage to the engine. The Competition Organization may require the engine to be returned for inspection, maintenance or repair.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.9', 'C.1.1.9', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'Normal wear resulting from proper use of the engine during development and competition activities will not be charged to the team. Engines must always be operated in a responsible manner. However, any damage resulting from misuse, abusive operation, incorrect installation, operation outside the specified limits, lack of maintenance or unauthorized modification will be the financial responsibility of the team. Examples of improper or abusive operation may include, but are not limited to, excessive engine revving without load, burnouts, prolonged operation outside the recommended operating conditions, or any other use that may cause abnormal stress or damage to the engine.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.10', 'C.1.1.10', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The Competition Organization shall determine whether engine damage results from normal wear or improper use. The decision of the Competition Organization shall be final.', 'requirement', 'required', 'design', null, false, '[]'::jsonb),
  ('C.1.1.11', 'C.1.1.11', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The engine must be returned to the Competition Organization at the end of the current edition. Teams present at the Final Event are required to return the engine on-site during the Final Event, in accordance with the instructions of the Technical Organization.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.12', 'C.1.1.12', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'Teams that will not attend the Final Event must return the engine to the Competition Organization no later than thirty (30) days before the first day of the Final Event.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.13', 'C.1.1.13', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'All transportation costs for sending engines between the team’s facilities and MEF headquarters, including for inspection, repair, replacement or return, shall be borne by the team.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.14', 'C.1.1.14', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'If an engine is lost, not returned within the specified period, or returned with damage beyond normal wear, the team shall be responsible for covering the repair costs or replacement value of the engine.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.1.15', 'C.1.1.15', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The Competition Organization may establish maintenance procedures, inspection intervals and service operations in order to ensure reliability and equal performance of the engines during the Competition.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.1.16', 'C.1.1.16', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The engine sealing system, inspection procedures and maintenance operations will be defined in the relevant MotoStudent technical documentation and communicated to the teams through official channels.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.1.17', 'C.1.1.17', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'The price of replacement engines, standard maintenance procedures and repair operations will be defined in the official MotoStudent eFuel Engine Information document and / or in these Rules & Regulations.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.1.18', 'C.1.1.18', 'C', 1, 'Engine', 'Preliminary information', 'PWR_EF', 'In the event that an engine requires non-standard repair following inspection by the Competition Organization, the team will be notified of the corresponding repair cost through a proforma invoice prior to the intervention. The cost of the repair shall be borne by the team. If the team declines the repair or fails to assume the corresponding costs, the Competition Organization may retain the engine and restrict the team’s continued participation in the Competition. Any outstanding payments related to engine repair, replacement or loss must be settled before the end of the Competition edition. Failure to settle the obligations described in this Article C.1.1 may result in the Competition Organization declaring the team, the represented university or any related entity ineligible to participate in future editions of the MotoStudent Competition until all outstanding obligations have been fulfilled. The Competition Organization reserves the right to refuse participation to teams or institutions with outstanding obligations from previous editions.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.2.1', 'C.1.2.1', 'C', 1, 'Engine', 'Sealing', 'PWR_EF', 'The use of the engine supplied by the Competition Organization is compulsory. All engines will be delivered sealed by the Competition Organization. The engine seals must remain intact at all times. It is strictly forbidden for teams to open, disassemble, manipulate or alter any internal component of the engine. Any missing, broken or damaged seal may result in the engine being declared non- compliant and may lead to sanctions as determined by the Competition Organization.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.2.2', 'C.1.2.2', 'C', 1, 'Engine', 'Sealing', 'PWR_EF', 'If a team detects a malfunction, internal failure or suspected issue affecting the engine, the team must immediately inform the Competition Organization. Teams are not allowed to attempt any repair, disassembly or intervention affecting sealed parts of the engine. The Competition Organization will determine the appropriate inspection, repair or replacement procedure.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.2.3', 'C.1.2.3', 'C', 1, 'Engine', 'Sealing', 'PWR_EF', 'The inspection and verification of engine seals may be performed by the Competition Organization at any moment during the Competition, including scrutineering, practice sessions, races or technical inspections. The technical assessment of the engine condition and sealing status performed by the Competition Organization shall be final.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.3.1', 'C.1.3.1', 'C', 1, 'Engine', 'Engine Technical Specifications', 'PWR_EF', 'The detailed technical specifications of the engine supplied by the Competition Organization will be published in the official Engine Technical Information document and provided to all registered teams.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.3.2', 'C.1.3.2', 'C', 1, 'Engine', 'Engine Technical Specifications', 'PWR_EF', 'The engine supplied by the Competition Organization will be a single-cylinder four- stroke internal combustion engine with a displacement between 240 cc and 340 cc.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.3.3', 'C.1.3.3', 'C', 1, 'Engine', 'Engine Technical Specifications', 'PWR_EF', 'The engine supplied by the Competition Organization is equipped with a liquid cooling system.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.4.1', 'C.1.4.1', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'External or internal modifications to the engine assembly are not permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.4.2', 'C.1.4.2', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'The crankcase, cylinder head and cylinder block must remain in their original configuration as supplied by the Competition Organization. Machining, polishing, material removal, surface treatment, structural modification or replacement of internal components is strictly prohibited.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.4.3', 'C.1.4.3', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'No modifications to the engine mounting points on the engine block are permitted. The prototype frame must be designed to match the original engine mounting geometry.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.4.4', 'C.1.4.4', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'The original cooling passages and cooling interfaces of the engine must not be modified. Teams must design the external cooling system in accordance with the original cooling connections provided by the engine.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.4.5', 'C.1.4.5', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'The intake and exhaust interfaces of the engine must not be modified. The intake and exhaust systems developed by the teams must connect to the engine using the original geometry and connection points provided by the engine. No machining, modification or adaptation of the engine intake or exhaust mounting surfaces is permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.4.6', 'C.1.4.6', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'The installation of external protective engine covers is recommended, provided that their installation does not involve any modification of the engine structure. Such protectors may use the original engine cover bolts as mounting points. Protective covers must not hide or obstruct any official seal, identification mark or label placed by the Competition Organization. Only metallic protectors or FIM- homologated protectors are permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.4.7', 'C.1.4.7', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'The original oil pump integrated into the engine must not be modified or replaced.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.4.8', 'C.1.4.8', 'C', 1, 'Engine', 'Crankcase, cylinder head and engine block', 'PWR_EF', 'The original water pump integrated into the engine must not be modified or replaced.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.5.1', 'C.1.5.1', 'C', 1, 'Engine', 'Modifications', 'PWR_EF', 'Any modification to the engine or its components is prohibited unless it is expressly permitted in these Technical Regulations.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.5.2', 'C.1.5.2', 'C', 1, 'Engine', 'Modifications', 'PWR_EF', 'Any modification intended to circumvent the spirit of these Rules & Regulations may be considered a non-compliance by the Competition Organization.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.1.5.3', 'C.1.5.3', 'C', 1, 'Engine', 'Modifications', 'PWR_EF', 'In the event of any doubt or dispute regarding the interpretation of these provisions, the decision of the Competition Organization shall be final.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.6.1', 'C.1.6.1', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'The engine must be operated at all times within safe operating limits regarding temperature, engine speed and air-fuel mixture.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.6.2', 'C.1.6.2', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'The maximum coolant temperature during operation must not exceed the limit defined by the Competition Organization in the official MotoStudent eFuel Engine Information document.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.6.3', 'C.1.6.3', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'The air-fuel mixture must remain within safe limits as defined in Article C.6. Lambda values outside the permitted range may be considered unsafe engine operation.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.6.4', 'C.1.6.4', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'Engine speed must remain within the limits defined by the engine manufacturer or by the Competition Organization. Excessive engine revving without load is strictly forbidden.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.6.5', 'C.1.6.5', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'Operation practices that may cause abnormal thermal or mechanical stress to the engine are prohibited. These include, but are not limited to:
- excessive engine revving without load
- burnouts or intentional rear wheel spinning
- prolonged operation outside recommended temperature limits
- operation without adequate cooling airflow
- operation with clearly unsafe air-fuel mixture conditions', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.1.6.6', 'C.1.6.6', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'The Competition Organization reserves the right to review engine operating data, including but not limited to engine speed, coolant temperature and lambda values, in order to determine whether an engine failure may have resulted from operation outside safe limits.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.1.6.7', 'C.1.6.7', 'C', 1, 'Engine', 'Engine operating limits', 'PWR_EF', 'If engine damage is determined to be the result of operation outside these limits or abusive use of the engine, the repair or replacement costs shall be charged to the team.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.1.1', 'C.2.1.1', 'C', 2, 'Air Intake System', 'Intake pipes', 'PWR_EF', 'The design, dimensions and position of the air intake ducts are free, provided that they comply with the overall dimensional limits of the prototype defined in these Rules & Regulations. The intake system may incorporate filters, airboxes or aerodynamic intake devices freely designed by the teams.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.1.2', 'C.2.1.2', 'C', 2, 'Air Intake System', 'Intake pipes', 'PWR_EF', 'Mobile devices intended to vary the effective length of the intake duct are permitted, provided that they are located upstream of the intake valves.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.1.3', 'C.2.1.3', 'C', 2, 'Air Intake System', 'Intake pipes', 'PWR_EF', 'Only air and recirculated engine gases (if applicable) may flow through the intake ducts. The injection or introduction of additional substances such as ethanol, methanol, water or any other chemical compound into the intake system is not permitted.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.2.1', 'C.2.2.1', 'C', 2, 'Air Intake System', 'Throttle control', 'PWR_EF', 'Only one throttle valve or an equivalent mechanical system is permitted. The throttle must be operated exclusively by a mechanical control (e.g. cable) directly actuated by the rider.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.2.2', 'C.2.2.2', 'C', 2, 'Air Intake System', 'Throttle control', 'PWR_EF', 'Electronic throttle control systems ("ride-by-wire") are not permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.2.3', 'C.2.2.3', 'C', 2, 'Air Intake System', 'Throttle control', 'PWR_EF', 'In the event of a control system failure, the throttle valve must automatically return to the closed position.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.2.4', 'C.2.2.4', 'C', 2, 'Air Intake System', 'Throttle control', 'PWR_EF', 'A bypass system for idle speed control may be implemented.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.2.3.1', 'C.2.3.1', 'C', 2, 'Air Intake System', 'Overpressure Systems', 'PWR_EF', 'Any system intended to artificially increase the pressure of the intake air is prohibited. The use of turbochargers, superchargers or any other forced induction system is strictly forbidden.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.3.2', 'C.2.3.2', 'C', 2, 'Air Intake System', 'Overpressure Systems', 'PWR_EF', 'Only passive pressure effects generated by the vehicle motion (ram-air effect) through aerodynamic air intakes are permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.4.1', 'C.2.4.1', 'C', 2, 'Air Intake System', 'Airbox and Air Filtering', 'PWR_EF', 'The design and construction of the airbox are free, provided that it complies with these Technical Regulations.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.4.2', 'C.2.4.2', 'C', 2, 'Air Intake System', 'Airbox and Air Filtering', 'PWR_EF', 'The use of an airbox incorporating an air filter is mandatory.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.4.3', 'C.2.4.3', 'C', 2, 'Air Intake System', 'Airbox and Air Filtering', 'PWR_EF', 'The internal volume of the airbox must not be less than 2.4 liters.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.4.4', 'C.2.4.4', 'C', 2, 'Air Intake System', 'Airbox and Air Filtering', 'PWR_EF', 'The air filter must be specifically intended for engine air intake applications. Its design, dimensions and filtering media are free, provided that it ensures adequate filtration and protects the engine from dust, debris or foreign particles that could cause damage. The use of commercial air filters or equivalent self-designed filtration solutions is permitted.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.4.5', 'C.2.4.5', 'C', 2, 'Air Intake System', 'Airbox and Air Filtering', 'PWR_EF', 'The intake system must be securely mounted and designed to prevent the ingestion of foreign objects.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.2.5.1', 'C.2.5.1', 'C', 2, 'Air Intake System', 'Recycling of gases', 'PWR_EF', 'Recycling of engine breather gases is permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.5.2', 'C.2.5.2', 'C', 2, 'Air Intake System', 'Recycling of gases', 'PWR_EF', 'A closed breather system directing crankcase gases to the intake system is allowed. These breather lines may include filtration devices and oil catch tanks.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.2.5.3', 'C.2.5.3', 'C', 2, 'Air Intake System', 'Recycling of gases', 'PWR_EF', 'If the recycling system described in Art. C.2.5.2 is not implemented, a breather duct must be installed to discharge oil residues into a dedicated oil catch tank with a minimum capacity of 200 cc.', 'requirement', 'required', 'design', null, true, '[]'::jsonb)
on conflict (clause_key) do update set
  printed_ref = excluded.printed_ref, section = excluded.section,
  article = excluded.article, article_title = excluded.article_title,
  group_title = excluded.group_title, subteam_key = excluded.subteam_key,
  body = excluded.body, obligation = excluded.obligation,
  criticality = excluded.criticality, phase = excluded.phase,
  milestone_key = excluded.milestone_key,
  is_team_duty = excluded.is_team_duty, specs = excluded.specs;

insert into clauses (clause_key, printed_ref, section, article, article_title, group_title, subteam_key, body, obligation, criticality, phase, milestone_key, is_team_duty, specs) values
  ('C.2.5.4', 'C.2.5.4', 'C', 2, 'Air Intake System', 'Recycling of gases', 'PWR_EF', 'Under no circumstances may breather gases or oil residues be discharged directly onto the track or onto any part of the prototype not intended for this purpose.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.3.1.1', 'C.3.1.1', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'Fuel tanks, regardless of their design or manufacturing material, must be fully filled with flame-retardant mousse-type safety foam (preferably Explosafe, ExploStop, Baffle Foam ATL, Fuel Safe or an equivalent motorsport safety foam compatible with gasoline fuels containing renewable components, ethanol, other alcohols and oxygenated compounds) intended to reduce fuel movement and minimize explosion risks in case of impact. Picture 31 - Example of flame-retardant foam', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.1.2', 'C.3.1.2', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'It is mandatory to install a breather duct in the fuel tank to prevent possible overpressures. This duct must be fitted with a retention valve that allows the free circulation of air (fuel vapours) but prevents the circulation of liquids (fuel), in order to avoid fuel spills in case of an accident. The outlet of the breather line must be connected to a recovery container specifically installed for this purpose, with a minimum capacity of 250 cc.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.1.3', 'C.3.1.3', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'The main structure of the fuel tank must be made entirely of steel or aluminium. The use of composite materials (such as carbon fibre, aramid fibre or glass fibre) or polymeric materials is permitted only as secondary structural elements, external protection or reinforcement of the tank. Composite or polymeric materials must not constitute the primary fuel containment structure.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.1.4', 'C.3.1.4', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'The lowest part of the fuel tank must be located above the height of the engine intake valves.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.1.5', 'C.3.1.5', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'The fuel tank cap must be fitted with a threaded opening and closing system. Lockable caps are not permitted.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.1.6', 'C.3.1.6', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'The fuel tank cap must ensure a watertight seal that prevents any fuel leakage in the event of a fall or accident.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.1.7', 'C.3.1.7', 'C', 3, 'Fuel Supply System', 'Fuel Tank', 'PWR_EF', 'All materials and components used in the fuel system, including fuel tank, internal components, hoses, connectors, pump, filters, seals and fittings, must be compatible with gasoline fuels containing renewable components ethanol, other alcohols and oxygenated compounds as specified by the Competition Organization.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.2.1', 'C.3.2.1', 'C', 3, 'Fuel Supply System', 'Fuel Pipes', 'PWR_EF', 'All fuel pipes running from the tank to the carburettor or to the injection system must be fitted with at least one self-closing valve (quick connector). This connector must automatically close in the event of disconnection, so that if the tank becomes detached from the motorcycle it is the connector that disconnects rather than another section of the fuel line. The force required to disconnect the connector must be, at maximum, 50% of the force required to loosen any other connection or to cause breakage of the pipe material. Picture 32 - Example of self-closing quick connector', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.2.2', 'C.3.2.2', 'C', 3, 'Fuel Supply System', 'Fuel Pipes', 'PWR_EF', 'Fuel pipes must be securely mounted and routed in such a way that they are protected from mechanical damage, excessive heat exposure or accidental disconnection during operation.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.2.3', 'C.3.2.3', 'C', 3, 'Fuel Supply System', 'Fuel Pipes', 'PWR_EF', 'Fuel hoses, seals, connectors and related components must be compatible with gasoline fuels containing renewable components and oxygenated compounds.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.3.1', 'C.3.3.1', 'C', 3, 'Fuel Supply System', 'Injection system', 'PWR_EF', 'Replacement or modification of the original fuel supply system of the supplied engine is allowed. Both carburetion and electronic fuel injection systems are permitted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.3.3.2', 'C.3.3.2', 'C', 3, 'Fuel Supply System', 'Injection system', 'PWR_EF', 'The fuel injector must be installed upstream of the intake valves of the cylinder. Direct fuel injection into the combustion chamber is not allowed.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.3.3', 'C.3.3.3', 'C', 3, 'Fuel Supply System', 'Injection system', 'PWR_EF', 'The injector supplied with the MotoStudent kit must be used in the throttle body and must remain unmodified (same brand and reference).', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.3.4', 'C.3.3.4', 'C', 3, 'Fuel Supply System', 'Injection system', 'PWR_EF', 'Article C.1.1.1 also applies to the injector body delivered with the MotoStudent Kit as part of the internal combustion engine.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.3.4.1', 'C.3.4.1', 'C', 3, 'Fuel Supply System', 'Fuel Cooling', 'PWR_EF', 'Artificial cooling of the fuel is not allowed. Only passive cooling resulting from the aerodynamic design of the prototype may be used for the fuel system.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.3.5.1', 'C.3.5.1', 'C', 3, 'Fuel Supply System', 'Fuel Pressure', 'PWR_EF', 'Only one fuel pump may be installed. There are no restrictions regarding the type of pump used.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.3.5.2', 'C.3.5.2', 'C', 3, 'Fuel Supply System', 'Fuel Pressure', 'PWR_EF', 'Fuel pressure must not exceed 3.5 bar at any point of the supply circuit.', 'prohibition', 'required', 'design', null, true, '[{"op": "max", "value": 3.5, "unit": "bar"}]'::jsonb),
  ('C.3.5.3', 'C.3.5.3', 'C', 3, 'Fuel Supply System', 'Fuel Pressure', 'PWR_EF', 'Refuelling operations must be carried out using a non-pressurized container.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.3.5.4', 'C.3.5.4', 'C', 3, 'Fuel Supply System', 'Fuel Pressure', 'PWR_EF', 'Artificial pressurization of the fuel tank is strictly forbidden.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.3.5.5', 'C.3.5.5', 'C', 3, 'Fuel Supply System', 'Fuel Pressure', 'PWR_EF', 'The fuel supply system must be designed and installed in a way that prevents fuel leakage during normal operation, vibration or accidental impacts.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.4.1.1', 'C.4.1.1', 'C', 4, 'Fuel And Lubricants', 'Fuel', 'PWR_EF', 'The fuel used during the Final Event of the Competition shall be the Official Fuel specified and supplied by the Competition Organization. During the Final Event, at all times and for any use related to the prototype, only the Official Fuel distributed by the Competition Organization may be used. The use, storage or refuelling of any other fuel by the teams during the Final Event is not permitted. The Official Fuel supplied during the Final Event is not provided free of charge. Teams must acquire it through the official MotoStudent Store during the Final Event. The technical specifications, commercial conditions and relevant information of the Official Fuel will be communicated to all registered teams through the official documentation of the Competition. Such publication is intended to assist the teams, but does not exempt them from their responsibility to ensure fuel-system compatibility and correct engine calibration.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.4.1.2', 'C.4.1.2', 'C', 4, 'Fuel And Lubricants', 'Fuel', 'PWR_EF', 'During the development phase of the prototype, teams may use commercially available unleaded gasoline for testing and calibration purposes. The Official Fuel used during the Final Event has combustion characteristics comparable to commercially available gasoline fuels typically available in international markets. Teams are responsible for ensuring the compatibility of their fuel system, engine calibration and materials with the Official Fuel.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.4.1.3', 'C.4.1.3', 'C', 4, 'Fuel And Lubricants', 'Fuel', 'PWR_EF', 'Any alteration of the fuel by means of additives, blending, chemical treatments or any other modification is strictly forbidden.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.4.1.4', 'C.4.1.4', 'C', 4, 'Fuel And Lubricants', 'Fuel', 'PWR_EF', 'At any time during the Competition, the Organization may require fuel samples from any participating team for verification purposes. If the fuel used is found not to correspond to the Official Fuel supplied by the Organization, the team may be disqualified from the test in progress or from the Competition.', 'info', 'blocking', 'design', null, true, '[]'::jsonb),
  ('C.4.1.5', 'C.4.1.5', 'C', 4, 'Fuel And Lubricants', 'Fuel', 'PWR_EF', 'The Official Fuel complies with the applicable chemical requirements established within the European Union. Teams from non-EU countries should take into account that fuels available in their countries may have different chemical compositions and should consider this during engine calibration and prototype development.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.4.1.6', 'C.4.1.6', 'C', 4, 'Fuel And Lubricants', 'Fuel', 'PWR_EF', 'The Competition Organization will keep a reference sample of the Official Fuel used during the Competition. This reference sample may be used as the baseline for any fuel verification, comparison or dispute regarding fuel compliance. The decision of the Competition Organization based on this reference fuel shall be final.', 'requirement', 'required', 'design', null, false, '[]'::jsonb),
  ('C.4.2.1', 'C.4.2.1', 'C', 4, 'Fuel And Lubricants', 'Engine lubricating oil', 'PWR_EF', 'The lubricating oil is free choice. However, the selected oil must be suitable for high-performance four-stroke motorcycle engines and compatible with the specifications and viscosity grades recommended by the engine manufacturer.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.4.2.2', 'C.4.2.2', 'C', 4, 'Fuel And Lubricants', 'Engine lubricating oil', 'PWR_EF', 'The installation of radiators to cool the engine oil is not allowed.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.4.2.3', 'C.4.2.3', 'C', 4, 'Fuel And Lubricants', 'Engine lubricating oil', 'PWR_EF', 'The oil filler cap, oil drainage plug and oil filter cap bolts must be safety wired in order to prevent oil leakages during the MS2 phase. Engines are delivered to the teams with the required bolts already safety wired as a reference.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.5.1.1', 'C.5.1.1', 'C', 5, 'Cooling System', 'Cooling systems design', 'PWR_EF', 'The design and manufacturing of the external cooling system is free.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.5.1.2', 'C.5.1.2', 'C', 5, 'Cooling System', 'Cooling systems design', 'PWR_EF', 'The number, position, size and material of the cooling radiators and associated cooling components are free, provided that they comply with the dimensional limits of the prototype defined in these Rules and Regulations.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.5.1.3', 'C.5.1.3', 'C', 5, 'Cooling System', 'Cooling systems design', 'PWR_EF', 'The cooling system must be securely installed and designed to prevent coolant leaks during normal operation or in the event of a crash.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.5.1.4', 'C.5.1.4', 'C', 5, 'Cooling System', 'Cooling systems design', 'PWR_EF', 'Any cooling system components must not present sharp edges or protrusions that may create safety hazards for the rider or other participants.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.5.1.5', 'C.5.1.5', 'C', 5, 'Cooling System', 'Cooling systems design', 'PWR_EF', 'Cooling airflow may be improved by aerodynamic design of ducts, fairings or radiator positioning.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.5.2.1', 'C.5.2.1', 'C', 5, 'Cooling System', 'Cooling fluids', 'PWR_EF', 'Only distilled water may be used as cooling fluid. Recommended operating range: 80–90 °C Maximum allowed: 105 °C', 'constraint', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.5.2.2', 'C.5.2.2', 'C', 5, 'Cooling System', 'Cooling fluids', 'PWR_EF', 'The use of additives, glycol, antifreeze agents or any other chemical products in the cooling fluid is forbidden.', 'prohibition', 'info', 'design', null, true, '[]'::jsonb),
  ('C.5.2.3', 'C.5.2.3', 'C', 5, 'Cooling System', 'Cooling fluids', 'PWR_EF', 'Any coolant overflow outlet must discharge into a recovery container in order to prevent coolant being released onto the track. The recovery container must be securely mounted on the prototype.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.6.1.1', 'C.6.1.1', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'The design and manufacturing of the exhaust system is free, provided that it complies with the dimensional requirements of the prototype and the noise limits defined in these Rules & Regulations.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.6.1.2', 'C.6.1.2', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'No mobile or variable geometry devices are allowed in the exhaust system downstream of the engine exhaust valves (e.g. exhaust valves, movable deflectors or similar devices).', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.6.1.3', 'C.6.1.3', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'The exhaust system must be securely mounted and designed to avoid contact with the rider, tyres or other safety-critical components.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.6.1.4', 'C.6.1.4', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'Exhaust gases must not be directed towards the tyres, brakes or rider in a way that may create safety risks.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.6.1.5', 'C.6.1.5', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'The use of a lambda (oxygen) sensor is compulsory. The lambda value must be recorded at any time the engine is running. The data acquisition system must record lambda values, and the Competition Organization may request these data at any time during the Competition.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.6.1.6', 'C.6.1.6', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'Lambda sensors may only be used for monitoring and engine calibration purposes. The use of lambda signals for active engine control strategies such as traction control or similar rider-assistance systems is not allowed.', 'info', 'info', 'design', null, true, '[]'::jsonb),
  ('C.6.1.7', 'C.6.1.7', 'C', 6, 'Exhaust System', 'Exhaust system design', 'PWR_EF', 'For safe engine operation, the recommended lambda operating range is between 0.85 and 0.88 under normal engine load conditions. The lambda value must not exceed 0.95 during normal engine operation. Short transient conditions occurring during gear shifts or throttle transitions may be disregarded. The Competition Organization reserves the right to review recorded engine data in order to determine whether an engine failure may have resulted from operation outside safe limits.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.6.2.1', 'C.6.2.1', 'C', 6, 'Exhaust System', 'Noise', 'PWR_EF', 'The maximum noise level allowed for the exhaust is 105 dB(A) measured statically at 6,000 rpm. No tolerance will be applied during the initial technical inspection. After a race session, a tolerance of +3 dB(A) may be applied.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.1.1', 'C.7.1.1', 'C', 7, 'Transmission System', 'Clutch', 'PWR_EF', 'The original clutch type must be maintained.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.7.1.2', 'C.7.1.2', 'C', 7, 'Transmission System', 'Clutch', 'PWR_EF', 'Clutch discs may be replaced.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.1.3', 'C.7.1.3', 'C', 7, 'Transmission System', 'Clutch', 'PWR_EF', 'Clutch springs may be replaced.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.1.4', 'C.7.1.4', 'C', 7, 'Transmission System', 'Clutch', 'PWR_EF', 'The clutch basket may be replaced provided that the replacement does not require any modification of the engine crankcase or internal engine components.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.1.5', 'C.7.1.5', 'C', 7, 'Transmission System', 'Clutch', 'PWR_EF', 'The installation of clutch systems with limited slip (anti-skid or anti-bounce type) is allowed and recommended.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.2.1', 'C.7.2.1', 'C', 7, 'Transmission System', 'Gearbox', 'PWR_EF', 'The original gearbox integrated in the supplied engine must be used and shares the lubrication system with the engine.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.7.2.2', 'C.7.2.2', 'C', 7, 'Transmission System', 'Gearbox', 'PWR_EF', 'The original gearbox cannot be replaced or internally modified.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.7.2.3', 'C.7.2.3', 'C', 7, 'Transmission System', 'Gearbox', 'PWR_EF', 'External quickshifter systems are allowed provided that they operate only by interrupting ignition during gear shifts.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.7.2.4', 'C.7.2.4', 'C', 7, 'Transmission System', 'Gearbox', 'PWR_EF', 'The shift lever may be replaced.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.3.1', 'C.7.3.1', 'C', 7, 'Transmission System', 'Secondary transmission', 'PWR_EF', 'Only chain-driven secondary transmission systems are allowed.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.7.3.2', 'C.7.3.2', 'C', 7, 'Transmission System', 'Secondary transmission', 'PWR_EF', 'The gearbox output pinion may be replaced. Variations in geometry and number of teeth are allowed, provided that the modification does not require any alteration of the gearbox or engine components.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.7.3.3', 'C.7.3.3', 'C', 7, 'Transmission System', 'Secondary transmission', 'PWR_EF', 'The rear wheel sprocket and the chain are free choice.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.7.3.4', 'C.7.3.4', 'C', 7, 'Transmission System', 'Secondary transmission', 'PWR_EF', 'The secondary transmission system must include adequate protection devices in order to prevent injuries to the rider or damage in case of chain failure.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.1.1', 'C.8.1.1', 'C', 8, 'Electric Installation', 'ECU', 'PWR_EF', 'Only the Engine Control Unit (ECU) specified and published by the MotoStudent Organization in the MotoStudent Approved Parts List may be used.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.8.1.2', 'C.8.1.2', 'C', 8, 'Electric Installation', 'ECU', 'PWR_EF', 'Under no circumstances may the signals from sensors integrated in the engine be modified, intercepted or distorted. This includes any attempt to bypass or exceed the engine speed limit defined by the ECU (13,500 rpm). The engine speed limit may be verified by the Technical Staff of the Organization at any time during the Final Event. Any device, software modification or wiring alteration intended to modify the original ECU engine speed limitation is strictly prohibited.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.8.1.3', 'C.8.1.3', 'C', 8, 'Electric Installation', 'ECU', 'PWR_EF', 'Ignition and injection adjustments are limited to those permitted by the ECU tuning software under the official user license. Base maps must not be modified. Any team modifying parameters not permitted by the official software license will be disqualified from the test in which the team has participated since the last ECU verification.', 'prohibition', 'blocking', 'design', null, true, '[]'::jsonb),
  ('C.8.1.4', 'C.8.1.4', 'C', 8, 'Electric Installation', 'ECU', 'PWR_EF', 'The MotoStudent Organization may request to connect to the ECU and download its configuration at any time during the Competition. Teams must ensure that the necessary means are available to allow the Organization to perform this verification. Failure to provide access will be considered non-compliance with Article C.8.1.3.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.2.1', 'C.8.2.1', 'C', 8, 'Electric Installation', 'Battery', 'PWR_EF', 'It is compulsory to install a battery with an operating voltage between 8 V to 18 V.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.8.3.1', 'C.8.3.1', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'The configuration of the electrical installation is free.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.8.3.2', 'C.8.3.2', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'The use of commercial electrical systems or components is allowed.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.8.3.3', 'C.8.3.3', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'Cable types, wiring design and routing are free provided that the installation is properly insulated and securely mounted.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.8.3.4', 'C.8.3.4', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'The connector type is free. Teams must ensure that the electrical system operates correctly under wet conditions.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.3.5', 'C.8.3.5', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'Commercial components such as coils, batteries, regulators and connectors may be used.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.8.3.6', 'C.8.3.6', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'All prototypes must be equipped with an engine kill switch located on the left-hand side of the handlebar. The switch must be clearly marked in red and easily accessible in case of emergency. The rider must be able to activate the switch while keeping both hands on the handlebar grips. The switch must immediately stop the engine when activated.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.3.7', 'C.8.3.7', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'Only one ignition coil may be used.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.8.3.8', 'C.8.3.8', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'The electrical installation must be properly integrated into the prototype structure. All wiring must be securely fixed and protected.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.3.9', 'C.8.3.9', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'Excess wiring must not be coiled or loosely installed. Cable lengths must be appropriate for their installation.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.3.10', 'C.8.3.10', 'C', 8, 'Electric Installation', 'Electric installation', 'PWR_EF', 'Electrical wiring must be routed away from hot components such as the engine, exhaust system and cooling system. Electrical cables and components must not be in direct contact with parts that may reach high temperatures.', 'prohibition', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.4.1', 'C.8.4.1', 'C', 8, 'Electric Installation', 'Start System', 'PWR_EF', 'The electric starter system integrated in the official engine must remain operational and may not be removed.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.4.2', 'C.8.4.2', 'C', 8, 'Electric Installation', 'Start System', 'PWR_EF', 'In the event of a malfunction of the electric starter during the start procedure of a race session, external starting devices are not allowed. In case of failure, the motorcycle may only be started by pushing.', 'info', 'info', 'design', null, true, '[]'::jsonb),
  ('C.8.5.1', 'C.8.5.1', 'C', 8, 'Electric Installation', 'Data Logging', 'PWR_EF', 'The use of a data logging system is compulsory. Commercial loggers are recommended.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.8.5.2', 'C.8.5.2', 'C', 8, 'Electric Installation', 'Data Logging', 'PWR_EF', 'Engine speed, engine temperature and lambda value must be monitored and recorded whenever the engine is running, from the first engine start until the end of the Final Event.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.5.3', 'C.8.5.3', 'C', 8, 'Electric Installation', 'Data Logging', 'PWR_EF', 'Logged data must be stored by the team and must be made available to the Competition Organization at any time upon request during the Competition and particularly during the Final Event.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.5.4', 'C.8.5.4', 'C', 8, 'Electric Installation', 'Data Logging', 'PWR_EF', 'The Competition Organization may require the download and submission of data logs at any time during the Final Event, including after any session or test.', 'info', 'info', 'design', null, false, '[]'::jsonb),
  ('C.8.5.5', 'C.8.5.5', 'C', 8, 'Electric Installation', 'Data Logging', 'PWR_EF', 'Teams must ensure that the necessary hardware, software and connection means are available to allow the Competition Organization to access the recorded data. Failure to provide access to the data may be considered a technical non- conformity.', 'requirement', 'required', 'design', null, true, '[]'::jsonb),
  ('C.8.5.6', 'C.8.5.6', 'C', 8, 'Electric Installation', 'Data Logging', 'PWR_EF', 'Logged data should preferably be provided in CSV or another widely accessible format. The Competition Organization may also request the original native data format generated by the ECU or data logging system.', 'info', 'recommended', 'design', null, false, '[]'::jsonb),
  ('C.8.6.1', 'C.8.6.1', 'C', 8, 'Electric Installation', 'Launch Control and Traction Control', 'PWR_EF', 'Launch Control and Traction Control functions integrated in the homologated MotoStudent eFuel ECU may be used as the only exception to Article B.10.1.1. No additional Launch Control or Traction Control systems are allowed. SECTI ON D: SPE CIFIC TE CHNI CAL REG ULATIONS FOR THE CATEGORY “MOT OSTUDENT E LECT RIC” SECTION D SPECIFIC TECHNICAL REGULATIONS FOR THE CATEGORY “MOTOSTUDENT ELECTRIC”', 'info', 'penalty', 'design', null, true, '[]'::jsonb),
  ('E.1.1.1', 'E.1.1.1', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'The objective of the Scrutineering is to verify that the prototypes presented by the participating teams comply with the performance and safety requirements established in the Technical Regulations (Sections B, C and D), and to verify that the rider designated by the team is eligible to participate in the MS2 Phase of the Competition.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.2', 'E.1.1.2', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'Scrutineering does not award points in the MotoStudent International Competition. However, it may result in the exclusion of a prototype or rider if any deviation from the Rules & Regulations is detected or if the prototype is not considered sufficiently safe to participate in the tests.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.3', 'E.1.1.3', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'Scrutineering will be carried out by experienced scrutineers and qualified Technical Staff of the Competition Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.4', 'E.1.1.4', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'In the event of any dispute regarding compliance with the Technical Regulations or the safety of a prototype on track, the decision of the Technical Staff of the Competition Organization shall be final.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.1.1.5', 'E.1.1.5', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'The values measured using the Organization’s instruments shall be considered final.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.6', 'E.1.1.6', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'Passing Scrutineering does not constitute technical approval, certification or homologation of the prototype design by the Competition Organization. Scrutineering only verifies compliance with the Technical Regulations based on the inspections and tests carried out at the moment of the check.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.7', 'E.1.1.7', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'The responsibility for the design, construction, safety and operation of the prototype remains entirely with the team at all times. The fact that a prototype has passed Scrutineering or has been allowed to participate in any activity of the Competition does not transfer any responsibility to the Competition Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.8', 'E.1.1.8', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'Scrutineering approval only applies to the condition of the prototype at the time of inspection. Any modification, adjustment, repair or replacement of components carried out after the inspection may require a new verification by the Technical Staff of the Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.1.9', 'E.1.1.9', 'E', 1, 'Objective And Methodology', 'Objective', 'SCRUT', 'The Competition Organization reserves the right to perform additional inspections at any time during the Competition if it considers that the safety or regulatory compliance of a prototype may have been affected.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.2.1', 'E.1.2.1', 'E', 1, 'Objective And Methodology', 'Responsibility of the teams', 'SCRUT', 'Teams are solely responsible for ensuring that their prototype complies with all the requirements established in the Technical Regulations of the Competition.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.2.2', 'E.1.2.2', 'E', 1, 'Objective And Methodology', 'Responsibility of the teams', 'SCRUT', 'By presenting a prototype for Scrutineering, the team declares that it has verified that the prototype complies with the Rules & Regulations established by the Competition Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.2.3', 'E.1.2.3', 'E', 1, 'Objective And Methodology', 'Responsibility of the teams', 'SCRUT', 'Teams must present the prototype in a condition suitable for inspection and must facilitate access to all areas, systems and components that may need to be checked during Scrutineering.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.1.2.4', 'E.1.2.4', 'E', 1, 'Objective And Methodology', 'Responsibility of the teams', 'SCRUT', 'Teams must provide any technical information, documentation, tools, connectors or support elements that may be required by the Competition Organization to carry out the inspection.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.1.3.1', 'E.1.3.1', 'E', 1, 'Objective And Methodology', 'Procedure', 'SCRUT', 'Scrutineering consists of the following stages:
- Administrative Check
- Static Scrutineering
- Dynamic Safety Check', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.3.2', 'E.1.3.2', 'E', 1, 'Objective And Methodology', 'Procedure', 'SCRUT', 'A prototype may be rejected at any stage of Scrutineering if it does not comply with the Rules & Regulations or if it is considered unsafe.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.3.3', 'E.1.3.3', 'E', 1, 'Objective And Methodology', 'Procedure', 'SCRUT', 'If a non-conformity is detected, the Competition Organization may allow the team to correct the issue and present the prototype again for reinspection, provided that the official schedule allows it.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.1.3.4', 'E.1.3.4', 'E', 1, 'Objective And Methodology', 'Procedure', 'SCRUT', 'The order, scope and detailed methodology of the Scrutineering may be defined by the Competition Organization in the corresponding official documentation.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.2.1.1', 'E.2.1.1', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'At the beginning of the Final Event, teams must perform the Administrative Check, during which the Competition Organization will verify that the rider and the team comply with the administrative and federative requirements established for participation in the Competition.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.2.1.2', 'E.2.1.2', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'Once these requirements have been verified and approved, the corresponding Administrative Check sticker will be placed on the prototype, allowing the team to proceed to the next Scrutineering stage. Figure 37 - Administrative Check sticker example', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.2.1.3', 'E.2.1.3', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'The Administrative Check will be carried out at the Paddock General Office.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.2.1.4', 'E.2.1.4', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'Teams will not be allowed to access the Static Scrutineering stage without having successfully passed the Administrative Check.', 'verification', 'blocking', 'scrutineering', null, true, '[]'::jsonb),
  ('E.2.1.5', 'E.2.1.5', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'During the Administrative Check, the Organization may verify the following documentation:
- Rider Identification Document (ID card or passport)
- Rider’s federative license
- “Start permission” issued by the rider’s national federation when required
- Any additional documentation required by the Competition Organization', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.2.1.6', 'E.2.1.6', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'If the rider arrives at the Final Event later than the rest of the team, the team may perform the Administrative Check by presenting the rider’s identification document, federative license and start permission (if required). In such case, the rider must personally attend the Administrative Check location upon arrival to confirm participation and complete the required signatures.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.2.1.7', 'E.2.1.7', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'The Competition Organization reserves the right to request additional verification of the rider eligibility or documentation if necessary.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.2.1.8', 'E.2.1.8', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'Teams that fail to comply with the administrative or federative requirements may not proceed to the Static Scrutineering stage until the situation has been resolved.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.2.1.9', 'E.2.1.9', 'E', 2, 'Administrative Check', 'Process', 'SCRUT', 'The schedule, time slots and operational procedure for the Administrative Check will be defined in the official documentation of the Final Event.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.1.1', 'E.3.1.1', 'E', 3, 'Static Scrutineering', 'Process', 'SCRUT', 'Static Scrutineering consists of a series of checks performed on the prototype to verify its compliance with the Competition Technical Regulations and to assess whether the prototype is safe to participate in the MS2 Phase.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.1.2', 'E.3.1.2', 'E', 3, 'Static Scrutineering', 'Process', 'SCRUT', 'Rider protective equipment may also be verified during Static Scrutineering to confirm that it is appropriate for participation in the Competition.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.1.3', 'E.3.1.3', 'E', 3, 'Static Scrutineering', 'Process', 'SCRUT', 'The scrutineering checks described in this article apply to prototypes presented in both the MotoStudent eFuel and MotoStudent Electric categories.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.2.1', 'E.3.2.1', 'E', 3, 'Static Scrutineering', 'Development', 'SCRUT', 'Static Scrutineering will be carried out in the Technical Control Area designated by the Competition Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.2.2', 'E.3.2.2', 'E', 3, 'Static Scrutineering', 'Development', 'SCRUT', 'The prototype must be presented in a condition ready for inspection and suitable for participation in the MS2 Phase, complying with all the requirements established in the Competition Rules & Regulations.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.3.2.3', 'E.3.2.3', 'E', 3, 'Static Scrutineering', 'Development', 'SCRUT', 'The prototype must be fully assembled and capable of being inspected without requiring major disassembly operations. Scrutineers may request the removal of fairings or other components if required for inspection.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.3.2.4', 'E.3.2.4', 'E', 3, 'Static Scrutineering', 'Development', 'SCRUT', 'The use during the Competition of components or configurations that have not been verified during Static Scrutineering may result in exclusion from the Competition.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.2.5', 'E.3.2.5', 'E', 3, 'Static Scrutineering', 'Development', 'SCRUT', 'Only two (2) Team Members are allowed to access the Technical Control Area during Static Scrutineering. These members will be responsible for transporting the prototype and presenting it in a stable static position suitable for inspection.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.2.6', 'E.3.2.6', 'E', 3, 'Static Scrutineering', 'Development', 'SCRUT', 'The team must bring all tools necessary to remove the prototype fairings and to provide access to the components required for inspection.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.3.3.1', 'E.3.3.1', 'E', 3, 'Static Scrutineering', 'Visual check', 'SCRUT', 'During this check, scrutineers will visually inspect the prototype in order to verify compliance with the Technical Regulations defined in Section B and other applicable sections of the Rules & Regulations.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.4.1', 'E.3.4.1', 'E', 3, 'Static Scrutineering', 'Weight check', 'SCRUT', 'During this check, the prototype will be weighed using two scales, one placed under the front wheel and the other under the rear wheel.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.4.2', 'E.3.4.2', 'E', 3, 'Static Scrutineering', 'Weight check', 'SCRUT', 'The total weight of the prototype will be determined as the sum of the values measured on both scales.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.4.3', 'E.3.4.3', 'E', 3, 'Static Scrutineering', 'Weight check', 'SCRUT', 'The measured weight must be equal to or greater than the minimum weight defined in Article B.2.2.1.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.4.4', 'E.3.4.4', 'E', 3, 'Static Scrutineering', 'Weight check', 'SCRUT', 'The weight measured using the Organization’s scales will be considered final.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.5.1', 'E.3.5.1', 'E', 3, 'Static Scrutineering', 'Load check', 'SCRUT', 'During this check, the prototype will be subjected to horizontal and vertical loads in order to verify the structural rigidity of the frame, the correct assembly of the main structural elements and the behaviour of the suspension systems.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.5.2', 'E.3.5.2', 'E', 3, 'Static Scrutineering', 'Load check', 'SCRUT', 'The following loads will be progressively applied to the prototype in order to evaluate structural behaviour:
- 250 kg applied on the saddle area
- 300 kg applied on the front wheel Picture 38 - Load test forces diagram', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.5.3', 'E.3.5.3', 'E', 3, 'Static Scrutineering', 'Load check', 'SCRUT', 'These loads will be applied progressively and alternately while verifying that no structural failure, interference between components or unsafe deformation occurs. If any unsafe structural behaviour is detected during this test, the scrutineers may stop the test and declare the prototype non-compliant.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.6.1', 'E.3.6.1', 'E', 3, 'Static Scrutineering', 'Brake check', 'SCRUT', 'During this check, the braking performance of the front and rear brake systems will be tested using a roller brake tester. Picture 39 - Brake check', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.6.2', 'E.3.6.2', 'E', 3, 'Static Scrutineering', 'Brake check', 'SCRUT', 'The braking force measured must exceed the following minimum values:
- Front axle: 0.3 kN
- Rear axle: 0.25 kN If abnormal behaviour of the braking system is detected during the test (such as inconsistent force, excessive lever travel or system malfunction), the scrutineers may declare the prototype non-compliant even if the minimum values are reached.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.3.6.3', 'E.3.6.3', 'E', 3, 'Static Scrutineering', 'Brake check', 'SCRUT', 'The values measured using the Organization’s equipment will be considered final.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.3.7.1', 'E.3.7.1', 'E', 3, 'Static Scrutineering', 'Approval', 'SCRUT', 'If the prototype successfully passes all the static checks described in this article (including those specific to each category), the corresponding Static Scrutineering sticker will be placed on the prototype. Once approved, the prototype will be allowed to proceed to the Dynamic Safety Check stage. Picture 40 - Static Scrutineering sticker', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.1.1', 'E.4.1.1', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Visual check', 'SCRUT', 'During this check, scrutineers will visually inspect the prototype in order to verify compliance with the Technical Regulations defined in Section C.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.1.2', 'E.4.1.2', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Visual check', 'SCRUT', 'This inspection will be performed as part of the visual inspection described in Article E.3.3.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.1', 'E.4.2.1', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'During this check, the exhaust noise emitted by the prototype will be measured.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.2', 'E.4.2.2', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The maximum permitted exhaust noise level is defined in Article C.6.2 of the Technical Regulations.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.3', 'E.4.2.3', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The sound level meter will be positioned approximately 50 cm from the end of the exhaust outlet at an angle of 45° relative to the centreline of the exhaust pipe and at the same height as the exhaust outlet, but at least 20 cm above the ground. If this position cannot be achieved, the measurement may be taken at a 45° upward angle from the exhaust outlet.', 'verification', 'recommended', 'scrutineering', null, true, '[{"op": "min", "value": 20.0, "unit": "cm"}]'::jsonb),
  ('E.4.2.4', 'E.4.2.4', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The noise test must be carried out in an open area adjacent to the Technical Control Area, at least 5 meters away from any large reflecting surface such as walls, vehicles or structures.', 'verification', 'required', 'scrutineering', null, true, '[{"op": "min", "value": 5.0, "unit": "meters"}]'::jsonb),
  ('E.4.2.5', 'E.4.2.5', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The engine must run out of gear. The rider or a team member must increase the engine speed until the specified test RPM defined in the Technical Regulations is reached. The sound measurement will be taken once the engine speed stabilizes at the specified RPM.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.4.2.6', 'E.4.2.6', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'During the test, the ambient noise level must not exceed 90 dB(A) within a radius of 5 meters around the measurement area.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.7', 'E.4.2.7', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The sound level meter used by the Competition Organization must be equipped with a calibrator for verification and adjustment during the test period.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.8', 'E.4.2.8', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The sound level meter must be configured to use the “slow response” setting and A-weighted measurement scale.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.9', 'E.4.2.9', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'The value measured using the Organization’s sound level meter will be considered final.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.4.2.10', 'E.4.2.10', 'E', 4, 'Static Scrutineering Specific To “Motostudent Efuel” Category', 'Noise check', 'SCRUT', 'If the prototype exceeds the permitted noise level, the team may be allowed to perform corrective actions and repeat the test if the event schedule allows it.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.1.1', 'E.5.1.1', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Electric visual check', 'SCRUT', 'During this check, scrutineers will visually inspect the prototype in order to verify compliance with the Technical Regulations defined in Section D.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.1.2', 'E.5.1.2', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Electric visual check', 'SCRUT', 'This inspection will be performed as part of the general visual inspection described in Article E.3.3.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.2.1', 'E.5.2.1', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Isolation resistance measurement check', 'SCRUT', 'During this check, the scrutineers will verify the electrical isolation between the High Voltage System (HVS) and the prototype chassis (also the Low Voltage System
- LVS).', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.2.2', 'E.5.2.2', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Isolation resistance measurement check', 'SCRUT', 'The isolation resistance between the High Voltage System and the prototype chassis must be at least 100 Ω/V of the maximum battery pack voltage.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.5.2.3', 'E.5.2.3', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Isolation resistance measurement check', 'SCRUT', 'The isolation measurement will be performed using the Voltage Measuring Point (VMP) defined in Article D.7.3.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.2.4', 'E.5.2.4', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Isolation resistance measurement check', 'SCRUT', 'The measurement method will consist of the following steps:
- The battery pack voltage will be recorded (hereinafter Ub) between the “HV+” and “B–” terminals of the VMP.
- The voltage between the “B–” terminal of the VMP and the prototype chassis will be recorded (hereinafter U1).
- The voltage between the “HV+” terminal of the VMP and the prototype chassis will be recorded (hereinafter U2).
- A resistor Ro will be connected between the terminal presenting the highest voltage value relative to the prototype chassis and the prototype chassis.
- The voltage will then be measured again after the resistor is connected (U1’ or U2’).
- The insulation resistance Ri will then be calculated according to the following formulas: 𝑅𝑖 = 𝑅𝑜 ∗ 𝑈𝑏 ∗ (1⁄ ′ − 1⁄𝑈 ) 𝑖𝑓 𝑈2 > 𝑈1 𝑈2 2 𝑅𝑖 = 𝑅𝑜 ∗ 𝑈𝑏 ∗ (1⁄ ′ − 1⁄𝑈 ) 𝑖𝑓 𝑈1 > 𝑈2 𝑈1 1
- The isolation value will be obtained by dividing Ri by Ub. Picture 41 - Test example for measuring U2'' and U1''', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.2.5', 'E.5.2.5', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Isolation resistance measurement check', 'SCRUT', 'The resistor Ro used for this test must have a value of 15 kΩ.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.1', 'E.5.3.1', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'During this check, the scrutineers will verify the correct operation of the Insulation Monitoring Device (IMD) and the High Voltage System disconnection circuit.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.2', 'E.5.3.2', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'The test will consist of connecting the terminal with the lowest voltage recorded during the previous isolation test (U1 or U2) to the prototype chassis through a 50 kΩ resistor.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.3', 'E.5.3.3', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'When this condition is applied, the IMD must detect the insulation fault and trigger the opening of the HVS disconnection circuit.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.4', 'E.5.3.4', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'The HVS disconnection circuit must open within a maximum time of 30 seconds.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.5', 'E.5.4.5', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', null, 'SCRUT', 'If the IMD does not trigger the shutdown of the High Voltage System within the specified time, the prototype will be considered non-compliant.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.6', 'E.5.3.6', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'The Emergency Shutdown Button (ESDB) and the Traction System Master Switch (TSMS) will also be tested to verify that they correctly open the HVS disconnection circuit.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.7', 'E.5.3.7', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'A disconnection circuit will be considered open when both the line contactor and the charging relay are open.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.3.8', 'E.5.3.8', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'IMD check', 'SCRUT', 'This condition will be verified by measuring the voltage at the VMP terminals:
- The voltage between “B+” and “B–” must be equal to 0 V.
- The voltage between “C+” and “B–” must be equal to 0 V.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.1', 'E.5.4.1', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'This check applies only to prototypes participating in the MotoStudent Electric category.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.2', 'E.5.4.2', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'The purpose of this test is to verify that the electrical insulation of the prototype remains safe under rain or high humidity conditions.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.3', 'E.5.4.3', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'During this test, the High Voltage System must be activated and the drive wheel must be lifted off the ground using an appropriate stand.', 'verification', 'required', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.4', 'E.5.4.4', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'Water will be sprayed over the prototype to simulate light rain conditions from different directions for a minimum duration of 60 seconds. High-pressure water jets must not be used.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.5.4.5#2', 'E.5.4.5', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'The test will be considered successful if the IMD does not trigger during the 60 seconds of spraying and during the following 60 seconds after the spraying has stopped. The minimum total duration of the test will therefore be 120 seconds.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.6', 'E.5.4.6', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'The Technical Staff may also verify that no water accumulates in areas that could compromise the safety of the High Voltage System.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.5.4.7', 'E.5.4.7', 'E', 5, 'Static Scrutineering Specific To “Motostudent Electric” Category', 'Rain check', 'SCRUT', 'Verification that the High Voltage System remains active during the test may be performed by:
- confirming that the motor can operate normally
- measuring the voltage between “B+” and “B–” at the VMP', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.1.1', 'E.6.1.1', 'E', 6, 'Dynamic Safety Check', 'Process', 'SCRUT', 'The Dynamic Safety Check consists of a series of on-track verifications performed by Official Riders appointed by the Competition Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.1.2', 'E.6.1.2', 'E', 6, 'Dynamic Safety Check', 'Process', 'SCRUT', 'The purpose of this stage is to verify that the prototype operates correctly under basic dynamic conditions and that it can safely circulate on track.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.1.3', 'E.6.1.3', 'E', 6, 'Dynamic Safety Check', 'Process', 'SCRUT', 'The checks described in this article apply to prototypes presented in both the "MotoStudent eFuel" and the "MotoStudent Electric" categories.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.1.4', 'E.6.1.4', 'E', 6, 'Dynamic Safety Check', 'Process', 'SCRUT', 'The Dynamic Safety Check is not intended to evaluate the performance of the prototype but only to verify its basic operational safety.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.2.1', 'E.6.2.1', 'E', 6, 'Dynamic Safety Check', 'Procedure', 'SCRUT', 'An Official Rider appointed by the Organization will perform a series of controlled dynamic tests on the track in order to verify the correct functioning of the prototype.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.2.2', 'E.6.2.2', 'E', 6, 'Dynamic Safety Check', 'Procedure', 'SCRUT', 'During these tests the following basic aspects will be verified:
- The prototype must start and move under its own power.
- The prototype must respond correctly to throttle input.
- The prototype must brake correctly under both moderate and higher braking conditions.
- The prototype must be able to complete several turns at different speeds with stable and predictable behaviour.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.6.2.3', 'E.6.2.3', 'E', 6, 'Dynamic Safety Check', 'Procedure', 'SCRUT', 'If the Official Rider detects any malfunction, instability or unsafe behaviour, the test may be stopped immediately. The Official Rider will determine whether the prototype meets the minimum safety requirements necessary to participate in the Competition.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.3.1', 'E.6.3.1', 'E', 6, 'Dynamic Safety Check', 'Lap around the track', 'SCRUT', 'Once the basic checks have been completed, the Official Rider may perform a complete lap of the Speed Racing Track in order to evaluate the general behaviour of the prototype under real track conditions. The completion of this lap is at the discretion of the Official Rider and the Technical Staff of the Organization.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.6.4.1', 'E.6.4.1', 'E', 6, 'Dynamic Safety Check', 'Approval', 'SCRUT', 'If the prototype successfully passes the Dynamic Safety Check, it will be marked with the corresponding approval sticker. Once approved, the team will be allowed to participate in the MS2 Phase of the Competition. Picture 42 - Example of approval sticker', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.1.1', 'E.7.1.1', 'E', 7, 'Changes And Repairs', 'Rectification time', 'SCRUT', 'If a prototype is considered "Not Approved" after any Scrutineering stage, the Organization may grant the team a rectification period in order to correct the detected non-compliances.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.1.2', 'E.7.1.2', 'E', 7, 'Changes And Repairs', 'Rectification time', 'SCRUT', 'During this period, the team must perform the required corrections in their designated paddock or box area.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.7.1.3', 'E.7.1.3', 'E', 7, 'Changes And Repairs', 'Rectification time', 'SCRUT', 'Once the rectification has been completed, the prototype must be presented again at the scrutineering area during the next assigned inspection slot in order to verify compliance with the Rules & Regulations.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.7.1.4', 'E.7.1.4', 'E', 7, 'Changes And Repairs', 'Rectification time', 'SCRUT', 'The Organization reserves the right to limit the number of re-inspection attempts depending on the event schedule.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.1.5', 'E.7.1.5', 'E', 7, 'Changes And Repairs', 'Rectification time', 'SCRUT', 'No prototype will be allowed to participate in the MS2 Phase without successfully passing all required Scrutineering stages within the established timetable.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.1.6', 'E.7.1.6', 'E', 7, 'Changes And Repairs', 'Rectification time', 'SCRUT', 'The MotoStudent Organization reserves the right to refuse access to scrutineering for any prototype once the official scrutineering schedule has concluded.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.2.1', 'E.7.2.1', 'E', 7, 'Changes And Repairs', 'Changes and repairs', 'SCRUT', 'Once a prototype has successfully passed scrutineering and has been approved for participation in the MotoStudent Competition, no modification or replacement of components may be carried out without the authorization of the Technical Director.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.2.2', 'E.7.2.2', 'E', 7, 'Changes And Repairs', 'Changes and repairs', 'SCRUT', 'If a team intends to perform any modification or repair, the Technical Staff of the Organization must be informed beforehand.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.7.2.3', 'E.7.2.3', 'E', 7, 'Changes And Repairs', 'Changes and repairs', 'SCRUT', 'The Organization may require the prototype to be re-inspected before it is allowed to continue participating in the Competition.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.2.4', 'E.7.2.4', 'E', 7, 'Changes And Repairs', 'Changes and repairs', 'SCRUT', 'The following operations are allowed after scrutineering without requiring prior approval from the Organization, provided that they do not alter the safety or structural characteristics of the prototype:
- Secondary transmission adjustments
- Brake system adjustments
- Data acquisition or telemetry adjustments
- Tire pressure adjustments
- Refilling of fluids
- General setup adjustments
- Engine or powertrain setup adjustments', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.7.2.5', 'E.7.2.5', 'E', 7, 'Changes And Repairs', 'Changes and repairs', 'SCRUT', 'Any repair affecting structural, safety-critical or electrical High Voltage components must be approved by the Technical Director before the prototype may return to the track.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.7.2.6', 'E.7.2.6', 'E', 7, 'Changes And Repairs', 'Changes and repairs', 'SCRUT', 'The Technical Director reserves the right to require a partial or full re-inspection of the prototype after any repair.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.8.1.1', 'E.8.1.1', 'E', 8, 'Additional Scrutineering Rounds', 'Additional inspection rounds', 'SCRUT', 'The Organization may perform additional scrutineering inspections at any time during the Final Event in order to verify continued compliance with the Technical Regulations.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.8.1.2', 'E.8.1.2', 'E', 8, 'Additional Scrutineering Rounds', 'Additional inspection rounds', 'SCRUT', 'These inspections may be carried out in the paddock, in the Technical Control Area or on track.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.8.1.3', 'E.8.1.3', 'E', 8, 'Additional Scrutineering Rounds', 'Additional inspection rounds', 'SCRUT', 'Teams must cooperate with the Technical Staff during these inspections and provide access to the prototype if requested.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.8.1.4', 'E.8.1.4', 'E', 8, 'Additional Scrutineering Rounds', 'Additional inspection rounds', 'SCRUT', 'If a non-compliance is detected during an additional inspection round, the Organization may require corrective actions or suspend the prototype from participating in track activities until the issue has been resolved.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.1.1', 'E.9.1.1', 'E', 9, 'Time Control Procedure', 'Inspection scheduling', 'SCRUT', 'At the beginning of the Final Event, each team will be assigned a time slot for their first scrutineering inspection.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.1.2', 'E.9.1.2', 'E', 9, 'Time Control Procedure', 'Inspection scheduling', 'SCRUT', 'The initial inspection schedule will be determined by the Organization and may be based on accreditation time or other operational criteria defined by the Organization.', 'verification', 'recommended', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.1.3', 'E.9.1.3', 'E', 9, 'Time Control Procedure', 'Inspection scheduling', 'SCRUT', 'Teams must present their prototype at the scrutineering area at the assigned time slot.', 'verification', 'required', 'scrutineering', null, true, '[]'::jsonb),
  ('E.9.2.1', 'E.9.2.1', 'E', 9, 'Time Control Procedure', 'Missed inspection slots', 'SCRUT', 'If a team fails to present its prototype at the assigned inspection time, the team may lose its priority and will be reassigned a new time slot depending on the availability of the scrutineering schedule.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.2.2', 'E.9.2.2', 'E', 9, 'Time Control Procedure', 'Missed inspection slots', 'SCRUT', 'The Organization is not responsible for delays caused by teams missing their assigned inspection slots.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.3.1', 'E.9.3.1', 'E', 9, 'Time Control Procedure', 'Re-inspection scheduling', 'SCRUT', 'If a prototype does not pass an inspection stage, the team will be assigned a new inspection time slot for the next verification round.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.3.2', 'E.9.3.2', 'E', 9, 'Time Control Procedure', 'Re-inspection scheduling', 'SCRUT', 'Re-inspection slots will be assigned by the Organization according to the availability of the scrutineering schedule.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.4.1', 'E.9.4.1', 'E', 9, 'Time Control Procedure', 'Publication of schedules', 'SCRUT', 'The scrutineering schedules and re-inspection time slots will be published, if needed, by the Organization through the official communication channels of the event.', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('E.9.4.2', 'E.9.4.2', 'E', 9, 'Time Control Procedure', 'Publication of schedules', 'SCRUT', 'Teams are responsible for checking the assigned times and presenting their prototype accordingly. SECTI ON F: COMPETITI ON STRUCTU RING SECTION F COMPETITION STRUCTURING', 'verification', 'info', 'scrutineering', null, false, '[]'::jsonb),
  ('F.1.1.1', 'F.1.1.1', 'F', 1, 'Objectives', 'Competition Objectives', 'DOCS', 'The MotoStudent International Competition is an advanced educational program based on the complete development of a real racing prototype. Its objective is to prepare young talent for their future professional careers, especially in the mobility and motorsport sectors, by requiring them to work in multidisciplinary teams, make decisions under technical, economic and time constraints, and justify those decisions in a competitive international environment. Through MotoStudent, participants are expected to develop practical skills in engineering, project management, communication, innovation, economic planning, resource management and teamwork, in a context that resembles the challenges of a real industrial project.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.1.2.1', 'F.1.2.1', 'F', 1, 'Objectives', 'MS1 Phase objectives', 'DOCS', 'The objective of the MS1 Phase is to evaluate the quality, maturity and coherence of the team’s project development process before the Final Event.', 'process', 'info', 'ms1', null, false, '[]'::jsonb)
on conflict (clause_key) do update set
  printed_ref = excluded.printed_ref, section = excluded.section,
  article = excluded.article, article_title = excluded.article_title,
  group_title = excluded.group_title, subteam_key = excluded.subteam_key,
  body = excluded.body, obligation = excluded.obligation,
  criticality = excluded.criticality, phase = excluded.phase,
  milestone_key = excluded.milestone_key,
  is_team_duty = excluded.is_team_duty, specs = excluded.specs;

insert into clauses (clause_key, printed_ref, section, article, article_title, group_title, subteam_key, body, obligation, criticality, phase, milestone_key, is_team_duty, specs) values
  ('F.1.2.2', 'F.1.2.2', 'F', 1, 'Objectives', 'MS1 Phase objectives', 'DOCS', 'MS1 is intended to guide teams through the full path of a real prototype development project, from the initial team organization and concept definition to design justification, innovation, technical documentation, economic viability, marketing and final communication of the project.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.1.2.3', 'F.1.2.3', 'F', 1, 'Objectives', 'MS1 Phase objectives', 'DOCS', 'The MS1 Phase is specially focused on assessing how teams think, justify, plan, develop and communicate their project. It is not about which team has the greatest means, but about which team makes the best use of the means available to it.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.1.2.4', 'F.1.2.4', 'F', 1, 'Objectives', 'MS1 Phase objectives', 'DOCS', 'A strong MS1 project should help the team arrive better prepared for the MS2 Phase, reducing uncertainty, improving decision-making and increasing the consistency between the original concept, the manufactured prototype and its final on-track performance.', 'process', 'recommended', 'ms1', null, false, '[]'::jsonb),
  ('F.1.2.5', 'F.1.2.5', 'F', 1, 'Objectives', 'MS1 Phase objectives', 'DOCS', 'Teams must therefore be able to demonstrate to the jury their full project development process, including the technical, organizational, marketing, economic and strategic decisions that support the prototype presented in the Competition.', 'process', 'required', 'ms1', null, true, '[]'::jsonb),
  ('F.1.3.1', 'F.1.3.1', 'F', 1, 'Objectives', 'MS2 Phase objectives', 'DOCS', 'The objective of the MS2 Phase is to evaluate the dynamic behaviour, performance, reliability and competitive consistency of the manufactured prototype under real track conditions.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.1.3.2', 'F.1.3.2', 'F', 1, 'Objectives', 'MS2 Phase objectives', 'DOCS', 'The MS2 Phase is intended to validate, under racing conditions, the ideas, decisions and solutions developed during the MS1 Phase.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.1.3.3', 'F.1.3.3', 'F', 1, 'Objectives', 'MS2 Phase objectives', 'DOCS', 'Through the different MS2 tests, teams must demonstrate that their prototype is not only theoretically well-conceived, but also effectively built, safe, functional and competitive in a real motorsport environment.', 'process', 'required', 'ms1', null, true, '[]'::jsonb),
  ('F.2.1.1', 'F.2.1.1', 'F', 2, 'Phases Of The Competition', 'MS1 Milestones', 'DOCS', 'The MotoStudent Phase 1 (MS1) is structured as a sequence of project milestones intended to guide teams through the development of their prototype and its associated project. Each milestone evaluates a specific aspect of the project development, including team organization, engineering design, innovation, technical documentation, economic viability, communication and marketing.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.2.1.2', 'F.2.1.2', 'F', 2, 'Phases Of The Competition', 'MS1 Milestones', 'DOCS', 'The MS1 Phase is divided into the following milestones:
- MS1 1st milestone: Team plan.
- MS1 2nd milestone: Product definition.
- MS1 3rd milestone: Innovation.
- MS1 4th milestone: Prototype CAD and drawings.
- MS1 5th milestone: Economical plan.
- MS1 6th milestone: Pitch presentation.
- MS1 7th milestone: Final event presentation.', 'process', 'info', 'ms1', null, false, '[]'::jsonb),
  ('F.2.2.1', 'F.2.2.1', 'F', 2, 'Phases Of The Competition', 'MSE Deliveries', 'DOCS', 'Teams competing in the MotoStudent Electric (MSE) category must complete the following additional technical deliveries in order to verify the electrical design and safety compliance before the Final Event:
- MSE 1st delivery: Electric and battery pack scheme.
- MSE 2nd delivery: Electrical precheck.', 'process', 'required', 'ms1', null, true, '[]'::jsonb),
  ('F.3.1.1', 'F.3.1.1', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must provide a clear and structured overview of the entire milestone submission.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.1.2', 'F.3.1.2', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 1: Executive abstract', 'DOCS', 'Its objective is to allow the jury to understand, in a very short time, the key aspects of the team, its organization, the main project objectives and the overall development strategy for the MotoStudent edition.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.1.3', 'F.3.1.3', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must synthesize the most relevant information contained in the following sections of this milestone, including:
- The purpose and motivation of the team.
- The structure and organization of the team.
- The main goals of the project, including their main indicators where applicable
- The general development timeline, the main project milestones and their overall feasibility
- The main decision-making and responsibility structure of the team', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.1.4', 'F.3.1.4', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must be written in a clear, structured and professional way, focusing on the key elements of the project rather than detailed explanations.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.1.5', 'F.3.1.5', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 1: Executive abstract', 'DOCS', 'The recommended length of the Executive Abstract is approximately one page and must not exceed two pages.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.1.6', 'F.3.1.6', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must prioritize clarity and synthesis of the project rather than detailed technical explanations, which should be developed in the subsequent sections.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.2.1', 'F.3.2.1', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 2: Team structure', 'DOCS', 'The objective of this section is to explain the organizational structure of the team and how the work is distributed among its members.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.2.2', 'F.3.2.2', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 2: Team structure', 'DOCS', 'The team must describe the different departments or functional areas of the project (for example: engineering, manufacturing, electronics, marketing, management, etc.), their responsibilities and how they interact with each other.', 'process', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.2.3', 'F.3.2.3', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 2: Team structure', 'DOCS', 'The team must also explain how decisions are taken within the project, including the decision-making structure and coordination between departments.', 'process', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.2.4', 'F.3.2.4', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 2: Team structure', 'DOCS', 'Teams are encouraged to briefly present the academic background of the members in order to show the multidisciplinary nature of the project.', 'process', 'recommended', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.3.1', 'F.3.3.1', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 3: Team goals', 'DOCS', 'This section must define the main objectives that the team intends to achieve during the current MotoStudent edition.', 'process', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.3.2', 'F.3.3.2', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 3: Team goals', 'DOCS', 'The goals must be clear, realistic and measurable and must contribute to the successful development of the project.', 'process', 'required', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.3.3', 'F.3.3.3', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 3: Team goals', 'DOCS', 'Goals should not only focus on performance results but also on relevant project aspects such as engineering development, reliability, innovation, prototype completion, team organization or communication.', 'process', 'recommended', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.3.4', 'F.3.3.4', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 3: Team goals', 'DOCS', 'Each goal must include:
- A short description of the objective.
- A measurable indicator allowing progress tracking.
- The responsible department or team member.
- An estimated timeframe for completion.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.3.5', 'F.3.3.5', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 3: Team goals', 'DOCS', 'Goals must be presented in a structured table format in order to facilitate tracking and evaluation.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.4.1', 'F.3.4.1', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 4: Milestones, deliveries and project timeline', 'DOCS', 'This section must present the main development phases of the team during the competition.', 'process', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.4.2', 'F.3.4.2', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 4: Milestones, deliveries and project timeline', 'DOCS', 'The team must include a time-driven project chart (for example a Gantt chart) showing the main project phases and their relation with the official MotoStudent milestones and deliveries.', 'deliverable', 'required', 'ms1', 'MS1-1', true, '[]'::jsonb),
  ('F.3.4.3', 'F.3.4.3', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 4: Milestones, deliveries and project timeline', 'DOCS', 'The timeline should include the key phases of prototype development such as:
- Concept and design
- Engineering development
- Manufacturing
- Assembly
- Testing and validation
- Preparation for the Final Event', 'process', 'recommended', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.4.4', 'F.3.4.4', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Section 4: Milestones, deliveries and project timeline', 'DOCS', 'It is recommended that the team defines internal review points in order to monitor project progress and detect possible delays or risks in advance.', 'process', 'recommended', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.5.1', 'F.3.5.1', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Evaluation and Scoring', 'DOCS', 'The maximum score for the 1st milestone is 75 points.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.5.2', 'F.3.5.2', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Evaluation and Scoring', 'DOCS', 'The milestone will be evaluated as a whole, considering the clarity, coherence and overall quality of the submission.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.5.3', 'F.3.5.3', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Evaluation and Scoring', 'DOCS', 'Although teams are free to structure their submission as they consider appropriate, the evaluation will consider several key dimensions of the project.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.5.4', 'F.3.5.4', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Evaluation and Scoring', 'DOCS', 'The evaluation will consider several key dimensions of the project. The maximum weight of each dimension and the aspects that may be considered by the jury include:
1) Team purpose and project vision (maximum 5 points)
- Clarity of the team’s purpose and motivation.
- Clarity and coherence of the project objectives.
2) Team structure and organization (maximum 20 points)
- Definition and clarity of the team structure.
- Coherence between team composition and project needs.
- Explanation of the decision-making process.
- Definition of responsibilities for each organizational unit.
- Overall management and coordination of the team.
3) Definition and quality of project goals (maximum 25 points)
- Precision and clarity of the defined goals.
- Presence of measurable indicators to evaluate progress.
- Alignment between goals and team capabilities.
- Feasibility of the goals and supporting reasoning.
- Definition of timeframes for achieving the goals.
- Clear assignment of responsibilities.
4) Project planning, milestones and timeline feasibility (maximum 25 points)
- Existence of a structured project timeline (e.g., Gantt chart).
- Integration of MotoStudent official milestones.
- Definition of internal project milestones.
- Definition of prototype development stages.
- Planning of the different deliveries throughout the competition.', 'process', 'recommended', 'ms1', 'MS1-1', true, '[{"op": "max", "value": 5.0, "unit": "points"}, {"op": "max", "value": 20.0, "unit": "points"}, {"op": "max", "value": 25.0, "unit": "points"}, {"op": "max", "value": 25.0, "unit": "points"}]'::jsonb),
  ('F.3.5.5', 'F.3.5.5', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Evaluation and Scoring', 'DOCS', 'These values represent the relative weight of each dimension in the evaluation but do not imply that the milestone will be assessed strictly by sections.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.3.5.6', 'F.3.5.6', 'F', 3, 'Ms1 1St Milestone, Team Plan', 'Evaluation and Scoring', 'DOCS', 'The jury will assign a global score up to the maximum value of the milestone based on the overall quality and coherence of the project.', 'process', 'info', 'ms1', 'MS1-1', false, '[]'::jsonb),
  ('F.4.1.1', 'F.4.1.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Milestone preamble', 'DOCS', 'The objective of this milestone is to define the conceptual and engineering foundations of the motorcycle prototype that will be developed for the MotoStudent competition.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.1.2', 'F.4.1.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Milestone preamble', 'DOCS', 'The prototype to be developed shall be a racing motorcycle powered either by the standardized combustion engine or by the electric powertrain provided by the Competition Organization, depending on the category in which the team participates.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.1.3', 'F.4.1.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Milestone preamble', 'DOCS', 'Since the vehicle will be operated by a rider, the design must consider appropriate structural loads, ergonomics, safety margins and correct rider integration.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.1.4', 'F.4.1.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Milestone preamble', 'DOCS', 'The milestone must demonstrate that the team has defined a technically feasible design concept supported by engineering analysis and technical reasoning.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.2.1', 'F.4.2.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must provide a clear and concise overview of the proposed prototype concept and the main engineering decisions taken by the team.', 'deliverable', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.2.2', 'F.4.2.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 1: Executive abstract', 'DOCS', 'The objective of this section is to allow the jury to quickly understand the design philosophy of the prototype and the rationale behind the most relevant technical choices.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.2.3', 'F.4.2.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must synthesize the key engineering aspects of the milestone and provide a clear overview of the proposed prototype definition. In particular, it should summarize:
- The general concept of the motorcycle prototype and the main functional architecture of the vehicle
- The main design alternatives considered and the justification of the selected technical solutions
- The most relevant risk, safety and reliability considerations identified during the design phase (e.g. main conclusions from the FMEA)
- The overall make/buy strategy and manufacturing approach adopted by the team
- The proposed prototype layout and the integration of the rider within the vehicle design
- The main project requirements, design criteria and main load assumptions considered for the design of the prototype and the most relevant structural or performance results obtained during the engineering analysis
- The main engineering results and conclusions supporting the proposed prototype definition', 'deliverable', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.2.4', 'F.4.2.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract should demonstrate that the team has developed a coherent prototype concept supported by sound engineering reasoning and consistent design assumptions.', 'deliverable', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.2.5', 'F.4.2.5', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 1: Executive abstract', 'DOCS', 'As part of the Executive Abstract submission, each team must include a Prototype Characteristics Sheet summarizing the main technical parameters of the proposed prototype. Its purpose is to provide with a clear and structured overview of the main technical characteristics of the prototype. At a minimum, the Prototype Characteristics Sheet must include the following information:
- Category of participation (MotoStudent Electric or MotoStudent eFuel)
- University and team name
- Prototype wheelbase
- Estimated total vehicle weight
- Powertrain type and main characteristics
- Battery characteristics (Electric category) or fuel system configuration (eFuel category)
- Front and rear suspension type
- Front and rear brake system type
- Wheel and tyre dimensions
- Main frame concept and material
- Estimated maximum power or performance target
- Rider position concept and general prototype layout Teams may include additional technical parameters if they consider them relevant to better describe the prototype. The information provided in this sheet must be consistent with the rest of the documentation submitted in the milestone.', 'deliverable', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.2.6', 'F.4.2.6', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must remain concise while clearly summarizing the most relevant aspects of the proposed design and its main engineering conclusions. As a general guideline, the Executive Abstract should normally range between three and four pages and must not exceed four pages.', 'deliverable', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.3.1', 'F.4.3.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 2: Functional systems trade-off', 'DOCS', 'The objective of this section is to explain the main design concepts selected for the different functional systems of the prototype.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.3.2', 'F.4.3.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 2: Functional systems trade-off', 'DOCS', 'Teams must compare possible design alternatives and justify the selected solution.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.3.3', 'F.4.3.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 2: Functional systems trade-off', 'DOCS', 'The analysis may include references to existing motorcycles, motorsport applications, previous MotoStudent prototypes or other relevant engineering references.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.3.4', 'F.4.3.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 2: Functional systems trade-off', 'DOCS', 'The advantages, disadvantages and expected impact of the selected solutions should be clearly discussed.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.4.1', 'F.4.4.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 3: Failure Modes and Effect Analysis (FMEA)', 'DOCS', 'The objective of this section is to identify possible failure modes of the main systems of the prototype and evaluate their potential consequences.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.4.2', 'F.4.4.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 3: Failure Modes and Effect Analysis (FMEA)', 'DOCS', 'The analysis should identify possible failure modes, their causes, their effects and possible mitigation actions.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.4.3', 'F.4.4.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 3: Failure Modes and Effect Analysis (FMEA)', 'DOCS', 'The FMEA should demonstrate that the team has considered reliability, safety and risk mitigation aspects during the design phase.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.5.1', 'F.4.5.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 4: Make / Buy analysis', 'DOCS', 'This section must describe which elements or systems of the prototype are designed and manufactured by the team and which components are sourced externally.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.5.2', 'F.4.5.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 4: Make / Buy analysis', 'DOCS', 'Components classified as "make" are those whose design and/or manufacturing has been carried out by the team. Minor adaptations or simple assembly of commercial components shall not be considered as "make".', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.5.3', 'F.4.5.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 4: Make / Buy analysis', 'DOCS', 'Components classified as "buy" are those obtained from suppliers or commercial products without significant modification of their original design.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.5.4', 'F.4.5.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 4: Make / Buy analysis', 'DOCS', 'Teams must clearly identify the main systems of the prototype (e.g. frame, swingarm, suspension elements, braking system, electronics, fairing, etc.) and specify for each of them whether they are classified as make or buy.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.5.5', 'F.4.5.5', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 4: Make / Buy analysis', 'DOCS', 'The team should briefly justify the make/buy decision, considering aspects such as technical capability, manufacturing resources, reliability or project strategy.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.5.6', 'F.4.5.6', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 4: Make / Buy analysis', 'DOCS', 'If a component from a previous MotoStudent edition is reused, it must be clearly identified. The reuse and evolution of components between editions is considered a natural part of the engineering development process and is therefore allowed and encouraged. When a component is reused, its make/buy classification must remain consistent with its original nature. Minor adaptations or improvements to a previously purchased component shall not change its classification to "make", and components originally designed and manufactured by the team shall remain classified as "make".', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.6.1', 'F.4.6.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 5: Proposed design', 'DOCS', 'The objective of this section is to provide a clear visual and geometric representation of the proposed prototype design.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.6.2', 'F.4.6.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 5: Proposed design', 'DOCS', 'The prototype architecture and layout must be presented using both 2D and 3D representations.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.6.3', 'F.4.6.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 5: Proposed design', 'DOCS', 'The design must include at least the following views of the prototype without fairings:
- front view
- side view
- top view', 'deliverable', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.6.4', 'F.4.6.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 5: Proposed design', 'DOCS', 'The rider must be represented in the design in order to demonstrate correct ergonomic integration with the vehicle. The main rider dimensions used in the design (such as total height, arm reach or leg dimensions) should be indicated.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.6.5', 'F.4.6.5', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 5: Proposed design', 'DOCS', 'The design must show the main geometric and dimensional constraints of the prototype and should include key parameters such as main dimensions, estimated centre of gravity (CoG) and expected minimum prototype weight.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.6.6', 'F.4.6.6', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 5: Proposed design', 'DOCS', 'The inclusion of the same views with the fairing installed is highly recommended to help understand the final appearance and packaging of the prototype.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.7.1', 'F.4.7.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 6: Loads definitions', 'DOCS', 'The objective of this section is to define the main load cases that the prototype is expected to withstand during the MotoStudent Final Event. These load cases will form the basis for the structural design and validation of the vehicle.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.7.2', 'F.4.7.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 6: Loads definitions', 'DOCS', 'Teams should justify the selected loads using engineering estimations, simplified analytical calculations or numerical simulations where appropriate. If available, empirical data or measurements obtained during testing activities (for example at MotorLand Aragón or similar circuits) may also be used to support the assumptions.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.7.3', 'F.4.7.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 6: Loads definitions', 'DOCS', 'The following load cases must be considered in the design of the prototype:
- Static verification loads
- Maximum braking loads
- Maximum acceleration loads
- Cornering loads
- Turning loads (e.g. rapid left-right transitions such as chicanes)
- Aerodynamic loads', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.7.4', 'F.4.7.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 6: Loads definitions', 'DOCS', 'The defined loads must include the rider mass in the calculations and must represent realistic operating conditions of the prototype during riding.', 'deliverable', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.8.1', 'F.4.8.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 7: Structural calculations', 'DOCS', 'The objective of this section is to evaluate the structural behaviour of the main components of the prototype under the load cases defined in the previous section.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.8.2', 'F.4.8.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 7: Structural calculations', 'DOCS', 'The analysis must assess the stresses and deformations of the structural parts of the vehicle in order to verify that the design can safely withstand the expected operating loads.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.8.3', 'F.4.8.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 7: Structural calculations', 'DOCS', 'Finite element simulations are highly recommended for complex components. For simpler elements, analytical calculations may be used where appropriate.', 'process', 'recommended', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.8.4', 'F.4.8.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 7: Structural calculations', 'DOCS', 'At minimum, the following structural components must be evaluated:
- frame
- swingarm
- subframe', 'process', 'required', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.8.5', 'F.4.8.5', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 7: Structural calculations', 'DOCS', 'If a purchased component is structurally critical within the vehicle architecture, its structural behaviour must also be justified by calculation or engineering analysis.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.8.6', 'F.4.8.6', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Section 7: Structural calculations', 'DOCS', 'Safety margins must be clearly defined and justified in order to demonstrate the structural integrity of the prototype.', 'process', 'required', 'ms1', 'MS1-2', true, '[]'::jsonb),
  ('F.4.9.1', 'F.4.9.1', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Evaluation and scoring', 'DOCS', 'The maximum score for the 2nd milestone is 100 points.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.9.2', 'F.4.9.2', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Evaluation and scoring', 'DOCS', 'The milestone will be evaluated as a whole, considering the overall technical coherence, engineering reasoning and quality of the proposed prototype definition.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.9.3', 'F.4.9.3', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Evaluation and scoring', 'DOCS', 'Although teams are free to structure their submission as they consider appropriate, the evaluation will consider several key dimensions of the project.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.9.4', 'F.4.9.4', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Evaluation and scoring', 'DOCS', 'The evaluation will consider several key engineering dimensions of the project. The maximum weight of each dimension and the aspects that may be considered by the jury include:
1) Engineering concept and system design justification (maximum 10 points)
- Identification of the different technical solutions considered for the main systems of the prototype.
- Analysis of the advantages and disadvantages of the selected solutions.
- Comparison with reference solutions from the market, motorsport or other engineering applications where relevant.
- Technical justification of the selected system architecture.
- Consideration of environmental impact when evaluating alternative solutions.
2) Failure analysis and risk awareness – FMEA (maximum 15 points)
- Completeness of the Failure Modes and Effects Analysis (FMEA).
- Accuracy in identifying possible failure modes and their consequences.
- Correct evaluation of occurrence and detection rankings.
- Definition and consistency of risk priority numbers (RPN).
- Identification of the systems or components requiring special attention.
- Definition and effectiveness of proposed risk reduction actions.
3) Make / Buy strategy and manufacturing approach (maximum 10 points)
- Completeness and clarity of the list of main prototype components.
- Correct classification of elements as designed/manufactured by the team or sourced externally.
- Engineering reasoning behind the make/buy decisions.
- Coherence between the manufacturing strategy and the capabilities of the team.
4) Prototype architecture and design definition (maximum 20 points)
- Clarity and completeness of the proposed prototype architecture.
- Quality and coherence of the 2D and 3D design representations.
- Definition of geometric constraints and main vehicle dimensions.
- Integration and ergonomic positioning of the rider.
5) Definition of load cases and engineering assumptions (maximum 25 points)
- Definition of relevant static and dynamic load cases.
- Consideration of braking, acceleration, cornering and aerodynamic loads.
- Quality of the engineering assumptions used in the calculations.
- Inclusion of the rider mass in the load definition.
- Coherence of the load estimations with realistic vehicle behaviour.
6) Structural analysis and validation (maximum 20 points)
- Structural analysis of the main components of the prototype.
- Evaluation of stresses and deformations under the defined load cases.
- Strength and stiffness calculations or simulations.
- Definition and justification of appropriate safety margins.', 'process', 'recommended', 'ms1', 'MS1-2', true, '[{"op": "max", "value": 10.0, "unit": "points"}, {"op": "max", "value": 15.0, "unit": "points"}, {"op": "max", "value": 10.0, "unit": "points"}, {"op": "max", "value": 20.0, "unit": "points"}]'::jsonb),
  ('F.4.9.5', 'F.4.9.5', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Evaluation and scoring', 'DOCS', 'These values represent the approximate weight of each dimension but do not imply that the milestone will be evaluated strictly by sections.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.4.9.6', 'F.4.9.6', 'F', 4, 'Ms1 2Nd Milestone, Product Definition', 'Evaluation and scoring', 'DOCS', 'The jury will assign a global score based on the overall technical quality, engineering reasoning and feasibility of the proposed design.', 'process', 'info', 'ms1', 'MS1-2', false, '[]'::jsonb),
  ('F.5.1.1', 'F.5.1.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'Innovation is understood as the development or implementation of a new or improved solution that provides a measurable technical or process-related benefit compared to an existing approach.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.1.2', 'F.5.1.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'The objective of this milestone is to encourage teams to identify a relevant technical or process-related challenge and to develop an innovative solution that improves the prototype, the development process or the understanding of the system.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.1.3', 'F.5.1.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'The innovation may involve a new technical solution, an improvement of an existing system, a new design methodology, a manufacturing process improvement or a new approach to solving an engineering problem.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.1.4', 'F.5.1.4', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'The innovation must be supported by a structured development process including problem identification, concept exploration, development phases, testing and evaluation of results.', 'process', 'required', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.1.5', 'F.5.1.5', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'The innovation presented in this milestone must be implemented in the prototype or in its development process and must be available to be demonstrated during the Final Event. Concepts that remain only at proposal, rendering, simulation or theoretical intention level, without real implementation, shall not be considered sufficient for the purposes of this milestone.', 'process', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.1.6', 'F.5.1.6', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'The expected impact of the innovation should be supported by quantitative or qualitative evidence such as simulations, experimental tests, comparisons with baseline solutions or engineering analysis.', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.1.7', 'F.5.1.7', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'Innovation in motorsport engineering is often the result of questioning established solutions and exploring new approaches. Teams are therefore encouraged to approach this milestone with creativity, technical reasoning and a clear focus on measurable improvements.', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.1.8', 'F.5.1.8', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Milestone preamble', 'DOCS', 'The jury will evaluate the innovation primarily based on the engineering process followed, the technical justification of the proposed solution and the evidence supporting its impact, rather than solely on the novelty of the idea itself.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.2.1', 'F.5.2.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 1: Executive Abstract', 'DOCS', 'The Executive Abstract must provide a clear and concise overview of the innovation project developed by the team.', 'deliverable', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.2.3', 'F.5.2.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 1: Executive Abstract', 'DOCS', 'The objective of this section is to allow the jury to quickly understand the problem addressed, the proposed innovative solution, the development methodology followed and the expected impact on the prototype.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.2.3#2', 'F.5.2.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 1: Executive Abstract', 'DOCS', 'The Executive Abstract must summarize the key aspects of the milestone, including:
- The problem or limitation identified by the team
- The objective of the innovation
- The proposed concept or solution and main alternative solutions considered and the justification of the selected concept
- The development approach followed
- The implemented Proof of Concept and the main results obtained, including the comparison between expected and achieved results
- The main resources required
- The expected improvement and its engineering justification', 'deliverable', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.2.4', 'F.5.2.4', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 1: Executive Abstract', 'DOCS', 'The Executive Abstract should demonstrate that the innovation is supported by sound engineering reasoning and a structured development process.', 'deliverable', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.2.5', 'F.5.2.5', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 1: Executive Abstract', 'DOCS', 'The Executive Abstract should be proportional to the complexity of the innovation project and sufficiently detailed to clearly summarize the most relevant aspects of the work carried out. Teams are encouraged to keep this section concise and focused on the key engineering aspects of the innovation. The Executive Abstract must not exceed 4 pages.', 'deliverable', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.3.1', 'F.5.3.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 2: Starting point and innovation objective', 'DOCS', 'The objective of this section is to explain the origin of the innovation and the problem that the team intends to solve.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.3.2', 'F.5.3.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 2: Starting point and innovation objective', 'DOCS', 'Teams must clearly describe:
- the initial situation or limitation identified
- the engineering problem to be addressed
- the expected improvement or benefit
- the alignment of the innovation with the team’s project goals', 'process', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.4.1', 'F.5.4.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 3: Solution exploration and alternatives', 'DOCS', 'The objective of this section is to analyse the different possible solutions considered by the team before selecting the final innovation concept.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.4.2', 'F.5.4.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 3: Solution exploration and alternatives', 'DOCS', 'The analysis may include:
- existing solutions available in the market or motorsport
- alternative technical approaches
- advantages and disadvantages of each option
- justification of the selected concept', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.4.3', 'F.5.4.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 3: Solution exploration and alternatives', 'DOCS', 'If no direct market solution exists, the comparison should include the closest available technological alternatives.', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.4.4', 'F.5.4.4', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 3: Solution exploration and alternatives', 'DOCS', 'The proposed innovation must comply with the MotoStudent Technical Regulations. Solutions that affect regulated safety systems or critical vehicle components must demonstrate full compliance with the applicable rules.', 'process', 'required', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.5.1', 'F.5.5.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 4: Development process', 'DOCS', 'This section must explain the development process followed by the team from the initial concept to the final implementation.', 'process', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.5.2', 'F.5.5.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 4: Development process', 'DOCS', 'The development process should include:
- concept generation and first sketches
- design iterations and decision points
- prototype development phases
- testing activities performed', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.5.3', 'F.5.5.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 4: Development process', 'DOCS', 'It is highly recommended to include a timeline describing the main development milestones of the innovation project (e.g., concept release, design freeze, prototype manufacturing, testing stages). Teams are also encouraged to perform experimental tests or validation activities in order to compare the obtained results with the expected improvement and to demonstrate the effectiveness of the proposed solution.', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.6.1', 'F.5.6.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 5: Proof of Concept (PoC)', 'DOCS', 'The objective of this section is to demonstrate that the proposed innovation works as intended.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.6.2', 'F.5.6.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 5: Proof of Concept (PoC)', 'DOCS', 'The Proof of Concept must present the implemented solution and the tests or evaluations used to validate it.', 'process', 'required', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.6.3', 'F.5.6.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 5: Proof of Concept (PoC)', 'DOCS', 'The PoC should include:
- description of the implemented concept
- visual evidence such as photographs or diagrams
- tests, experiments or validation activities
- comparison between expected and obtained results', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.7.1', 'F.5.7.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 6: Bill of Materials (BOM) and development resources', 'DOCS', 'The objective of this section is to describe the resources required to develop and implement the innovation.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.7.2', 'F.5.7.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 6: Bill of Materials (BOM) and development resources', 'DOCS', 'Teams must include a Bill of Materials (BOM) listing the main components, materials and consumables used during the development of the innovation.', 'deliverable', 'required', 'ms1', 'MS1-3', true, '[]'::jsonb),
  ('F.5.7.3', 'F.5.7.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 6: Bill of Materials (BOM) and development resources', 'DOCS', 'The budget estimation should consider:
- cost of the components included in the BOM
- manufacturing or prototyping costs
- development resources used during the project', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.7.4', 'F.5.7.4', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 6: Bill of Materials (BOM) and development resources', 'DOCS', 'The analysis should demonstrate the relationship between the resources invested and the expected benefit obtained.', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.8.1', 'F.5.8.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 7: Conclusions and future potential', 'DOCS', 'This section must summarize the results of the innovation project.', 'process', 'required', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.8.2', 'F.5.8.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 7: Conclusions and future potential', 'DOCS', 'Teams should evaluate:
- the final improvement obtained
- the real impact of the innovation on the prototype
- possible future developments or improvements', 'process', 'recommended', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.8.3', 'F.5.8.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 7: Conclusions and future potential', 'DOCS', 'The potential applicability of the innovation beyond the current prototype may also be discussed.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.9.1', 'F.5.9.1', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Evaluation and scoring', 'DOCS', 'The maximum score for the 3rd milestone is 150 points.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.9.2', 'F.5.9.2', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Evaluation and scoring', 'DOCS', 'The milestone will be evaluated as a whole, considering the overall coherence of the innovation project, the quality of the engineering reasoning, the development methodology and the demonstrated impact of the proposed innovation.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.9.3', 'F.5.9.3', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Evaluation and scoring', 'DOCS', 'Although teams are free to structure their submission as they consider appropriate, the evaluation will consider several key dimensions of the project. The maximum weight of each dimension and the aspects that may be considered by the jury include:
1) Innovation motivation and problem definition (maximum 10 points)
- Clarity of the identified problem or improvement opportunity.
- Justification of the need for the innovation.
- Alignment between the innovation and the team’s project goals.
2) Analysis of alternatives and solution selection (maximum 20 points)
- Identification of existing solutions or technological alternatives.
- Comparison between possible approaches.
- Justification of the selected concept.
- Compliance of the proposed solution with the MotoStudent technical regulations.
3) Development process and engineering methodology (maximum 55 points)
- Clarity of the development phases.
- Definition of development milestones and project evolution.
- Engineering reasoning behind design decisions.
- Quality of testing activities and validation methods.
- Evidence of iterative development and learning during the project.
4) Proof of Concept and validation of results (maximum 35 points)
- Quality, clarity and level of real implementation of the Proof of Concept.
- Demonstration that the concept works as intended.
- Comparison between expected and obtained results.
- Quality of graphical and technical documentation.
5) Resources, feasibility and development efficiency (maximum 15 points)
- Completeness and clarity of the Bill of Materials (BOM).
- Evaluation of the resources required for the development.
- Balance between development effort and expected benefit.
6) Impact and future potential of the innovation (maximum 15 points)
- Demonstrated or expected impact on the prototype.
- Potential benefits in terms of performance, efficiency, reliability or sustainability.
- Possibilities for future evolution or further development of the concept.', 'process', 'recommended', 'ms1', 'MS1-3', true, '[{"op": "max", "value": 10.0, "unit": "points"}, {"op": "max", "value": 20.0, "unit": "points"}, {"op": "max", "value": 55.0, "unit": "points"}, {"op": "max", "value": 35.0, "unit": "points"}]'::jsonb),
  ('F.5.9.4', 'F.5.9.4', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Evaluation and scoring', 'DOCS', 'These values represent the approximate weight of each dimension but do not imply that the milestone will be evaluated strictly by sections.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.5.8.5', 'F.5.8.5', 'F', 5, 'Ms1 3Rd Milestone, Innovation', 'Section 7: Conclusions and future potential', 'DOCS', 'The jury will assign a global score based on the overall quality of the innovation project, the clarity of the development process, the robustness of the validation carried out and the demonstrated or expected impact of the innovation on the prototype.', 'process', 'info', 'ms1', 'MS1-3', false, '[]'::jsonb),
  ('F.6.1.1', 'F.6.1.1', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Milestone preamble', 'DOCS', 'The objective of this milestone is to demonstrate that the prototype design has reached a sufficient level of technical maturity to allow its correct manufacturing and integration.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.1.2', 'F.6.1.2', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Milestone preamble', 'DOCS', 'In modern engineering environments, the CAD model represents the digital definition of the product and is the central reference for design, manufacturing and assembly.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.1.3', 'F.6.1.3', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Milestone preamble', 'DOCS', 'This milestone evaluates the quality, structure and clarity of the CAD model as well as the ability of the team to generate professional manufacturing documentation.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.1.4', 'F.6.1.4', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Milestone preamble', 'DOCS', 'The documentation provided must demonstrate that the prototype can be manufactured, assembled and understood by a third party using the information delivered by the team.', 'process', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.2.1', 'F.6.2.1', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must provide a clear overview of the CAD definition of the prototype and the design maturity achieved by the team at this stage of the project.', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.2.2', 'F.6.2.2', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 1: Executive abstract', 'DOCS', 'The objective of this section is to allow the jury to quickly understand the architecture of the CAD model, the design status of the prototype and the approach followed by the team to prepare the manufacturing documentation.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.2.3', 'F.6.2.3', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must synthesize the key aspects of the milestone, including:
- The general architecture of the prototype CAD model
- The design maturity of the main structural components
- The modelling strategy used by the team
- The structure of the assemblies and subsystems
- The documentation strategy followed to support manufacturing and assembly
- The main conclusions regarding the completeness, consistency and technical usefulness of the CAD and drawings package', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.2.4', 'F.6.2.4', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract should demonstrate that the team has developed a structured and coherent digital definition of the prototype.', 'deliverable', 'recommended', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.2.5', 'F.6.2.5', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 1: Executive abstract', 'DOCS', 'The length of the Executive Abstract should be proportional to the complexity of the prototype design and sufficient to clearly summarize the most relevant aspects of the CAD model and documentation.', 'deliverable', 'recommended', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.2.6', 'F.6.2.6', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must not exceed 3 pages.', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.3.1', 'F.6.3.1', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 2: Prototype CAD model', 'DOCS', 'The objective of this section is to deliver the latest CAD definition of the structural elements of the prototype.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.3.2', 'F.6.3.2', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 2: Prototype CAD model', 'DOCS', 'This section must be delivered as a single 3D file in. STEP format.', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.3.3', 'F.6.3.3', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 2: Prototype CAD model', 'DOCS', 'The CAD submission must include a 3D CAD assembly of the motorcycle containing, as a minimum, the main structural components designed by the team. The assembly shall include at least the following components in their design position:
- frame
- subframe
- swingarm These components must be modelled with a level of detail sufficient to identify their geometry, interfaces, and structural concept.', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.3.4', 'F.6.3.4', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 2: Prototype CAD model', 'DOCS', 'The CAD model should represent the current design status of the prototype and demonstrate an appropriate level of engineering definition.', 'process', 'recommended', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.3.5', 'F.6.3.5', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 2: Prototype CAD model', 'DOCS', 'The CAD model must be clean, coherent and free of unnecessary elements that could complicate its interpretation.', 'process', 'required', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.4.1', 'F.6.4.1', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 3: Model tree and CAD structure', 'DOCS', 'The objective of this section is to present the internal structure of the CAD model and the whole organization of the assemblies, subassemblies and parts. The model tree must clearly show the hierarchical structure of the prototype design, including the relationships between systems, assemblies and individual parts. Each assembly and part must include an alphanumeric reference and a clear name. A part or subassembly may appear more than once if it is used in different assemblies. Figure 43 - Example of a model tree', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.4.2', 'F.6.4.2', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 3: Model tree and CAD structure', 'DOCS', 'The nomenclature for parts and assemblies must follow a consistent alphanumeric reference system defined by the team. Each element of the prototype must be uniquely identified by an alphanumeric code following the general structure: SS-AA-SSS-PPP Where:
- SS = System
- AA = Assembly
- SSS = Subassembly
- PPP = Part This reference must be used consistently across the CAD model, model tree and drawings.
- System: The whole prototype must be broken down into the following main 7 systems:
- 01 – Structure
- 02 – Powertrain
- 03 – Suspensions
- 04 – Wheels
- 05 – Brakes
- 06 – Aerodynamics
- 07 – Others Teams may further divide these systems into assemblies and subassemblies according to their design structure. The hierarchical structure of the product must follow the following levels:
- System
- Assembly: Level set immediately below Systems.
- Subassembly: Level set immediately below Assemblies.
- Part: The number of the art pertaining the subassembly. Numbering must be ascending. For subassemblies, the part number must be 000. Each level must clearly represent the functional and structural organization of the prototype.', 'process', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.4.3', 'F.6.4.3', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 3: Model tree and CAD structure', 'DOCS', 'The numbering of parts must be sequential within each subassembly. When an element corresponds to a subassembly rather than a single part, the part number must be defined as "000" (e.g. 01-01-002-000 → Subassembly; 01-01-002-001 → Part inside that subassembly). Code: Picture 44 - Drawings nomenclature', 'process', 'required', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.5.1', 'F.6.5.1', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'The objective of this section is to demonstrate that the team is capable of producing professional manufacturing drawings derived from the CAD model.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.5.2', 'F.6.5.2', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'Teams are not required to provide drawings for every component of the prototype.', 'process', 'info', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.5.3', 'F.6.5.3', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'Instead, the team must provide representative examples of manufacturing documentation that demonstrate the correct application of engineering drawing standards.', 'process', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.5.4', 'F.6.5.4', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'At least, the following drawings must be delivered:
- Complete prototype drawing (front, side, top and isometric views)
- Rear suspension assembly drawing
- Top triple clamp part drawing', 'process', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.5.5', 'F.6.5.5', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'Assembly drawings must include a Bill of Materials (BOM) identifying the parts included in the assembly.', 'deliverable', 'required', 'ms1', 'MS1-4', true, '[]'::jsonb),
  ('F.6.5.6', 'F.6.5.6', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'Parts and subassemblies must be referenced using balloons.', 'process', 'required', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.5.7', 'F.6.5.7', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'Commercial components must also be identified in the Bill of Materials.', 'process', 'required', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.5.8', 'F.6.5.8', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Section 4: Manufacturing drawings', 'DOCS', 'Drawings should include the necessary information to support manufacturing and assembly, such as dimensions, materials, tolerances and relevant notes when applicable.', 'process', 'recommended', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.6.1', 'F.6.6.1', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Evaluation and scoring', 'DOCS', 'The maximum score for this milestone is 60 points.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.6.2', 'F.6.6.2', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Evaluation and scoring', 'DOCS', 'The milestone will be evaluated as a whole, considering the overall quality, structure and engineering maturity of the CAD definition and the manufacturing documentation.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.6.3', 'F.6.6.3', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Evaluation and scoring', 'DOCS', 'Although teams are free to structure their submission as they consider appropriate, the evaluation will consider several key dimensions of the project. The maximum weight of each dimension and the aspects that may be considered by the jury include:
1) CAD model definition and engineering maturity (maximum 10 points)
- Correct delivery format of the CAD model.
- Level of definition of the structural components.
- Coherence and cleanliness of the model.
2) Model tree organization and digital structure (maximum 20 points)
- Correct application of the nomenclature system.
- Completeness of the assemblies and subassemblies.
- Inclusion of the relevant parts within the model structure.
- Clarity of the relationships between systems and assemblies.
3) Manufacturing drawings and documentation quality (maximum 30 points)
- Correct application of engineering drawing standards.
- Inclusion of relevant dimensions.
- Definition of materials and relevant technical information.
- Correct use of Bill of Materials and balloons.
- Overall clarity and usability of the documentation for manufacturing.', 'deliverable', 'recommended', 'ms1', 'MS1-4', true, '[{"op": "max", "value": 10.0, "unit": "points"}, {"op": "max", "value": 20.0, "unit": "points"}, {"op": "max", "value": 30.0, "unit": "points"}]'::jsonb),
  ('F.6.6.4', 'F.6.6.4', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Evaluation and scoring', 'DOCS', 'These values represent the approximate weight of each dimension but do not imply that the milestone will be evaluated strictly by sections.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.6.6.5', 'F.6.6.5', 'F', 6, 'Ms1 4Th Delivery, Prototype Cad And Drawings', 'Evaluation and scoring', 'DOCS', 'The jury will assign a global score based on the overall quality of the CAD definition, the clarity of the model structure and the professional level of the manufacturing documentation.', 'process', 'info', 'ms1', 'MS1-4', false, '[]'::jsonb),
  ('F.7.1.1', 'F.7.1.1', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'Engineering projects are not only defined by their technical performance but also by their economic feasibility. Every engineering decision has an associated economic impact that must be understood and justified.', 'process', 'required', 'ms1', 'MS1-5', false, '[]'::jsonb),
  ('F.7.1.2', 'F.7.1.2', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'The objective of this milestone is to introduce teams to the economic dimension of engineering projects, encouraging them to analyse costs, resources and financial sustainability as part of the project development process.', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb),
  ('F.7.1.3', 'F.7.1.3', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'Teams are expected to demonstrate a structured and transparent approach to the economic management of the project, including cost tracking, budgeting and financial planning.', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb),
  ('F.7.1.4', 'F.7.1.4', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'The purpose of this milestone is not to reward teams that achieve the lowest costs or the highest financial results, but to evaluate the reasoning process, justification and understanding of the economic implications of their engineering decisions.', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb),
  ('F.7.1.5', 'F.7.1.5', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'This milestone also encourages multidisciplinary collaboration within the team, involving members with backgrounds in engineering, economics, management or related fields.', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb),
  ('F.7.1.6', 'F.7.1.6', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'Teams participating in MotoStudent may operate under different economic conditions and levels of available resources. For this reason, this milestone does not aim to compare the absolute financial capacity of teams, but rather to evaluate their ability to understand, manage and justify the economic implications of their engineering decisions. The evaluation will therefore focus on the transparency of the economic analysis, the identification of the main cost drivers and the coherence between technical decisions and their economic impact on the project.', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb),
  ('F.7.1.7', 'F.7.1.7', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Milestone preamble', 'DOCS', 'All economic values presented in this milestone must be expressed in euros (€). If the original transaction was performed in another currency, the value must be converted to euros using a reasonable exchange rate, which must be indicated by the team. The same exchange rate must be used consistently throughout the entire submission.', 'process', 'required', 'ms1', 'MS1-5', true, '[]'::jsonb),
  ('F.7.2.1', 'F.7.2.1', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Section 1: Executive abstract', 'DOCS', 'The Executive Abstract must provide a clear overview of the economic situation of the project and the methodology used by the team to analyse and manage the project’s financial resources.', 'deliverable', 'required', 'ms1', 'MS1-5', true, '[]'::jsonb),
