  ('F.7.5.6', 'F.7.5.6', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Section 4: Prototype value', 'DOCS', 'If a component has been purchased from a supplier, manufacturing hours must be considered zero, as the cost of the component already includes the associated manufacturing effort.', 'process', 'required', 'ms1', 'MS1-5', false, '[]'::jsonb),
