  ('F.7.5.8', 'F.7.5.8', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Section 4: Prototype value', 'DOCS', 'If a component has been donated by a sponsor, it must be accounted as a purchased component using its estimated market value.', 'process', 'required', 'ms1', 'MS1-5', false, '[]'::jsonb),
