  ('F.7.7.1', 'F.7.7.1', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Section 6: Future budget', 'DOCS', 'The objective of this section is to estimate the financial resources required from the milestone submission date until the end of the competition (including also the costs that may arise after the competition, e.g., traveling back to your hometown).', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb),
