  ('F.7.9.4', 'F.7.9.4', 'F', 7, 'Ms1 5Th Milestone, Economical Plan', 'Evaluation and scoring', 'DOCS', 'These values represent the approximate weight of each dimension but do not imply that the milestone will be evaluated strictly by sections.', 'process', 'info', 'ms1', 'MS1-5', false, '[]'::jsonb)
