-- Spec sheet. Pass/fail is NEVER stored — read it from the spec_verdicts view.
-- 'Competition number' is a range (1-99), which the view reports as unmeasured
-- by design: a range needs a human to read it, not a comparison.
insert into specs (season_id, parameter, comparator, target, target_text,
                   unit, clause_key, condition, sort_order)
select s.id, 'Minimum total weight, no rider', 'min', 85,
       null, 'kg',
       c.clause_key, 'Including all fluids needed for normal operation. Ballast allowed (B.2.2.3) but must be declared and bolted.', 0
from seasons s
left join clauses c on c.clause_key = 'B.2.2.1'
where s.label = '2026/27'
  and not exists (select 1 from specs x
                  where x.season_id = s.id and x.parameter = 'Minimum total weight, no rider');

